(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("hermes-stobaeus-e", [{"sp": "HDR", "t": "Ἑρμοῦ ἐκ τῶν Στοβαίου"}, {"sp": "SEC", "t": "I", "st": "1.1"}, {"sp": "N", "t": "Θεὸν νοῆσαι μὲν χαλεπόν, φράσαι δὲ ἀδύνατον ᾧ καὶ νοῆσαι δυνατόν. τὸ γὰρ ἀσώματον σώματι σημῆναι ἀδύνατον, καὶ τὸ τέλειον τῷ ἀτελεῖ καταλαβέσθαι οὐ δυνατόν, καὶ τὸ ἀίδιον τῷ ὀλιγοχρονίῳ συγγενέσθαι δύσκολον. τὸ μὲν γὰρ ἀεί ἐστι, τὸ δὲ παρέρχεται· καὶ τὸ μὲν ἀληθές ἐστι, τὸ δὲ ὑπὸ φαντασίας σκιάζεται. ὅσον οὖν τὸ ἀσθενέστερον τοῦ ἰσχυροτέρου καὶ τὸ ἔλαττον τοῦ κρείττονος διέστηκε, τοσοῦτον τὸ θνητὸν τοῦ θείου.", "st": "1.1"}, {"sp": "N", "t": "ἡ δὲ μέση τούτων διάστασις ἀμαυροῖ τὴν τοῦ καλοῦ θέαν. ὀφθαλμοῖς μὲν γὰρ τὰ σώματα θεατά, γλώττῃ δὲ τὰ ὁρατὰ λεκτά· τὸ δὲ ἀσώματον καὶ ἀφανὲς καὶ ἀσχημάτιστον καὶ μὴ ἐξ ὕλης ὑποκείμενον ὑπὸ τῶν ἡμετέρων αἰσθήσεων καταληφθῆναι οὐ δύναται. ἐννοοῦμαι, ὦ Τάτ, ἐννοοῦμαι ὃ ἐξειπεῖν ἀδύνατον· τοῦτο ἔστιν ὁ θεός.", "st": "1.2"}, {"sp": "SEC", "t": "II A", "st": "2a.1"}, {"sp": "N", "t": "Περὶ ἀληθείας, ὦ Τάτ, οὐκ ἔστι δυνατὸν ἄνθρωπον ὄντα, ζῷον ἀτελές, ἐξ ἀτελῶν συγκείμενον μερῶν, καὶ ἐξ ἀλλοτρίων σωμάτων καὶ πολλῶν τὸ σκῆνος συνεστὸς τολμήσαντα εἰπεῖν· ὃ δέ ἐστι δυνατὸν ἢ δίκαιον, τοῦτο φημί, ἀλήθειαν εἶναι ἐν μόνοις τοῖς ἀιδίοις σώμασιν, ὧν", "st": "2a.1"}, {"sp": "N", "t": "καὶ τὰ σώματα αὐτὰ ἀληθῆ ἐστι, πῦρ αὐτόπυρ μόνον καὶ οὐδὲν ἄλλο, γῆ αὐτόγη καὶ οὐδὲν ἄλλο, ἀὴρ αὐτοάηρ, ὕδωρ αὐτοΰδωρ καὶ οὐδὲν ἄλλο. τὰ δὲ ἡμέτερα σώματα ἐκ πάντων τούτων συνέστηκεν· ἔχει μὲν γὰρ πυρός, ἔχει δὲ καὶ γῆς, ἔχει καὶ ὕδατος καὶ ἀέρος· καὶ οὔτε πῦρ ἐστιν οὔτε γῆ οὔτε ὕδωρ οὔτε ἀήρ, οὔτε οὐδὲν ἀληθές. εἰ δὲ μὴ τὴν ἀρχὴν ἡ σύστασις ἡμῶν ἔσχε τὴν ἀλήθειαν, πῶς ἂν δύναιτο ἀλήθειαν ἢ ἰδεῖν ἢ εἰπεῖν; νοῆσαι δὲ μόνον ἐὰν ὁ θεὸς θέλῃ.", "st": "2a.2"}, {"sp": "N", "t": "πάντα οὖν, ὦ Τάτ, τὰ ἐπὶ γῆς ἀλήθεια μὲν οὐκ ἔστι· τῆς δὲ ἀληθείας μιμήματα καὶ οὐ πάντα, ὀλίγα δὲ ταῦτα· ἄλλα ψεῦδος καὶ πλάνος, ὦ Τάτ, καὶ δόξαι φαντασίας, καθάπερ εἰκόνες συνεστῶτα.", "st": "2a.3"}, {"sp": "N", "t": "ὅταν δ᾽ ἄνωθεν τὴν ἐπίρροιαν ἔχῃ ἡ φαντασία, τῆς ἀληθείας γίγνεται μίμησις. χωρὶς δὲ τῆς ἄνωθεν ἐνεργείας, ψεῦδος καταλείπεται· καθάπερ καὶ ἡ εἰκὼν τὸ μὲν σῶμα τῆς γραφῆς δείκνυσι, αὐτὴ δὲ οὐκ ἔστι σῶμα κατὰ τὴν φαντασίαν τοῦ ὁρωμένου, καὶ ὀφθαλμοὺς μὲν ὁρᾶται ἔχουσα, βλέπει δὲ οὐδέν, ἀκούει δὲ οὐδὲν ὅλως· καὶ τὰ ἄλλα πάντα ἔχει μὲν ἡ γραφή, ψευδῆ δέ ἐστι, τὰς τῶν ὁρώντων ὄψεις ἐξαπατῶντα, τῶν μὲν δοκούντων ἀλήθειαν ὁρᾶν, τῶν δὲ ὡς ἀληθῶς ὄντων ψευδῶν.", "st": "2a.4"}, {"sp": "N", "t": "ὅσοι μὲν οὖν οὐ ψεῦδος ὁρῶσιν, ἀλήθειαν ὁρῶσιν. ἐὰν οὖν ἕκαστον τούτων οὕτω νοῶμεν ἢ ὁρῶμεν ὡς ἔστιν, ἀληθῆ καὶ νοοῦμεν καὶ ὁρῶμεν· ἐὰν δὲ παρὰ τὸ ὄν, οὐδὲν ἀληθὲς οὔτε νοήσομεν οὔτ᾽ ὀψόμεθα.", "st": "2a.5"}, {"sp": "N", "t": "— Ἔστιν οὖν, πάτερ, ἀλήθεια καὶ ἐν τῇ γῇ. — Καὶ οὐκ ἀσκόπως σφάλλῃ, ὦ τέκνον. ἀλήθεια μὲν οὐδαμῶς ἐστιν ἐν τῇ γῇ, ὦ Τάτ, οὔτε γενέσθαι δύναται· περὶ δὲ ἀληθείας νοῆσαι ἐνίους τῶν ἀνθρώπων, οἷς ἐὰν ὁ θεὸς τὴν θεοπτικὴν δωρήσηται δύναμιν, γενέσθαι.", "st": "2a.6"}, {"sp": "N", "t": "οὕτως ἀληθὲς οὐδὲν ἔστιν ἐν τῇ γῇ. νοῶ καὶ λέγω. φαντασίαι εἰσὶ καὶ δόξαι πάντα. ἀληθῆ νοῶ καὶ λέγω. — Οὐκ οὖν τό τε ἀληθῆ νοεῖν καὶ λέγειν, τοῦτο ἀλήθειαν δεῖ καλεῖν; — Τί δαί;", "st": "2a.7"}, {"sp": "N", "t": "τὰ ὄντα δεῖ νοεῖν καὶ λέγειν, ἔστι δὲ οὐδὲν ἀληθὲς ἐπὶ τῆς γῆς· τοῦτο ἀληθές ἐστι, τὸ μὴ εἰδέναι μηδὲν ἀληθὲς ἐνθάδε.", "st": "2a.8"}, {"sp": "N", "t": "πῶς ἂν καὶ δύναιτο γενέσθαι, ὦ τέκνον; ἡ γὰρ ἀλήθεια τελεωτάτη ἀρετή ἐστιν, αὐτὸ τὸ ἄκρατον ἀγαθόν, τὸ μὴ ὑπὸ ὕλης θολούμενον μήτε ὑπὸ σώματος περιβαλλόμενον, γυμνὸν φανόν, ἄτρεπτον σεμνὸν ἀναλλοίωτον ἀγαθόν. τὰ δὲ ἐνθάδε, ὦ τέκνον, οἷά ἐστιν ὁρᾷς, ἄδεκτα τούτου τοῦ ἀγαθοῦ, φθαρτὰ παθητὰ διαλυτὰ τρεπτά, ἀεὶ ἐναλλοιούμενα, ἄλλα ἐξ ἄλλων γινόμενα.", "st": "2a.9"}, {"sp": "N", "t": "ἃ οὖν μηδὲ πρὸς ἑαυτὰ ἀληθῆ ἐστι, πῶς δύναιτο ἀληθῆ εἶναι; πᾶν γὰρ τὸ ἀλλοιούμενον ψεῦδός ἐστι, μὴ μένον ἐν ᾧ ἐστι, φαντασίας δὲ μετατρεπόμενον ἄλλας καὶ ἄλλας ἐπιδεικνύμενον ἡμῖν.", "st": "2a.10"}, {"sp": "N", "t": "— Οὐδὲ ἄνθρωπος ἀληθής ἐστιν, ὦ πάτερ; — Καθότι ἄνθρωπος, οὐκ ἔστιν ἀληθής, ὦ τέκνον. τὸ γὰρ ἀληθές ἐστι καὶ ἐξ αὑτοῦ μόνου τὴν σύστασιν ἔχον, καὶ μένον καθ᾽ αὑτὸ οἷον ἐστίν· ὁ δὲ ἄνθρωπος ἐκ πολλῶν συνέστηκε, καὶ οὐ μένει καθ᾽ αὑτόν, τρέπεται δὲ καὶ μεταβάλλεται ἡλικίαν ἐξ ἡλικίας καὶ ἰδέαν ἐξ ἰδέας καὶ ταῦτα ἔτι ὢν ἐν τῷ σκήνει. καὶ πολλοὶ τέκνα οὐκ ἐγνώρισαν χρόνου ὀλίγου μεταξὺ γενομένου, καὶ πάλιν τέκνα γονεῖς ὁμοίως.", "st": "2a.11"}, {"sp": "N", "t": "τὸ οὖν οὕτως μεταβαλλόμενον ὥστε ἀγνοεῖσθαι, δύναται ἀληθὲς εἶναι, ὦ Τάτ; οὐ τοὐναντίον ψεῦδός ἐστιν, ἐν ποικίλαις γινομένων φαντασίαις τῶν μεταβολῶν; σὺ δὲ νόει ἀληθές τι εἶναι τὸ μόνον ἀίδιον. ὁ δὲ ἄνθρωπος οὐκ ἔστιν ἀεί· ἄρα οὐδὲ ἀληθές ἐστι, φαντασία δέ ἐστί τις ἄνθρωπος· ἡ δὲ φαντασία ψεῦδος ἂν εἴη ἀκρότατον.", "st": "2a.12"}, {"sp": "N", "t": "— Οὐδὲ ταῦτα οὖν, ὦ πάτερ, τὰ ἀίδια σώματα, ἐπεὶ μεταβάλλεται, ἀληθῆ ἐστι; — Πᾶν μὲν οὖν τὸ γεννητὸν καὶ μεταβλητὸν οὐκ ἀληθές· ὑπὸ δὲ τοῦ προπάτορος γενόμενα τὴν ὕλην δύναται ἀληθῆ ἐσχηκέναι· ἔχει δέ τι καὶ ταῦτα ψεῦδος ἐν τῇ μεταβολῇ· οὐδὲν γάρ, μὴ μένον ἐφ᾽ αὑτῷ, ἀληθές ἐστιν.", "st": "2a.13"}, {"sp": "N", "t": "— Ἀληθές, ὦ πάτερ, τί οὖν ἂν εἴποι τις; — Μόνον τὸν ἥλιον, παρὰ τὰ ἄλλα πάντα μὴ μεταβαλλόμενον, μένοντα δὲ ἐφ᾽ αὑτῷ, ἀλήθειαν. διὸ καὶ τὴν ἐν τῷ κόσμῳ πάντων δημιουργίαν αὐτὸς μόνος πεπίστευται, ἄρχων πάντων καὶ ποιῶν πάντα. ὃν καὶ σέβομαι, καὶ προσκυνῶ αὐτοῦ τὴν ἀλήθειαν, μετὰ τὸν ἕνα καὶ πρῶτον τοῦτον δημιουργὸν γνωρίζω.", "st": "2a.14"}, {"sp": "N", "t": "— Τί οὖν ἂν εἴποι τις τὴν πρώτην ἀλήθειαν, ὦ πάτερ; — Ἕνα καὶ μόνον, ὦ Τάτ, τὸν μὴ ἐξ ὕλης, τὸν μὴ ἐν σώματι· τὸν ἀχρώματον, τὸν ἀσχημάτιστον· τὸν ἄτρεπτον, τὸν μὴ ἀλλοιούμενον· τὸν ἀεὶ ὄντα.", "st": "2a.15"}, {"sp": "N", "t": "τὸ δὲ ψεῦδος, ὦ τέκνον, φθείρεται. πάντα δὲ τὰ ἐπὶ γῆς φθορὰ κατέλαβε καὶ ἐμπεριέχει καὶ ἐμπεριέξει ἡ τοῦ ἀληθοῦς πρόνοια· χωρὶς γὰρ φθορᾶς οὐδὲ γένεσις δύναται συστῆναι. πάσῃ δὲ γενέσει φθορὰ ἕπεται, ἵνα πάλιν γένηται. τὰ γὰρ γιγνόμενα ἐκ τῶν φθειρομένων ἀνάγκη γίγνεσθαι· φθείρεσθαι δὲ τὰ γιγνόμενα ἀνάγκη, ἵνα μὴ στῇ ἡ γένεσις τῶν ὄντων. πρῶτον τοῦτον δημιουργὸν γνώριζε εἰς τὴν γένεσιν τῶν ὄντων. τὰ οὖν ἐκ φθορᾶς γινόμενα ψευδῆ ἂν εἴη, ὡς ποτὲ μὲν ἄλλα ποτὲ δὲ ἄλλα γινόμενα. τὰ γὰρ αὐτὰ γίνεσθαι δυνατόν· τὸ δὲ μὴ αὐτὸ πῶς ἂν ἀληθὲς εἴη;", "st": "2a.16"}, {"sp": "N", "t": "φαντασίας οὖν καλεῖν δεῖ ταῦτα, ὦ τέκνον, εἴ γε ὀρθῶς προσαγορεύομεν τὸν ἄνθρωπον ἀνθρωπότητος φαντασίαν, τὸ δὲ παιδίον παιδίου φαντασίαν, τὸν δὲ νεανίσκον νεανίσκου φαντασίαν, τὸν δὲ ἄνδρα ἀνδρὸς φαντασίαν, τὸν δὲ γέροντα γέροντος φαντασίαν· οὔτε γὰρ ὁ ἄνθρωπος ἄνθρωπος οὔτε τὸ παιδίον παιδίον, οὔτε ὁ νεανίσκος νεανίσκος, οὔτε ὁ ἀνὴρ ἀνήρ, οὔτε ὁ γέρων γέρων·", "st": "2a.17"}, {"sp": "N", "t": "μεταβαλλόμενα δὲ ψεύδεται καὶ τὰ προόντα καὶ τὰ ὄντα. ταῦτα μέντοι οὕτω νόει, ὦ τέκνον, ὡς καὶ τῶν ψευδῶν τούτων ἐνεργειῶν ἄνωθεν ἠρτημένων ἀπ᾽ αὐτῆς τῆς ἀληθείας· τούτου δὲ οὕτως ἔχοντος, τὸ ψεῦδός φημι τῆς ἀληθείας ἐνέργημα εἶναι.", "st": "2a.18"}, {"sp": "SEC", "t": "II B", "st": "2b.1"}, {"sp": "N", "t": "ἐγώ, ὦ τέκνον, καὶ τῆς φιλανθρωπίας ἕνεκα καὶ τῆς πρὸς τὸν θεὸν εὐσεβείας πρῶτον τόδε συγγράφω. οὐδεμία γὰρ ἂν γένοιτο δικαιοτάτη εὐσέβεια ἢ τοῦ νοῆσαι τὰ ὄντα καὶ χάριν τῷ ποιήσαντι ὑπὲρ τούτων ὁμολογῆσαι· ὅπερ διατελῶν οὐ παύσομαι.", "st": "2b.1"}, {"sp": "N", "t": "— Τί οὖν ἄν τις πράττων, ὦ πάτερ, εἰ μηδέν ἐστιν ἀληθὲς ἐνθάδε, καλῶς διαγάγοι τὸν βίον; — Εὐσέβει, ὦ τέκνον. ὁ δὲ εὐσεβῶν ἄκρως φιλοσοφήσει. χωρὶς γὰρ φιλοσοφίας ἄκρως εὐσεβῆσαι ἀδύνατον· ὁ δὲ μαθὼν οἷά ἐστι, καὶ πῶς διατέτακται, καὶ ὑπὸ τίνος, καὶ ἕνεκεν τίνος, χάριν εἴσεται ὑπὲρ πάντων τῷ δημιουργῷ ὡς πατρὶ ἀγαθῷ καὶ τροφεῖ χρηστῷ καὶ ἐπιτρόπῳ πιστῷ· ὁ δὲ χάριν ὁμολογῶν εὐσεβήσει.", "st": "2b.2"}, {"sp": "N", "t": "ὁ δὲ φιλοσοφῶν μαθήσεται καὶ ποῦ ἐστιν ἡ ἀλήθεια καὶ τίς ἐστιν ἐκείνη· καὶ μαθών, ἔτι μᾶλλον εὐσεβέστερος ἔσται. οὐδέποτε γάρ, ὦ τέκνον, ψυχὴ ἐν σώματι οὖσα καὶ κουφίσασα ἑαυτὴν ἐπὶ τὴν κατάληψιν τοῦ ὄντως ἀγαθοῦ καὶ ἀληθοῦς ὀλισθῆσαι δύναται ἐπὶ τὸ ἐναντίον· δεινὸν γὰρ ἔρωτα ἴσχει καὶ λήθην πάντων τῶν κακῶν ψυχὴ μαθοῦσα ἑαυτῆς τὸν προπάτορα. καὶ οὐκέτι ἀποστῆναι δύναται τοῦ ἀγαθοῦ.", "st": "2b.3"}, {"sp": "N", "t": "τοῦτο, τέκνον, τοῦτο εὐσεβείας ἐστὶ τέλος· ἐφ᾽ ὃ ἀφικνούμενος καὶ καλῶς βιώσῃ, καὶ εὐδαιμόνως τεθνήξῃ, τῆς ψυχῆς σου μὴ ἀγνοούσης ποῦ αὐτὴν δεῖ ἀναπτῆναι.", "st": "2b.4"}, {"sp": "N", "t": "αὕτη γὰρ μόνη ἐστίν, ὦ τέκνον, ἡ πρὸς ἀλήθειαν ὁδός· ἣν καὶ οἱ ἡμέτεροι πρόγονοι ὥδευσαν, καὶ ὁδεύσαντες ἔτυχον τοῦ ἀγαθοῦ. σεμνὴ αὕτη ὁδὸς καὶ λεία, χαλεπὴ δὲ ψυχῇ ὁδεῦσαι ἐν σώματι οὔσῃ.", "st": "2b.5"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ αὐτὴν ἑαυτῇ πολεμῆσαι δεῖ, καὶ διάστασιν μεγάλην ποιῆσαι, καὶ ὑπὸ τοῦ ἑνὸς μέρους πλέω νικηθῆναι. ἑνὸς γὰρ γίγνεται πρὸς δύο ἡ σύστασις, τοῦ μὲν φεύγοντος, τῶν δὲ καθελκόντων κάτω· καὶ ἔρις καὶ μάχη πολλὴ πρὸς ἄλληλα τούτων γίγνεται, τοῦ μὲν φυγεῖν βουλομένου, τῶν δὲ κατασχεῖν σπευδόντων.", "st": "2b.6"}, {"sp": "N", "t": "ἡ δὲ νίκη ἀμφοτέρων οὐχ ὁμοία· τὸ μὲν γὰρ πρὸς τὸ ἀγαθὸν σπεύδει, τὰ δὲ πρὸς τὰ κακὰ κατοικεῖ· καὶ τὸ μὲν ἐλευθερωθῆναι ποθεῖ, τὰ δὲ τὴν δουλείαν ἀγαπᾷ. κἂν μὲν νικηθῇ τὰ δύο μέρη, μεμένηκεν ἑαυτῶν ἔρημα καὶ τοῦ ἄρχοντος· ἐὰν δὲ τὸ ἓν ἡττηθῇ, ὑπὸ τῶν δύο ἄγεται καὶ φέρεται, τιμωρούμενον τῇ ἐνθάδε διαίτῃ.", "st": "2b.7"}, {"sp": "N", "t": "οὗτός ἐστιν, ὦ τέκνον, ὁ τῆς ἐκεῖσε ὁδοῦ ἀγωγός· δεῖ γάρ σε, ὦ τέκνον, πρῶτον τὸ σῶμα πρὸ τοῦ τέλους ἐγκαταλεῖψαι, καὶ νικῆσαι τὸν ἐναγώνιον βίον, καὶ νικήσαντα, οὕτως ἀνελθεῖν.", "st": "2b.8"}, {"sp": "SEC", "t": "III", "st": "3.1"}, {"sp": "N", "t": "ἐνέργειαι γάρ, ὦ Τάτ, ἀσώματοι αὐταὶ οὖσαι, ἐν σώμασίν εἰσι, καὶ διὰ τῶν σωμάτων ἐνεργοῦσι. διόπερ, ὦ Τάτ, καθότι ἀσώματοί εἰσι, καὶ ἀθανάτους αὐτὰς φὴς εἶναι· καθότι δὲ χωρὶς σωμάτων ἐνεργεῖν οὐ δύνανται, φημὶ αὐτὰς εἶναι ἀεὶ ἐν σώματι.", "st": "3.1"}, {"sp": "N", "t": "τὰ γὰρ πρός τι ἢ ἕνεκά τινος γενόμενα προνοίᾳ καὶ ἀνάγκῃ ὑποπεπτωκότα.", "st": "3.2"}, {"sp": "N", "t": "ἀδύνατον ἀργά ποτε μεῖναι τῆς ἰδίας ἐνεργείας. τὸ γὰρ ὂν ἀεὶ ἔσται. τοῦτο γὰρ αὐτοῦ καὶ σῶμα καὶ ζωή ἐστι.", "st": "3.3"}, {"sp": "N", "t": "τούτῳ τῷ λόγῳ ἕπεται τὸ καὶ ἀεὶ τὰ σώματα εἶναι. διὸ καὶ αὐτὴν τὴν σωμάτωσίν φημι ἀιδίαν ἐνέργειαν εἶναι. εἰς γὰρ σώματα ἐπίγεια διαλυτά, σώματα δὲ δεῖ εἶναι, τόπους καὶ ὄργανα τῶν ἐνεργειῶν ταῦτα, αἱ δὲ ἐνέργειαι ἀθάνατοι, τὸ δὲ ἀθάνατον ἀεὶ ἔστιν, ἐνέργεια καὶ ἡ σωματοποίησις, εἴ γε ἀεὶ ἔστι.", "st": "3.4"}, {"sp": "N", "t": "παρέπονται δὲ τῇ ψυχῇ οὐκ ἀθρόως παραγιγνόμεναι, ἀλλὰ τινὲς μὲν αὐτῶν ἅμα τῷ γενέσθαι τὸν ἄνθρωπον ἐνεργοῦσιν, ὁμοῦ τῇ ψυχῇ περὶ τὰ ἄλογα οὖσαι, αἱ δὲ καθαρώτεραι ἐνέργειαι κατὰ μεταβολὴν τῆς ἡσυχίας τῷ λογικῷ μέρει τῆς ψυχῆς συνεργοῦσαι.", "st": "3.5"}, {"sp": "N", "t": "αὗται δὲ αἱ ἐνέργειαι τῶν σωμάτων εἰσὶν ἠρτημέναι. καὶ ἀπὸ μὲν τῶν θείων σωμάτων ἔρχονται εἰς τὰ θνητὰ αὗται αἱ σωματοποιοῦσαι, ἑκάστη δὲ αὐτῶν ἐνεργεῖ ἢ περὶ τὸ σῶμα ἢ τὴν ψυχήν. καὶ αὐτῇ μέντοι τῇ ψυχῇ συγγίγνονται χωρὶς σώματος· ἀεὶ δὲ ἐνέργειαί εἰσιν, οὐκ ἀεὶ δὲ ἡ ψυχὴ ἐν σώματι θνητῷ ἐστι· δύναται γὰρ χωρὶς τοῦ σώματος εἶναι· αἱ δὲ ἐνέργειαι χωρὶς τῶν σωμάτων οὐ δύνανται εἶναι.", "st": "3.6"}, {"sp": "N", "t": "ἱερὸς λόγος ἐστίν, ὦ τέκνον, οὗτος.", "st": "3.7"}, {"sp": "N", "t": "Συνεστάναι μὲν σῶμα χωρὶς ψυχῆς οὐ δύναται, τὸ δὲ εἶναι δύναται. — Πῶς τοῦτο λέγεις, ὦ πάτερ; — Οὕτω νόησον, ὦ Τάτ. τῆς ψυχῆς χωρισθείσης τοῦ σώματος, ἐπιμένει αὐτὸ τὸ σῶμα. τοῦτο δὲ τὸ σῶμα παρὰ τὸν τῆς ἐπιμονῆς χρόνον ἐνεργεῖται, διαλυόμενον καὶ ἀειδὲς γιγνόμενον. ταῦτα δὲ οὐ δύναται πάσχειν τὸ σῶμα χωρὶς ἐνεργείας. ἐπιμένει οὖν τῷ σώματι ἡ ἐνέργεια αὐτὴ ψυχῆς χωρισθείσης.", "st": "3.7"}, {"sp": "N", "t": "αὕτη οὖν ἡ διαφορὰ ἀθανάτου σώματος καὶ θνητοῦ, ὅτι τὸ μὲν ἀθάνατον ἐκ μιᾶς ὕλης συνέστηκε, τὸ δὲ οὔ· καὶ τὸ μὲν ποιεῖ, τὸ δὲ πάσχει. πᾶν γὰρ τὸ ἐνεργοῦν κρατεῖ, τὸ δὲ ἐνεργούμενον κρατεῖται. καὶ τὸ μὲν κρατοῦν ἐπιτακτικὸν καὶ ἐλεύθερον ἄγει, τὸ δὲ δοῦλον φέρεται.", "st": "3.8"}, {"sp": "N", "t": "αἱ μὲν ἐνέργειαι οὐ μόνον τὰ ἔμψυχα ἐνεργοῦσι σώματα, καὶ τὰ ἄψυχα, ξύλα καὶ τοὺς λίθους καὶ τὰ ἄλλ᾽ ὅμοια, αὔξουσαί τε καὶ καρποφοροῦσαι καὶ πεπαίνουσαι, καὶ φθείρουσαι καὶ τήκουσαι καὶ σήπουσαι καὶ θρύπτουσαι, καὶ τὰ ὅμοια ἐνεργοῦσαι, ὅσα δύναται σώματα ἄψυχα πάσχειν. ἐνέργεια γὰρ κέκληται, ὦ τέκνον, αὐτὸ τοῦτο, ὅ τί ποτέ ἐστι τὸ γιγνόμενον.", "st": "3.9"}, {"sp": "N", "t": "ἀεὶ δὲ γίγνεσθαι δεῖ καὶ πολλά, μᾶλλον δὲ πάντα. οὐδέποτε γὰρ χηρεύει τῶν ὄντων τινὸς ὁ κόσμος, ἀεὶ δὲ φερόμενος ἐν ἑαυτῷ κυίσκει τὰ ὄντα οὐδέποτε ἀπολειφθησόμενα αὐτοῦ τῆς φθορᾶς.", "st": "3.10"}, {"sp": "N", "t": "πᾶσα οὖν ἐνέργεια νοείσθω ὡς ἀεὶ ἀθάνατος οὖσα, ἥτις ἂν ᾖ ἐν οἱῳδήποτε σώματι.", "st": "3.11"}, {"sp": "N", "t": "τῶν δὲ ἐνεργειῶν αἱ μέν εἰσι τῶν θείων σωμάτων, αἱ δὲ τῶν φθαρτῶν· καὶ αἱ μὲν καθολικαί, αἱ δὲ ἰδικαί. καὶ αἱ μὲν τῶν γενῶν, αἱ δὲ τῶν μερῶν ἑνὸς ἑκάστου. θεῖαι μὲν οὖν εἰσιν αἱ εἰς τὰ ἴδια σώματα ἐνεργοῦσαι· αὗται δὲ καὶ τέλειαί εἰσιν, ὡς εἰς τέλεια σώματα. μερικαὶ δὲ αἱ δι᾽ ἑνὸς ἑκάστου γένους τῶν ζῴων· ἰδικαὶ δὲ αἱ εἰς ἕκαστον τῶν ὄντων τι.", "st": "3.12"}, {"sp": "N", "t": "οὗτος ὁ λόγος, ὦ τέκνον, συνάγει πάντα μεστὰ εἶναι ἐνεργειῶν. εἰ γὰρ ἀνάγκη τὰς ἐνεργείας ἐν σώμασιν εἶναι, πολλὰ δὲ σώματα ἐν κόσμῳ, πλείους φημὶ εἶναι τὰς ἐνεργείας τῶν σωμάτων. ἐν ἑνὶ γὰρ πολλάκις σώματί ἐστι μία καὶ δευτέρα καὶ τρίτη, χωρὶς τῶν ἑπομένων καθολικῶν· καθολικὰς γὰρ ἐνεργείας φημὶ τὰς ὄντως σωματικάς, διὰ δὲ τῶν αἰσθήσεων καὶ τῶν κινήσεων γινομένας· χωρὶς γὰρ τούτων τῶν ἐνεργειῶν τὸ σῶμα συστῆναι οὐ δυνατόν. ἕτεραι δέ εἰσιν ἰδικαὶ ἐνέργειαι ταῖς ψυχαῖς τῶν ἀνθρώπων διὰ τεχνῶν καὶ ἐπιστημῶν καὶ ἐπιτηδευμάτων καὶ ἐνεργημάτων.", "st": "3.13"}, {"sp": "N", "t": "παρέπονται γὰρ ταῖς ἐνεργείαις καὶ αἰσθήσεις, μᾶλλον δὲ ἀποτελέσματα τῶν ἐνεργειῶν αἰσθήσεις εἰσί.", "st": "3.14"}, {"sp": "N", "t": "νόησον οὖν, ὦ τέκνον, διαφορὰν ἐνεργείας ⟨καὶ αἰσθήσεως. ἡ μὲν γὰρ ἐνέργεια⟩ ἄνωθεν πέμπεται· ἡ δὲ αἴσθησις, ἐν τῷ σώματι οὖσα, καὶ ἀπὸ τούτου τὴν οὐσίαν ἔχουσα, δεξαμένη τὴν ἐνέργειαν φανερὰν ποιεῖ, καθάπερ αὐτὴν σωματοποιήσασα. διόπερ τὰς αἰσθήσεις καὶ σωματικὰς καὶ θνητάς φημι εἶναι, τοσοῦτον συνεστώσας ὅσον καὶ τὸ σῶμα· καὶ γὰρ συγγεννῶνται τῷ σώματι αἱ αἰσθήσεις καὶ συναποθνήσκουσι.", "st": "3.15"}, {"sp": "N", "t": "τὰ δὲ ἀθάνατα σώματα αὐτὰ μὲν αἴσθησιν οὐκ ἔχει, ὡς ἐξ οὐσίας τοιαύτης συνεστῶτα. ἡ γὰρ αἴσθησις οὐδ᾽ ὅλως ἄλλου ἐστὶ σωματικὴ ἢ τοῦ προσγινομένου τῷ σώματι κακοῦ ἢ τοῦ ἀγαθοῦ, ἢ τοῦ πάλιν αὖ ἀπογινομένου· τοῖς δὲ ἀιδίοις σώμασιν οὔτε προσγίνεται οὔτε ἀπογίνεται· διὸ αἴσθησις ἐν ἐκείνοις οὐ γίνεται.", "st": "3.16"}, {"sp": "N", "t": "— Ἐν παντὶ οὖν σώματι αἴσθησις αἰσθάνεται; — Ἐν παντί, ὦ τέκνον· καὶ ἐνέργειαι πᾶσιν ἐνεργοῦσι. — Κἀν τοῖς ἀψύχοις, ὦ πάτερ; — Κἀν ἀψύχοις, ὦ τέκνον. διαφοραὶ δέ εἰσι τῶν αἰσθήσεων· αἱ μὲν τῶν λογικῶν μετὰ λόγου γίγνονται, αἱ δὲ τῶν ἀλόγων σωματικαί εἰσι μόνον, αἱ δὲ τῶν ἀψύχων", "st": "3.17"}, {"sp": "N", "t": "αἰσθήσεις μέν εἰσι, παθητικαὶ δέ, κατὰ αὔξησιν μόνον δὲ κατὰ μείωσιν γιγνόμεναι. τὸ δὲ πάθος καὶ αἴσθησις ἀπὸ μιᾶς κορυφῆς ἤρτηνται, εἰς δὲ τὸ αὐτὸ συνάγονται, ὑπὸ δὲ τῶν ἐνεργειῶν.", "st": "3.18"}, {"sp": "N", "t": "τῶν δὲ ἐμψύχων ζῴων εἰσὶ δύο ἄλλαι ἐνέργειαι, αἳ παρέπονται ταῖς αἰσθήσεσι καὶ τοῖς πάθεσι, λύπη καὶ χαρά. χωρὶς τούτων ζῷον ἔμψυχον καὶ μάλιστα λογικὸν αἰσθέσθαι ἀδύνατον· διὸ καὶ ἰδίας ταύτας εἶναί φημι τῶν παθῶν ἰδέας τῶν λογικῶν μᾶλλον ζῴων ἐπικρατούσας. αἱ μὲν ἐνέργειαι ἐνεργοῦσιν, αἱ δὲ αἰσθήσεις τὰς ἐνεργείας ἀναφαίνουσιν.", "st": "3.19"}, {"sp": "N", "t": "αὗται δέ, οὖσαι σωματικαί, ἀνακινοῦνται ὑπὸ τῶν τῆς ψυχῆς ἀλόγων μερῶν· διὸ καὶ ἀμφοτέρας φημὶ κακωτικὰς εἶναι. τό τε γὰρ χαίρειν, μεθ᾽ ἡδονῆς τὴν αἴσθησιν παρέχον, πολλῶν κακῶν εὐθέως αἴτιον συμβαίνειν τῷ παθόντι· ἥ τε λύπη ἀλγηδόνας καὶ ὀδύνας ἰσχυροτέρας παρέχεται. διόπερ εἰκότως ἀμφότεραι κακωτικαὶ ἂν εἴησαν.", "st": "3.20"}, {"sp": "N", "t": "— Ἡ αὐτὴ ἂν εἴη αἴσθησις ψυχῆς καὶ σώματος, ὦ πάτερ; — Πῶς νοεῖς, ὦ παῖ, ψυχῆς αἴσθησιν; οὐχ ἡ μὲν ψυχὴ ἀσώματος, ἡ δὲ αἴσθησις σῶμα; — * * * ἂν εἴη, ὦ πάτερ, ἡ αἴσθησις ἡ ἐν σώματι οὖσα τυγχάνει. — Ἐὰν ἀσώματον αὐτὴν θῶμεν, ὦ τέκνον, ὁμοίαν τῇ ψυχῇ αὐτὴν ἀποφανοῦμεν ἢ ταῖς ἐνεργείαις· ταῦτα γὰρ ἀσώματα ὄντα φαμὲν ἐν σώμασιν. ἡ δὲ αἴσθησις οὔτε ἐνέργειά ἐστιν οὔτε ψυχή, οὔτε ἀσώματόν τι ἄλλο παρὰ τὰ προειρημένα· οὐκ ἂν οὖν εἴη ἀσώματον. εἰ δ᾽ οὐκ ἔστιν ἀσώματον, σῶμα ἂν εἴη. τῶν γὰρ ὄντων δεῖ τὰ μὲν σώματα εἶναι, τὰ δὲ ἀσώματα.", "st": "3.21"}, {"sp": "SEC", "t": "IV A", "st": "4a.1"}, {"sp": "N", "t": "Ἔφαμεν γὰρ ἐν τοῖς γενικοῖς κινήσεις τὰς μὲν ὑπὸ τῶν ἐνεργειῶν, τὰς δὲ ὑπὸ τῶν σωμάτων.", "st": "4a.1"}, {"sp": "N", "t": "φαμὲν δὲ τὴν ψυχὴν ἐξ οὐσίας τινὸς οὐχ ὕλης γεγενῆσθαι, ἀσώματον οὖσαν καὶ αὐτῆς ἀσωμάτου οὔσης. πᾶν γὰρ τὸ γενόμενον ἀνάγκη ἔκ τινος γεγενῆσθαι.", "st": "4a.2"}, {"sp": "N", "t": "ὅσων μὲν οὖν τῇ γενέσει φθορὰ ἐπακολουθεῖ, τούτοις δύο κινήσεις παρακολουθεῖν ἀνάγκη, τήν τε ψυχῆς, ὑφ᾽ ἧς κινεῖται, καὶ τὴν τοῦ σώματος, ὑφ᾽ ἧς αὔξεται καὶ φθίνει, ἔτι δὲ καὶ ἀναλυθέντα ἀναλύεται. ταύτην ὁρίζομαι τὴν κίνησιν τῶν φθαρτῶν σωμάτων.", "st": "4a.3"}, {"sp": "N", "t": "ἡ δὲ ψυχὴ ἀεικίνητος, ὅτι ἀεὶ ἑαυτῇ κινεῖται καὶ ἄλλοις κίνησιν ἐνεργεῖ. κατὰ τοῦτον οὖν τὸν λόγον ἐστὶ ψυχὴ πᾶσα ἀθάνατος, καθότι ἀεικίνητος, ἔχουσα κίνησιν τὴν αὑτῆς ἐνέργειαν.", "st": "4a.4"}, {"sp": "N", "t": "ἰδέαι δὲ ψυχῶν, θεία, ἀνθρωπίνη, ἄλογος. ἡ μὲν οὖν θεία τοῦ θείου σώματος αὐτῆς ἐνέργεια· ἐν μὲν γὰρ αὐτῷ κινεῖται, καὶ ἑαυτὸ κινεῖ.", "st": "4a.5"}, {"sp": "N", "t": "ἐπὰν γὰρ θνητῶν ζῴων ἀπαλλαγῇ, χωρισθεῖσα τῶν ἀλόγων ἑαυτῆς μερῶν, ἐξελθοῦσα εἰς τὸ θεῖον σῶμα, ὡς ἀεικίνητος ἐν αὐτῷ κινεῖται, συμπεριφερομένη τῷ παντί.", "st": "4a.6"}, {"sp": "N", "t": "ἡ δὲ ἀνθρωπίνη ἔχει μὲν καὶ τὸ τοῦ θείου, συνῆπται δὲ αὐτῇ καὶ τὰ ἄλογα, ἥ τε ἐπιθυμία καὶ ὁ θυμός· καὶ αὗται μὲν ἀθάνατοι, καθότι καὶ αὗται αἱ ἐνέργειαι τυγχάνουσιν, αἱ ἐνέργειαι δὲ θνητῶν σωμάτων. διὸ τοῦ μὲν θείου μέρους τῆς ψυχῆς, οὔσης ἐν τῷ θείῳ σώματι, πόρρω τυγχάνουσιν οὖσαι· ἐπειδὰν δὲ εἰσέλθῃ τοῦτο εἰς θνητὸν σῶμα, κἀκεῖνα ἐπιφύεται, καὶ τῇ παρουσίᾳ αὐτῶν γίνεται ἀεὶ ψυχὴ ἀνθρωπίνη.", "st": "4a.7"}, {"sp": "N", "t": "ἡ δὲ τῶν ἀλόγων συνέστηκεν ἐκ θυμοῦ τε καὶ ἐπιθυμίας. διόπερ καὶ ἄλογα ἐκλήθη τὰ ζῷα ταῦτα, στερήσει τοῦ ἀλόγου τῆς ψυχῆς.", "st": "4a.8"}, {"sp": "N", "t": "τετάρτην δὲ νόει τὴν τῶν ἀψύχων, ἥτις ἔξωθεν οὖσα τῶν σωμάτων ἐνεργεῖ κινοῦσα. αὕτη δ᾽ ἂν εἴη ἡ ἐν τῷ θείῳ σώματι κινουμένη, καὶ ὥσπερ κατὰ πάροδον ταῦτα κινοῦσα.", "st": "4a.9"}, {"sp": "SEC", "t": "IV B", "st": "4b.1"}, {"sp": "N", "t": "— Ὀρθῶς ταῦτα ἀπέδειξας, ὦ πάτερ· ἐκεῖνο δὲ ἔτι με δίδαξον. ἔφης γάρ που τὴν ἐπιστήμην καὶ τὴν τέχνην ἐνεργείας εἶναι τοῦ λογικοῦ. νῦν δὲ φὴς τὰ ἄλογα ζῷα στερήσει τοῦ λογικοῦ ἄλογα εἶναι καὶ κεκλῆσθαι· δῆλον ὅτι ἀνάγκη κατὰ τοῦτον τὸν λόγον τὰ ἄλογα ζῷα μὴ μετέχειν ἐπιστήμης μηδὲ τέχνης, διὰ τὸ ἐστερῆσθαι τοῦ λογικοῦ. — Ἀνάγκη γάρ, ὦ τέκνον.", "st": "4b.1"}, {"sp": "N", "t": "— Πῶς οὖν ὁρῶμεν, ὦ πάτερ, τινὰ τῶν ἀλόγων ἐπιστήμῃ καὶ τέχνῃ χρώμενα, οἷον τοὺς μύρμηκας τὰς τροφὰς ἀποθησαυριζομένους τοῦ χειμῶνος, καὶ τὰ ἀέρια ζῷα ὁμοίως καλιὰς ἑαυτοῖς συντιθέντα, τὰ δὲ τετράποδα γνωρίζοντα τοὺς φωλεοὺς τοὺς ἰδίους;", "st": "4b.2"}, {"sp": "N", "t": "— Ταῦτα, ὦ τέκνον, οὐκ ἐπιστήμῃ οὐ τέχνῃ ποιεῖ, ἀλλὰ φύσει. ἡ γὰρ ἐπιστήμη καὶ ἡ τέχνη διδακτικά εἰσι· ταῦτα δὲ τῶν ἀλόγων οὐδεὶς οὐδὲν διδάσκεται. τὰ δὲ φύσει γιγνόμενα ἐνεργείᾳ μὲν γίγνεται καθολικῇ· τὰ δὲ ἐπιστήμῃ καὶ τέχνῃ εἰδόσι παραγίγνεται, οὐ πᾶσι γιγνόμενα ὑπὸ φύσεως ἐνεργεῖται.", "st": "4b.3"}, {"sp": "N", "t": "οἷον οἱ ἄνθρωποι ἄνω βλέπουσιν· οὐ πάντες δὲ ἄνθρωποι μουσικοί, οὐδὲ πάντες τοξόται ἢ κυνηγοί, οὐδὲ τὰ ἄλλα πάντα, ἀλλὰ τινὲς αὐτῶν τι ἔμαθον, ἐπιστήμης καὶ τέχνης ἐνεργούσης.", "st": "4b.4"}, {"sp": "N", "t": "τὸν αὐτὸν τρόπον, ⟨εἰ⟩ οἱ μέν τινες τῶν μυρμήκων τοῦτο ἔπραττον, οἱ δ᾽ οὔ, καλῶς ἂν ἔλεγες ἐπιστήμῃ αὐτὸ τοῦτο πράττειν καὶ τέχνῃ συνάγειν τὰς τροφάς· εἰ δὲ πάντες ὁμοίως ἄγονται ὑπὸ τῆς φύσεως ἐπὶ τοῦτο καὶ ἄκοντες, δῆλον ὅτι οὐκ ἐπιστήμῃ οὐδὲ τέχνῃ τοῦτο πράττουσιν.", "st": "4b.5"}, {"sp": "SEC", "t": "V", "st": "5.1"}, {"sp": "N", "t": "καὶ ὁ μὲν κύριος καὶ πάντων δημιουργὸς τῶν ἀιδίων σωμάτων, ὦ Τάτ, ἅπαξ ποιήσας οὐκέτι ἐποίησεν οὐδὲ ποιεῖ· ταῦτα γὰρ ἑαυτοῖς παραδοὺς καὶ ἑνώσας ἀλλήλοις ἀφῆκε φέρεσθαι, μηδὲν ἐνδέοντα ὡς ἀίδια. εἰ δὲ δέονται τινῶν, ἀλλήλων δεήσονται, οὐδεμιᾶς δὲ τῆς ἔξωθεν ἐπιφορᾶς, ὡς ἀθάνατα· ἔδει γὰρ τὰ ὑπ᾽ ἐκείνου σώματα γενόμενα τοιαύτην ἔχειν καὶ τὴν φύσιν.", "st": "5.1"}, {"sp": "N", "t": "ὁ δὲ ἡμέτερος δημιουργός, ἐν σώματι ὤν, ἐποίησεν ἡμᾶς, καὶ ποιεῖ ἀεὶ καὶ ποιήσει, σώματα διαλυτὰ καὶ θνητά. οὐ γὰρ θέμις ἦν αὐτῷ μιμεῖσθαι τὸν ἑαυτοῦ δημιουργόν, ἄλλως τε καὶ ἀδύνατον· ὁ μὲν γὰρ ἐκ τῆς πρώτης οὐσίας ἐποίησεν, οὔσης ἀσωμάτου, ὁ δὲ ἐκ τῆς γινομένης σωματώσεως ἐποίησεν ἡμᾶς.", "st": "5.2"}, {"sp": "N", "t": "εἰκότως οὖν κατὰ τὸν ὀρθὸν λόγον ἐκεῖνα μὲν τὰ σώματα, ὡς ἐξ ἀσωμάτου οὐσίας γεγενημένα, ἀθάνατά ἐστι· τὰ δὲ ἡμέτερα διαλυτὰ καὶ θνητά, ὡς τῆς ὕλης ἡμῶν ἐκ σωμάτων συνεστώσης.", "st": "5.3"}, {"sp": "N", "t": "διὸ τὸ ἀσθενῆ ἐστι, καὶ πολλῆς ἐπικουρίας δεόμενα. πῶς γὰρ ἂν καὶ τὸ τυχὸν ἀντέσχεν ὁ σύνδεσμος ἡμῶν τῶν σωμάτων, εἰ μή τινα εἶχεν ἐπεισερχομένην τροφὴν ἐκ τῶν ὁμοίων στοιχείων, καὶ ὑπεσωμάτου ἡμᾶς καθ᾽ ἑκάστην τὴν ἡμέραν; καὶ γὰρ γῆς τε καὶ ὕδατος καὶ πυρὸς καὶ ἀέρος ἐπιρροὴ ἡμῖν γίγνεται, ἥτις τὰ σώματα ἡμῶν νεοποιοῦσα συνέχει τὸ σκῆνος.", "st": "5.4"}, {"sp": "N", "t": "ὥστε καὶ πρὸς τὰς κινήσεις ἐσμὲν ἀσθενέστεροι, φέροντες κινήσεις μηδὲ ἡμέρας μιᾶς. εὖ γὰρ ἴσθι, ὦ τέκνον, ὅτι εἰ μὴ ἐν ταῖς νυξὶν ἡμῶν ἀνεπαύετο τὰ σώματα, οὐκ ἂν πρὸς μίαν ἡμέραν ἀντέσχομεν. ὅθεν ἀγαθὸς ὢν ὁ δημιουργός, πάντα προεπιστάμενος, εἰς διαμονὴν τοῦ ζῴου ἐποίησε τὸν ὕπνον, ⟨φάρμακ⟩ον μέγιστον τοῦ καμάτου τῆς κινήσεως, καὶ ἐπ᾽ ἰσότητος ἔταξεν ἑκατέρῳ χρόνον, μᾶλλον δὲ τῇ ἀναπαύλῃ πλείονα.", "st": "5.5"}, {"sp": "N", "t": "μεγίστην δὲ νόει, τέκνον, τοῦ ὕπνου τὴν ἐνέργειαν, ἐναντίαν τῇ τῆς ψυχῆς, οὐκ ἔλαττον ἐκείνης. καθάπερ γὰρ ἡ ψυχὴ κινήσεώς ἐστιν ἐνέργεια, τὸν αὐτὸν τρόπον καὶ τὰ σώματα ζῆν οὐ δύναται χωρὶς ὕπνου· ἄνεσις γὰρ καὶ ἄφεσίς ἐστι τῶν συνδέτων τῶν μελῶν.", "st": "5.6"}, {"sp": "N", "t": "καὶ ἔσωθεν ἐνεργεῖ, σωματοποιῶν τὴν ἐπεισελθοῦσαν ὕλην, ἑκάστῳ τὸ οἰκεῖον διαστέλλων, τὸ μὲν ὕδωρ τῷ αἵματι, τὴν δὲ γῆν ὀστέοις καὶ μυελοῖς, τὸν δὲ ἀέρα τοῖς νεύροις καὶ φλεψί, τὸ δὲ πῦρ τῇ ὁράσει. διόπερ καὶ ἥδεται ἄκρως τὸ σῶμα τῷ ὕπνῳ ταύτην ἐνεργοῦντι τὴν ἡδονήν.", "st": "5.7"}, {"sp": "SEC", "t": "VI", "st": "6.1"}, {"sp": "N", "t": "Ἐπεί μοι ἐν τοῖς ἔμπροσθεν γενικοῖς λόγοις ὑπέσχου δηλῶσαι περὶ τῶν τριάκοντα ἓξ δεκανῶν, νῦν μοι δήλωσον περὶ αὐτῶν καὶ τῆς τούτων ἐνεργείας. — Οὐδὲ εἷς φθόνος, ὦ Τάτ· καὶ ὁ κυριώτατος πάντων λόγος καὶ κορυφαιότατος οὗτος ἂν εἴη. σὺ δὲ νόει οὕτως.", "st": "6.1"}, {"sp": "N", "t": "ἔφαμέν σοι περὶ τοῦ ζῳδιακοῦ κύκλου, καὶ τοῦ ζῳοφόρου, καὶ τῶν πέντε πλανητῶν καὶ ἡλίου καὶ σελήνης καὶ τοῦ ἑκάστου τούτων κύκλου. — Ἔφης γάρ, ὦ Τρισμέγιστε. — Οὕτως βούλομαί σε νοεῖν καὶ περὶ τῶν τριάκοντα ἓξ δεκανῶν, μεμνημένον ἐκείνων, ἵν᾽ εὔγνωστός σοι καὶ ὁ περὶ τούτων λόγος γένοιτο. — Μέμνημαι, ὦ πάτερ.", "st": "6.2"}, {"sp": "N", "t": "— Φαμέν που, ὦ τέκνον, περιεκτικὸν τῶν ἁπάντων εἶναι σῶμα. ἐννόησον οὖν καὶ αὐτὸ ὥσπερ κυκλοειδὲς σχῆμα· καὶ γὰρ οὕτως ἔχει τὸ πᾶν. — Τοιοῦτον σχῆμα νοῶ οὕτως ὡς λέγεις, ὦ πάτερ. — Ὑπὸ δὲ τὸν κύκλον τοῦ σώματος τούτους τετάχθαι τοὺς τριάκοντα ἓξ δεκανούς, μέσους τοῦ παντὸς κύκλου τοῦ ζῳδιακοῦ, διορίζοντας ἀμφοτέρους τοὺς κύκλους, καὶ ὥσπερ ἐκεῖνον μὲν κουφίζοντας, τὸν ζῳδιακὸν καθορίζοντας,", "st": "6.3"}, {"sp": "N", "t": "συμφερομένους τοῖς πλάνησι καὶ ἰσοδυναμεῖν τῇ τοῦ παντὸς φορᾷ κατὰ τὸ ἐναλλὰξ τοῖς ἑπτά· καὶ τὸ μὲν περιεκτικὸν ἐπέχειν σῶμα, ἔσχατον γὰρ ἂν ἦν ἐν τῇ φορᾷ αὐτὸ καθ᾽ αὑτὸ ὂν τῷ πάσχειν, ἐπισπεύδειν δὲ τοὺς ἑπτὰ ἄλλους κύκλους, διὰ τὸ βραδυτέραν κίνησιν κινεῖσθαι τοῦ παντὸς κύκλου, ὥσπερ οὖν ἀνάγκη αὐτοὺς κινεῖσθαι καὶ τοῦ παντός.", "st": "6.4"}, {"sp": "N", "t": "νοήσωμεν οὖν καὶ τὰς τῶν ἑπτὰ καὶ πάντα τὸν κύκλον, μᾶλλον δὲ τῶν ἐν κόσμῳ ἁπάντων ὡσπερεὶ φύλακας αὐτοὺς περιίστασθαι, πάντα συνέχοντας καὶ τὰ πάντα, καὶ τηροῦντας τὴν τῶν πάντων εὐταξίαν. — Οὕτως γὰρ νοῶ, πάτερ, ἐξ ὧν λέγεις.", "st": "6.5"}, {"sp": "N", "t": "— Ἔτι δὲ νόησον, Τάτ, ὅτι καὶ ἀπαθεῖς εἰσιν ὧν οἱ ἄλλοι ἀστέρες πάσχουσιν. οὔτε γὰρ ἐπεχόμενοι τὸν δρόμον στηρίζουσιν οὔτε κωλυόμενοι ἀναποδίζουσιν, ἀλλ᾽ οὐδὲ μὴν ὑπὸ τοῦ φωτὸς τοῦ ἡλίου σκέπονται, ἅπερ πάσχουσιν οἱ ἄλλοι ἀστέρες· ἐλεύθεροι δὲ ὄντες, ὑπεράνω πάντων ὥσπερ φύλακες ἀκριβεῖς καὶ ἐπίσκοποι τοῦ παντὸς περιέχονται τῷ νυχθημέρῳ τὸ πᾶν.", "st": "6.6"}, {"sp": "N", "t": "— Ἆρ᾽ οὖν καὶ οὗτοι, ὦ πάτερ, ἔχουσι πρὸς ἡμᾶς ἐνέργειαν; — Τὴν μεγίστην, ὦ τέκνον. εἰ γὰρ ἐκείνοις ἐνεργοῦσι, πῶς οὐ καὶ ἡμῖν, καὶ καθ᾽ ἕνα ἕκαστον καὶ κοινῇ;", "st": "6.7"}, {"sp": "N", "t": "οὕτως, ὦ τέκνον, τῶν καθολικῶς πάντων συμβαινόντων ἡ ἐνέργεια ἀπὸ τούτων ἐστίν· οἷον, ὃ λέγω νόησον, βασιλέων μετατροπαί, πόλεων ἐπαναστάσεις, λιμοί, λοιμοί, ἄμπωτις θαλάσσης, γῆς σεισμοί, οὐδὲν τούτων, ὦ τέκνον, χωρὶς τῆς τούτων ἐνεργείας γίνεται.", "st": "6.8"}, {"sp": "N", "t": "ἔτι τε πρὸς τούτοις νόησον· εἰ γὰρ οὗτοι μὲν ἐπιστατοῦσιν ἐκείνων, ἡμεῖς δὲ καὶ ὑπὸ τοὺς ἑπτά ἐσμεν, οὐ νοεῖς καὶ εἰς ἡμᾶς τινὰ ἐκείνων φθάνειν ἐνέργειαν, ἤτοι ὑπ᾽ αὐτῶν ἢ δι᾽ ἐκείνων;", "st": "6.9"}, {"sp": "N", "t": "— Τίς αὐτοῖς εἴη, ὦ πάτερ, ὁ τοῦ σώματος τύπος; — Τούτους οὖν καλοῦσιν οἱ πολλοὶ δαίμονας· οὐδὲ γὰρ ἴδιόν τί ἐστι γένος τὸ τῶν δαιμόνων, οὔτε ἄλλα σώματα ἔχοντες ἐξ ἰδίας τινὸς ὕλης οὔτε ψυχῇ κινούμενοι ὥσπερ ἡμεῖς, ἀλλὰ ἐνέργειαί εἰσι τῶν τριάκοντα ἓξ τούτων θεῶν.", "st": "6.10"}, {"sp": "N", "t": "ἔτι δὲ πρὸς τούτοις νόησον, ὦ Τάτ, ἐνέργημα τούτων, ὅτι καὶ εἰς τὴν γῆν σπερματίζουσιν ἃς καλοῦσι τάνας, τὰς μὲν σωτηρίους, τὰς δὲ ὀλεθριωτάτας.", "st": "6.11"}, {"sp": "N", "t": "ἔτι καὶ ἐν οὐρανῷ φερόμενοι ἀστέρες γεννῶσιν αὐτοῖς ὑπολειτουργούς, οὓς καὶ ὑπηρέτας καὶ στρατιώτας ἔχουσιν. οὗτοι δὲ ὑπ᾽ ἐκείνων μιγνύμενοι φέρονται ἐν τῷ αἰθέρι αἰωρούμενοι, τὸν τούτου τόπον ἀναπληροῦντες, ὅπως μηδεὶς ᾖ τόπος ἄνω κενὸς ἀστέρων, συγκοσμοῦντες τὸ πᾶν, ἐνέργειαν ἰδίαν ἔχοντες, ὑποτεταγμένην δὲ τῶν τριάκοντα ἓξ ἐνεργείᾳ· ἐξ ὧν καὶ κατὰ τὰς χώρας φθοραὶ γίνονται τῶν ἄλλων ἐμψύχων ζῴων, καὶ ἡ πληθὺς τῶν λυμαινομένων ζῴων τοὺς καρπούς.", "st": "6.12"}, {"sp": "N", "t": "ὑπὸ δὲ τούτους ἐστὶν ἡ καλουμένη ἄρκτος, κατὰ μέσον τοῦ ζῳδιακοῦ, ἐξ ἀστέρων συγκειμένη ἑπτά, ἔχουσα ἀντίζυγον ἑτέραν ὑπὲρ κεφαλῆς. ταύτης μὲν ἡ ἐνέργειά ἐστι καθάπερ ἄξονος, μηδαμοῦ μὲν δυνούσης μηδὲ ἀνατελλούσης, μενούσης δὲ ἐν τῷ αὐτῷ τόπῳ, τῆς περὶ αὐτὸ στρεφομένης, ἐνεργούσης δὲ τὴν ζωφόρου κυκλοῦ, παραδιδοῦσα τὸ πᾶν τοῦτο ἀπὸ μὲν τῆς νυκτὸς ἡμέρᾳ, ἀπὸ ἡμέρας νυκτί.", "st": "6.13"}, {"sp": "N", "t": "μετὰ δὲ τούτους ἐστὶν ἄλλος χορὸς ἀστέρων, οὓς ἡμεῖς προσηγοριῶν οὐ κατηξιώσαμεν· οἱ δὲ μεθ᾽ ἡμᾶς μιμησάμενοι μὲν καὶ οὗτοι προσηγορίας τούτοις θήσονται.", "st": "6.14"}, {"sp": "N", "t": "κάτωθεν δὲ τῆς σελήνης εἰσὶν ἕτεροι ἀστέρες φθαρτοί, ἀργοί, πρὸς ὀλίγον χρόνον συνιστάμενοι, εἰς τὸν ὑπὲρ γῆς ἀέρα ἐξ αὐτῆς τῆς γῆς ἀναθυμιώμενοι, οὓς καὶ ἡμεῖς ὁρῶμεν διαλυομένους. τὴν φύσιν ὁμοίαν ἔχουσι τοῖς ἀχρήστοις τῶν ἐπὶ γῆς ζῴων, ἐπὶ ἕτερον δὲ οὐδὲν γίνεται ἢ ἵνα μόνον φθαρῇ, οἷον τὸ τῶν μυιῶν γένος καὶ τῶν ψυλλῶν καὶ τῶν σκωλήκων καὶ τῶν ἄλλων τῶν ὁμοίων. καθάπερ γὰρ ἐκεῖνα, ὦ Τάτ, οὔτε ἡμῖν οὔτε τῷ κόσμῳ χρήσιμά ἐστι, τοὐναντίον δὲ λυπεῖ ἐνοχλοῦντα, παρακολουθήματα ὄντα τῆς φύσεως, καὶ κατὰ τὸ περισσὸν τὴν γένεσιν ἔχοντα, τὸν αὐτὸν τρόπον καὶ οἱ ἀπὸ τῆς γῆς ἀναθυμιώμενοι ἀστέρες τὸν μὲν ἄνω τόπον οὐ καταλαμβάνουσιν, ἀδυνατοῦσι γάρ, ὡς κάτωθεν ἀνιόντες, πολὺ δὲ ἐμβριθὲς ἔχοντες, ἑλκόμενοι κάτω ὑπὸ τῆς ἰδίας ὕλης διαχέονται ταχέως, καὶ διαλυθέντες πίπτουσι πάλιν εἰς γῆν, μηδὲν ἐνεργήσαντες ἢ μόνον ὀχλήσαντες τῷ ὑπὲρ γῆν ἀέρι.", "st": "6.15"}, {"sp": "N", "t": "ἕτερόν ἐστι γένος, ὦ Τάτ, τὸ τῶν καλουμένων κομητῶν, κατὰ καιρὸν ἐπιφαινομένων, καὶ πάλιν μετὰ χρόνον ὀλίγον ἀφανῶν γινομένων, μήτε ἀνατελλόντων μήτε δυνόντων μήτε διαλυομένων· οἵτινες φανεροὶ ἄγγελοι καὶ κήρυκες καθολικῶν ἀποτελεσμάτων γίνονται μελλόντων ἔσεσθαι. οὗτοι δὲ τὸν τόπον ἔχουσιν ὑπὸ τὸν κύκλον τὸν τοῦ ἡλίου. ἐπὰν οὖν μέλλῃ τι τῷ κόσμῳ συμβαίνειν, οὗτοι φαίνονται, φανέντες ὀλίγας ἡμέρας, πάλιν ὑπὸ τὸν κύκλον ἐλθόντες τοῦ ἡλίου ἀφανεῖς μένουσιν, ἐν τῷ ἀπηλιώτῃ φανέντες, ἄλλοι δὲ ἐν τῷ βορρᾷ, ἄλλοι δὲ ἐν τῷ λιβί, ἄλλοι δὲ ἐν τῷ νότῳ. μάντεις δὲ τούτους προσηγορεύσαμεν. καὶ ἀστέρων ἥδε φύσις.", "st": "6.16"}, {"sp": "N", "t": "ἀστέρες δὲ ἄστρων διαφορὰν ἔχουσιν· ἀστέρες μὲν γάρ εἰσιν οἱ ἐν τῷ οὐρανῷ αἰωρούμενοι, ἄστρα δὲ τὰ ἐγκείμενα ἐν τῷ σώματι τοῦ οὐρανοῦ, συμφερόμενα δὲ ἐν τῷ οὐρανῷ· ἐξ ὧν δώδεκα ζῴδια προσηγορεύσαμεν.", "st": "6.17"}, {"sp": "N", "t": "ὁ ταῦτα μὴ ἀγνοήσας ἀκριβῶς δύναται νοῆσαι τὸν θεόν, εἰ δὲ καὶ τολμήσαντα δεῖ εἰπεῖν, καὶ αὐτόπτης γενόμενος θεάσασθαι, καὶ θεασάμενος μακάριος γενέσθαι. — Μακάριος ὡς ἀληθῶς, ὦ πάτερ, ὁ τοῦτον θεασάμενος. — Ἀλλ᾽ ἀδύνατον, ὦ τέκνον, τὸν ἐν σώματι τούτου εὐτυχῆσαι· δεῖ δὲ προγυμνάζειν αὑτοῦ τινα τὴν ψυχὴν ἐνθάδε, ἵνα ἐκεῖ γενομένη, ὅπου αὐτὸν ἔξεστι θεάσασθαι, ὁδοῦ μὴ σφαλῇ.", "st": "6.18"}, {"sp": "N", "t": "ὅσοι δὲ ἄνθρωποι φιλοσώματοί εἰσιν, οὗτοι οὐκ ἄν ποτε θεάσαιντο τὴν τοῦ καλοῦ καὶ ἀγαθοῦ ὄψιν. οἷον γάρ ἐστι κάλλος, ὦ τέκνον, τὸ μήτε σχῆμα μήτε χρῶμα μήτε σῶμα ἔχον. — Εἴη δ᾽ ἄν τι, ὦ πάτερ, χωρὶς τούτων καλόν; — Μόνος ὁ θεός, ὦ τέκνον, μᾶλλον δὲ τὸ μεῖζόν τι ὂν τοῦ θεοῦ τὸ ὄνομα.", "st": "6.19"}, {"sp": "SEC", "t": "VII", "st": "7.1"}, {"sp": "N", "t": "δαίμων γάρ τις μεγίστη τέτακται, ὦ τέκνον, ἐν μέσῳ τοῦ παντὸς εἰλουμένη, πάντα περιορῶσα τὰ ἐπὶ γῆς γινόμενα ὑπὸ τῶν ἀνθρώπων. καθάπερ ἐπὶ τῆς θείας τάξεως πρόνοια καὶ ἀνάγκη τέτακται, τὸν αὐτὸν τρόπον καὶ ἐπὶ τῶν ἀνθρώπων τέτακται ἡ δίκη, ταὐτὰ ἐκείνοις ἐνεργοῦσα.", "st": "7.1"}, {"sp": "N", "t": "ἐκείνη μὲν γὰρ κρατεῖ τὴν τάξιν τῶν ὄντων ὡς θείων, καὶ ἁμαρτεῖν μὴ θελόντων μηδὲ δυναμένων· ἀδύνατον γὰρ τὸ θεῖον πλανηθῆναι, ἐξ οὗ καὶ τὸ ἀναμάρτητον συμβαίνει· ἡ δὲ δίκη τέτακται τιμωρὸς τῶν ἐπὶ γῆς ἁμαρτανόντων.", "st": "7.2"}, {"sp": "N", "t": "ἀνθρώπων γὰρ γένος, ἅτε θνητὸν ὂν καὶ ἐκ κακῆς ὕλης συνεστός, καὶ μάλιστα ἐκείνοις συμβαίνει τὸ ὀλισθαίνειν, οἷς θεοπτικὴ δύναμις οὐ πρόσεστι· τούτων δὲ καὶ μάλιστα ἐπικρατεῖ δίκη· καὶ τῇ εἱμαρμένῃ ὑπόκειται διὰ τὰς τῆς γενέσεως ἐνεργείας, τῇ δὲ δίκῃ διὰ τὰς ἐν τῷ βίῳ ἁμαρτίας.", "st": "7.3"}, {"sp": "SEC", "t": "VIII", "st": "8.1"}, {"sp": "N", "t": "Ὀρθῶς μοι πάντα εἶπας, ὦ πάτερ. ἀλλ᾽ ἔτι με ἀνάμνησον τίνα ἐστὶ τὰ κατὰ πρόνοιαν, καὶ τίνα κατ᾽ ἀνάγκην ὁμοίως, καὶ καθ᾽ εἱμαρμένην.", "st": "8.1"}, {"sp": "N", "t": "— Ἔφην εἶναι ἐν ἡμῖν, ὦ Τάτ, τρία εἴδη ἀσωμάτων. καὶ τὸ μέν τι ἐστὶ νοητόν. τοῦτο μὲν οὖν ἀχρώματον, ἀσχημάτιστον, ἀσώματον, ἐξ αὐτῆς τῆς πρώτης καὶ νοητῆς οὐσίας.", "st": "8.2"}, {"sp": "N", "t": "εἰσὶ δὲ καὶ ἐν ἡμῖν τούτῳ ἐναντίαι σχηματότητες· τοῦτο ὑποδέχεται. τὸ γοῦν κινούμενον ὑπὸ τῆς νοητῆς οὐσίας πρός τινα λόγον καὶ ὑποδεχθὲν εὐθέως μεταβάλλεται εἰς ἕτερον εἶδος κινήσεως, τοῦτο δὲ εἴδωλόν ἐστι τοῦ νοήματος τοῦ δημιουργοῦ.", "st": "8.3"}, {"sp": "N", "t": "τρίτον δέ ἐστιν εἶδος ἀσωμάτων, ὃ περὶ τὰ σώματά ἐστι συμβεβηκός, τόπος, χρόνος, κίνησις, σχῆμα, ἐπιφάνεια, μέγεθος, εἶδος. καὶ τούτων εἰσὶ διαφοραὶ δύο· ἃ μὲν γάρ ἐστιν αὐτῶν ἰδίως ποιά, ἃ δὲ τοῦ σώματος. τὰ μὲν ἰδίως ποιὰ τὸ σχῆμα, ἡ χρόα, τὸ εἶδος, ὁ τόπος, ὁ χρόνος, ἡ κίνησις· τὰ δὲ τοῦ σώματος ἴδιά ἐστι τὸ ἐσχηματισμένον σχῆμα καὶ τὸ κεχρωσμένον χρῶμα, ἔστι δὲ καὶ ἡ μεμορφωμένη μορφὴ καὶ ἡ ἐπιφάνεια καὶ τὸ μέγεθος. ταῦτά ἐστι τούτων ἀμέτοχα.", "st": "8.4"}, {"sp": "N", "t": "ἡ μὲν οὖν νοητὴ οὐσία, πρὸς τῷ θεῷ γενομένη, ἑαυτῆς ἐξουσίαν ἔχει καὶ τοῦ σώζειν ἕτερον αὑτὴν σώζουσα· ἔπειθ᾽ αὐτὴ ἡ οὖσα ὑπὸ ἀνάγκην οὐκ ἔστιν. ὑπολειφθεῖσα δὲ ὑπὸ τοῦ θεοῦ αἱρεῖται τὴν σωματικὴν φύσιν, καὶ ἡ αἵρεσις αὐτῆς κατὰ πρόνοιαν, τούτῳ δὲ τοῦ κόσμου γίνεται.", "st": "8.5"}, {"sp": "N", "t": "τὸ δὲ ἄλογον πᾶν κινεῖται πρός τινα λόγον.", "st": "8.6"}, {"sp": "N", "t": "καὶ ὁ μὲν λόγος κατὰ πρόνοιαν, τὸ δὲ ἄλογον κατ᾽ ἀνάγκην, τὰ δὲ περὶ τὸ σῶμα συμβεβηκότα καθ᾽ εἱμαρμένην. καὶ οὗτός ἐστιν ὁ λόγος τῶν κατὰ πρόνοιαν καὶ ἀνάγκην καὶ καθ᾽ εἱμαρμένην.", "st": "8.7"}, {"sp": "SEC", "t": "IX", "st": "9.1"}, {"sp": "N", "t": "Καὶ γέγονεν, ὦ τέκνον, ἡ ὕλη καὶ ἦν. ὕλη γὰρ ἀγγεῖον γενέσεώς ἐστι· γένεσις δὲ ἐνεργείας τόπος τοῦ ἀγεννήτου καὶ προόντος τοῦ θεοῦ. τὸ σπέρμα οὖν τῆς γενέσεως λαμβάνουσα γέγονε.", "st": "9.1"}, {"sp": "N", "t": "καὶ τρεπτὴ ἐγένετο, καὶ ἰδέας εἶχε μορφοποιουμένη· ἐφέστηκε γὰρ αὐτῇ τρεπομένῃ ἡ τεχνιτεύουσα τὰς τῆς τροπῆς ἰδέας. ἀγεννησία οὖν τῆς ὕλης ἀμορφία ἦν, ἡ δὲ γένεσις τὸ ἐνεργεῖσθαι.", "st": "9.2"}, {"sp": "SEC", "t": "X", "st": "10.1"}, {"sp": "N", "t": "ὡς καὶ περὶ τῶν τριῶν χρόνων εὑρεῖν. οὔτε γὰρ καθ᾽ ἑαυτούς εἰσιν οὔτε συνήνωνται· καὶ πάλιν, συνήνωνται καὶ καθ᾽ ἑαυτούς εἰσιν.", "st": "10.1"}, {"sp": "N", "t": "ἐὰν χωρὶς εἶναι τοῦ παρεληλυθότος ὑπολάβῃς τὸν ἐνεστῶτα, ἀδύνατόν ἐστιν ἐνεστῶτα εἰ μὴ καὶ παρεληλυθὼς γένηται· ἐκ γὰρ τοῦ ἀποιχομένου τὸ ἐνεστὸς γίνεται, καὶ ἐκ τοῦ ἐνεστῶτος τὸ μέλλον ἔρχεται.", "st": "10.2"}, {"sp": "N", "t": "εἰ δὲ δεῖ καὶ ἐπὶ πλέον βασανίσαι, οὕτω λογισώμεθα· τὸν μὲν παρεληλυθότα χρόνον οἴχεσθαι εἰς τὸ μηκέτι οἴχεσθαι εἰς τὸ μηκέτι εἶναι τοῦτον, τὸν δὲ μέλλοντα μὴ ὑπάρχειν, ἐν τῷ μηδέπω παρεῖναι· ἀλλὰ μηδὲ τὸν ἐνεστῶτα συμπαρεῖναι, ἐν τῷ μένειν. ὃς γὰρ οὐχ ἕστηκε ῥοπήν, ἔχων οὐδὲ κέντρου μονὴν χρόνου, πῶς ἐνεστὼς εἶναι λέγεται, ὁ μηδὲ ἑστάναι δυνάμενος;", "st": "10.3"}, {"sp": "N", "t": "καὶ πάλιν ὁ παρεληλυθὼς συνάπτων τῷ ἐνεστῶτι, καὶ ὁ ἐνεστὼς τῷ μέλλοντι, εἷς γίνεται· οὐ γὰρ χωρὶς αὐτῶν εἰσι τῇ ταυτότητι καὶ τῇ ἑνότητι καὶ τῇ συνεχείᾳ.", "st": "10.4"}, {"sp": "N", "t": "οὕτω καὶ συνεχὴς καὶ διεστὼς γίνεται, εἷς ὢν καὶ ὁ αὐτὸς χρόνος.", "st": "10.5"}, {"sp": "SEC", "t": "XI", "st": "11.1"}, {"sp": "N", "t": "νῦν δέ, ὦ τέκνον, κεφαλαίοις τὰ ὄντα διεξελεύσομαι· νοήσεις γὰρ τὰ λεγόμενα, μεμνημένος ὧν ἤκουσας.", "st": "11.1"}, {"sp": "N", "t": "(1) πάντα τὰ ὄντα κινεῖται· μόνον τὸ μὴ ὂν ἀκίνητον.", "st": "11.2"}, {"sp": "N", "t": "(2) πᾶν σῶμα μεταβλητόν· οὐ πᾶν σῶμα διαλυτόν. ἔνια τῶν σωμάτων διαλυτά.", "st": "11.2"}, {"sp": "N", "t": "(3) οὐ πᾶν ζῷον θνητόν· οὐ πᾶν ζῷον ἀθάνατον.", "st": "11.2"}, {"sp": "N", "t": "(4) τὸ διαλυτὸν φθαρτόν· τὸ μόνον ἀδιάλυτον ἀίδιον.", "st": "11.2"}, {"sp": "N", "t": "(5) τὸ ἀεὶ γινόμενον ἀεὶ καὶ φθείρεται, τὸ δὲ ἅπαξ γενόμενον οὐδέποτε φθείρεται οὐδὲ ἄλλο τι γίνεται.", "st": "11.2"}, {"sp": "N", "t": "(6) πρῶτον ὁ θεός, δεύτερον ὁ κόσμος, τρίτον ὁ ἄνθρωπος.", "st": "11.2"}, {"sp": "N", "t": "(7) ὁ κόσμος διὰ τὸν ἄνθρωπον, ὁ δὲ ἄνθρωπος διὰ τὸν θεόν.", "st": "11.2"}, {"sp": "N", "t": "(8) ψυχῆς τὸ μὲν αἰσθητὸν θνητόν, τὸ δὲ λογικὸν ἀθάνατον.", "st": "11.2"}, {"sp": "N", "t": "(9) πᾶσα οὐσία ἀθάνατος· πᾶσα οὐσία μεταβλητή.", "st": "11.2"}, {"sp": "N", "t": "(10) πᾶν τὸ ὂν διττόν· οὐδὲν τῶν ὄντων ἕστηκεν.", "st": "11.2"}, {"sp": "N", "t": "(11) οὐ πάντα ψυχῇ κινεῖται, πᾶν δὲ ὂν ψυχὴ κινεῖ.", "st": "11.2"}, {"sp": "N", "t": "(12) πᾶν τὸ πάσχον αἴσθεται· πᾶν τὸ αἰσθόμενον πάσχει.", "st": "11.2"}, {"sp": "N", "t": "(13) πᾶν τὸ λυπούμενον καὶ ἥδεται, ζῷον θνητόν· οὐ πᾶν τὸ ἡδόμενον λυπεῖται, ζῷον ἀίδιον.", "st": "11.2"}, {"sp": "N", "t": "(14) οὐ πᾶν σῶμα νοσεῖ· πᾶν σῶμα νοσοῦν διαλυτόν.", "st": "11.2"}, {"sp": "N", "t": "(15) ὁ νοῦς ἐν τῷ θεῷ· ὁ λογισμὸς ἐν τῷ ἀνθρώπῳ· ὁ λόγος ἐν τῷ νοΐ. ὁ νοῦς ἀπαθής.", "st": "11.2"}, {"sp": "N", "t": "(16) οὐδὲν ἐν σώματι ἀληθές· ἐν ἀσωμάτῳ τὸ πᾶν ἀψευδές.", "st": "11.2"}, {"sp": "N", "t": "(17) πᾶν τὸ γενόμενον μεταβλητόν· οὐ πᾶν τὸ γενόμενον φθαρτόν.", "st": "11.2"}, {"sp": "N", "t": "(18) οὐδὲν ἀγαθὸν ἐπὶ τῆς γῆς· οὐδὲν κακὸν ἐν τῷ οὐρανῷ.", "st": "11.2"}, {"sp": "N", "t": "(19) ὁ θεὸς ἀγαθός· ὁ ἄνθρωπος κακός.", "st": "11.2"}, {"sp": "N", "t": "(20) τὸ ἀγαθὸν ἑκούσιον· τὸ κακὸν ἀκούσιον.", "st": "11.2"}, {"sp": "N", "t": "(21) οἱ θεοὶ τὰ ἀγαθὰ αἱροῦνται ὡς ἀγαθά.", "st": "11.2"}, {"sp": "N", "t": "(22) ἡ εὐνομία μεγάλη εὐνομία ἡ εὐνομία ὁ νόμος.", "st": "11.2"}, {"sp": "N", "t": "(23) θεῖος χρόνος νόμος ἀνθρώπινος.", "st": "11.2"}, {"sp": "N", "t": "(24) κακία κόσμου τρυφὴ χρόνος ἀνθρώπου φθορά.", "st": "11.2"}, {"sp": "N", "t": "(25) πᾶν ἐν οὐρανῷ ἀμετάθετον· πᾶν τὸ ἐπὶ γῆς μεταθετόν.", "st": "11.2"}, {"sp": "N", "t": "(26) οὐδὲν ἐν οὐρανῷ δοῦλον· οὐδὲν ἐπὶ γῆς ἐλεύθερον.", "st": "11.2"}, {"sp": "N", "t": "(27) οὐδὲν ἄγνωστον ἐν οὐρανῷ· οὐδὲν γνώριμον ἐπὶ τῆς γῆς.", "st": "11.2"}, {"sp": "N", "t": "(28) οὐ κοινωνεῖ τὰ ἐπὶ γῆς τοῖς ἐν οὐρανῷ.", "st": "11.2"}, {"sp": "N", "t": "(29) πάντα τὰ ἐν οὐρανῷ ἄμωμα· πάντα τὰ ἐπὶ γῆς ἐπίμωμα.", "st": "11.2"}, {"sp": "N", "t": "(30) τὸ ἀθάνατον οὐ θνητόν· τὸ θνητὸν οὐκ ἀθάνατον.", "st": "11.2"}, {"sp": "N", "t": "(31) τὸ σπαρὲν οὐ πάντως γενητόν, τὸ δὲ γενητὸν πάντως καὶ σπαρέν.", "st": "11.2"}, {"sp": "N", "t": "(32) διαλυτοῦ σώματος δύο χρόνοι, ὁ ἀπὸ τῆς σπορᾶς μέχρι τῆς γενέσεως καὶ ὁ ἀπὸ τῆς γενέσεως μέχρι τοῦ θανάτου· τοῦ ἀιδίου σώματος χρόνος ἐκ τῆς γενέσεως μόνος.", "st": "11.2"}, {"sp": "N", "t": "(33) τὰ διαλυτὰ σώματα αὔξεται καὶ μειοῦται.", "st": "11.2"}, {"sp": "N", "t": "(34) ἡ διαλυτὴ ὕλη εἰς τὰ ἐναντία ἐναλλοιοῦται, φθορὰν καὶ γένεσιν, ἡ δὲ ἀίδιος ἢ εἰς αὐτὴν ἢ εἰς τὰ ὅμοια.", "st": "11.2"}, {"sp": "N", "t": "(35) γένεσις ἀνθρώπου φθορά, φθορὰ ἀνθρώπου γενέσεως ἀρχή.", "st": "11.2"}, {"sp": "N", "t": "(36) τὸ ἀπογιγνόμενον καὶ ἀπογίγνεται.", "st": "11.2"}, {"sp": "N", "t": "(37) τῶν ὄντων τὰ μὲν ἐν σώμασίν εἰσι, τὰ δὲ ἐν ἰδέαις, τὰ δὲ ἐνεργείαις· σῶμα δὲ ἐν ἰδίαις, ἰδέα δὲ καὶ ἐνέργεια ἐν σώματί ἐστι.", "st": "11.2"}, {"sp": "N", "t": "(38) τὸ ἀθάνατον οὐ μετέχει τοῦ θνητοῦ, τὸ δὲ θνητὸν τοῦ ἀθανάτου μετέχει.", "st": "11.2"}, {"sp": "N", "t": "(39) τὸ μὲν θνητὸν εἰς ἀθάνατον σῶμα οὐκ ἔρχεται, τὸ δὲ ἀθάνατον εἰς θνητὸν παραγίνεται.", "st": "11.2"}, {"sp": "N", "t": "(40) αἱ ἐνέργειαι οὐκ εἰσὶν ἀνωφερεῖς, ἀλλὰ κατωφερεῖς.", "st": "11.2"}, {"sp": "N", "t": "(41) οὐδὲν ὠφελεῖ τὰ ἐπὶ γῆς τὰ ἐν οὐρανῷ· πάντα ὠφελεῖ τὰ ἐπὶ γῆς τῶν ἐν οὐρανῷ.", "st": "11.2"}, {"sp": "N", "t": "(42) ὁ οὐρανὸς σωμάτων ἀιδίων δεκτικός· ἡ γῆ σωμάτων φθαρτῶν δεκτική.", "st": "11.2"}, {"sp": "N", "t": "(43) ἡ γῆ ἄλογος· ὁ οὐρανὸς λογικός.", "st": "11.2"}, {"sp": "N", "t": "(44) τὰ ἐν οὐρανῷ ὑπόκειται· τὰ ἐπὶ γῆς τῇ γῇ ἐπίκειται.", "st": "11.2"}, {"sp": "N", "t": "(45) ὁ οὐρανὸς πρῶτον στοιχείων· ἡ γῆ ὕστατον στοιχείων.", "st": "11.2"}, {"sp": "N", "t": "(46) πρόνοια θεία τάξις· ἀνάγκη προνοίᾳ ὑπηρέτις.", "st": "11.2"}, {"sp": "N", "t": "(47) τύχη φορὰ ἀτάκτου ἐνεργείας· εἴδωλον δόξα ψευδής.", "st": "11.2"}, {"sp": "N", "t": "(48) τί θεός; ἄτρεπτον, ἀγαθόν. τί ἄνθρωπος; ἄτρεπτον, κακόν.", "st": "11.2"}, {"sp": "N", "t": "τούτων τῶν κεφαλαίων μεμνημένος, καὶ ὧν σοι διὰ πλειόνων λόγων διεξῆλθον εὐκόλως ἀναμνησθήσῃ· ταῦτα γὰρ ἐκείνων εἰσὶ περιοχαί.", "st": "11.3"}, {"sp": "N", "t": "τὰς μέντοι πρὸς τοὺς πολλοὺς ὁμιλίας παραιτοῦ· φθονεῖν μὲν γάρ σε οὐ βούλομαι, μᾶλλον δὲ ὅτι τοῖς πολλοῖς δόξεις καταγέλαστος εἶναι. τὸ γὰρ ὅμοιον πρὸς τὸ ὅμοιον παραλαμβάνεται, ἀνόμοιος δὲ ἀνομοίῳ οὐδέποτε φίλος. οὗτοι δὲ οἱ λόγοι ὀλίγους παντελῶς τοὺς ἀκροατὰς ἕξουσιν, ἢ τάχα οὐδὲ τοὺς ὀλίγους ἕξουσιν.", "st": "11.4"}, {"sp": "N", "t": "ἔχουσι δέ τι καὶ ἴδιον ἐν ἑαυτοῖς· τοὺς κακοὺς μᾶλλον παροξύνουσι πρὸς τὴν κακίαν. διὸ χρὴ τοὺς πολλοὺς φυλάττεσθαι, μὴ νοοῦντας τῶν λεγομένων τὴν ἀρετήν. — Πῶς εἶπας, ὦ πάτερ; — Οὕτως, ὦ τέκνον. πᾶν τὸ ζῷον τῶν ἀνθρώπων ἐπιρρεπέστερόν ἐστιν εἰς τὴν κακίαν· καὶ ταύτῃ σύντροφον γίγνεται, διὸ καὶ ἥδεται αὐτῇ. τοῦτο δὲ τὸ ζῷον ἐὰν μάθῃ ὅτι γενητὸς ὁ κόσμος, καὶ πάντα κατὰ πρόνοιαν καὶ ἀνάγκην γίνεται, εἱμαρμένης πάντων ἀρχούσης, οὐ πολλῷ ἑαυτοῦ χεῖρον ἔσται, καταφρονῆσαν μὲν τοῦ παντὸς ὡς γενητοῦ, τὰς δὲ αἰτίας τοῦ κακοῦ τῇ εἱμαρμένῃ ἀναφέρον, οὐδ᾽ ἀφέξεταί ποτε παντὸς ἔργου κακοῦ. διὸ φυλακτέον αὐτούς, ὅπως ἐν ἀγνοίᾳ ὄντες ἔλαττον ὦσι κακοὶ φόβῳ τοῦ ἀδήλου.", "st": "11.5"}, {"sp": "SEC", "t": "XII", "st": "12.1"}, {"sp": "N", "t": "πάντα δὲ γίνεται φύσει καὶ εἱμαρμένῃ, καὶ οὐκ ἔστι τόπος ἔρημος προνοίας. πρόνοια δέ ἐστιν αὐτοτελὴς λόγος τοῦ ἐπουρανίου θεοῦ· δύο δὲ τούτου αὐτοφυεῖς δυνάμεις, ἀνάγκη καὶ εἱμαρμένη.", "st": "12.1"}, {"sp": "N", "t": "ἡ δὲ εἱμαρμένη ὑπηρετεῖ προνοίᾳ καὶ ἀνάγκῃ. τῇ δὲ εἱμαρμένῃ ὑπηρετοῦσιν οἱ ἀστέρες. οὔτε γὰρ εἱμαρμένην φυγεῖν τις δύναται, οὔτε φυλάξαι ἑαυτὸν ἀπὸ τῆς τούτων δεινότητος. ὅπλον γὰρ εἱμαρμένης οἱ ἀστέρες· κατὰ γὰρ ταύτην πάντα ἀποτελοῦσι τῇ φύσει καὶ τοῖς ἀνθρώποις.", "st": "12.2"}, {"sp": "SEC", "t": "XIII", "st": "13.1"}, {"sp": "N", "t": "ἀνάγκη ἐστὶ κρίσις βεβαία καὶ ἀμετάτρεπτος δύναμις προνοίας.", "st": "13.1"}, {"sp": "SEC", "t": "XIV", "st": "14.1"}, {"sp": "N", "t": "καὶ ἡ μὲν διακρατοῦσα τὸν ὅλον κόσμον πρόνοιά ἐστιν· ἡ δὲ συνέχουσα καὶ περιέχουσα ἀνάγκη ἐστίν. εἱμαρμένη δὲ ἄγει καὶ περιάγει πάντα καταναγκάζουσα· φύσις γάρ ἐστιν αὐτῆς τὸ ἀναγκάζειν. αἰτία γενέσεως καὶ φθορᾶς βίου.", "st": "14.1"}, {"sp": "N", "t": "ὁ μὲν οὖν κόσμος πρῶτος ἔχει τὴν πρόνοιαν· πρῶτος γὰρ αὐτῆς τυγχάνει. ἡ δὲ πρόνοια ἐξήπλωται ἐν τῷ οὐρανῷ. διότι καὶ θεοὶ περὶ αὐτὸν στρέφονται καὶ κινοῦνται ἀκάματον καὶ ἄπαυστον κίνησιν ἔχοντες. εἱμαρμένη δὲ διότι καὶ ἀνάγκη. καὶ ἡ μὲν πρόνοια προνοεῖ, εἱμαρμένη δὲ αἰτία ἐστὶ τῆς τῶν ἄστρων διαθέσεως. οὗτος νόμος ἄφυκτος καθ᾽ ὃν πάντα τέτακται.", "st": "14.2"}, {"sp": "SEC", "t": "XV", "st": "15.1"}, {"sp": "N", "t": "κινεῖται δὲ τὸ κινούμενον κατ᾽ ἐνέργειαν τῆς κινήσεως, τῆς κινούσης τὸ πᾶν. ἡ γὰρ φύσις τοῦ παντὸς τῷ παντὶ παρέχει κινήσεις, μίαν μὲν τὴν κατὰ δύναμιν αὐτῆς, ἑτέραν δὲ τὴν κατ᾽ ἐνέργειαν· καὶ ἡ μὲν διήκει διὰ τοῦ σύμπαντος κόσμου καὶ ἐντὸς συνέχει, ἡ δὲ παρήκει καὶ ἐκτὸς περιέχει. καὶ διὰ πάντων πεφοιτήκασι κοινῇ.", "st": "15.1"}, {"sp": "N", "t": "καὶ ἡ φύσις, πάντα φύουσα τὰ γιγνόμενα, φυὴν παρέχει τοῖς φυομένοις, σπείρουσα μὲν τὰ ἑαυτῆς σπέρματα γένεσις, ἔχουσα δὲ ὕλην κινητήν. κινουμένη δὲ θερμαίνεται, καὶ γίγνεται ὕλη πῦρ καὶ ὕδωρ, τὸ μὲν σθεναρὸν καὶ ἰσχυρόν, τὸ δὲ πάσχον. τὸ δὲ πῦρ, ἐναντιούμενον τῷ ὕδατι, ἐξήρανε τοῦ ὕδατος, καὶ ἐγένετο ὀχουμένη ἐπὶ τοῦ ὕδατος. περιξηραινομένων δέ, ἀτμὸς ἐγένετο ἐκ τῶν τριῶν, τοῦ τε ὕδατος τῆς γῆς καὶ τοῦ πυρός, καὶ ἐγένετο ἀήρ.", "st": "15.2"}, {"sp": "N", "t": "ταῦτα συνῆλθε κατὰ τὸν τῆς ἁρμονίας λόγον, θερμὸν ψυχρῷ, ξηρὸν ὑγρῷ, καὶ ἐκ τῆς συμπνοίας τούτων ἐγένετο", "st": "15.3"}, {"sp": "N", "t": "πνεῦμα καὶ σπέρμα ἀνάλογον τῷ περιέχοντι πνεύματι. τοῦτο δέ, ἐς τὴν μήτραν ἐμπεσόν, οὐκ ἠρεμεῖ ἐν τῷ σπέρματι· οὐκ ἠρεμοῦν δέ, μεταβάλλει τὸ σπέρμα· μεταβαλλόμενον δὲ αὔξην ἴσχει καὶ μέγεθος· ἐπὶ τῷ μεγέθει δὲ εἴδωλον ἐπισπᾶται σχήματος, καὶ σχηματίζεται· ὀχεῖται δὲ ἐπὶ τῷ σχήματι τὸ εἶδος, δι᾽ οὗ καὶ εἰδωλοποιεῖται τὸ εἰδωλοποιούμενον.", "st": "15.4"}, {"sp": "N", "t": "ἐπεὶ τοίνυν τὸ πνεῦμα οὐκ εἶχεν ἐν τῇ νηδύι τὴν ζωτικὴν κίνησιν, τὴν δὲ βλαστικήν, καὶ ταύτην ἥρμοσεν ἁρμονία, ὑποδοχὴν οὖσαν τῆς διανοητικῆς ζωῆς. ἔστι δὲ αὕτη ἀμερὴς καὶ ἀμετάβλητος, οὐδέποτε ἐξισταμένη τῆς ἀμεταβλησίας. τὸ δ᾽ ἐν τῇ νηδύι ἀριθμοῖς λοχεύει καὶ μαιοῦται, καὶ εἰς τὸν ἔξω ἀέρα ἄγει.", "st": "15.5"}, {"sp": "N", "t": "καὶ ἐγγυτάτω ψυχὴ οὖσα οἰκειοῦται, οὐ κατὰ τὴν συγγενικὴν οἰκειότητα, ἀλλὰ τὴν καθ᾽ εἱμαρμένην· οὐ γὰρ ἐρώτων ἐστὶν αὐτῇ μετὰ σώματος εἶναι. διὰ τοῦτο καθ᾽ εἱμαρμένην", "st": "15.6"}, {"sp": "N", "t": "παρέχει τῷ γενομένῳ διανοητικὴν κίνησιν καὶ νοερὰν ζωῆς αὐτῆς οὐσίαν. παρεισέρπει γὰρ τῷ πνεύματι καὶ κινεῖ ζωτικῶς.", "st": "15.7"}, {"sp": "SEC", "t": "XVI", "st": "16.1"}, {"sp": "N", "t": "ψυχὴ τοίνυν οὐσία ἐστὶν ἀσώματος· καὶ ἐν σώματι δὲ οὖσα οὐκ ἐκβαίνει τῆς ἰδίας οὐσιότητος. τυγχάνει γὰρ οὖσα ἀεικίνητος κατ᾽ οὐσίαν κατὰ νόησιν αὐτοκίνητος, οὐκ ἔν τινι κινουμένη, οὐ πρός τι, οὐχ ἕνεκέν τινος. προτερεῖ γὰρ τῇ δυνάμει, τὸ δὲ πρότερον οὐ δεῖ τῶν ὑστέρων.", "st": "16.1"}, {"sp": "N", "t": "τὸ ἔν τινι τοίνυν ἐστὶν ὁ τόπος καὶ χρόνος καὶ φύσις· τὸ δὲ πρός τι ἐστὶν ἁρμονία καὶ εἶδος καὶ σχῆμα· τὸ δὲ οὗ ἕνεκα, τὸ σῶμα.", "st": "16.2"}, {"sp": "N", "t": "ἕνεκα γὰρ σώματος καὶ χρόνος καὶ τόπος καὶ φυσική· ταῦτα δὲ κατὰ συγγενικὴν οἰκειότητα κοινωνεῖ ἀλλήλοις. ἐπεὶ τοίνυν τὸ σῶμα ἐδεῖτο τόπου, ἀμήχανον γὰρ ἦν συστῆναι σῶμα ἄνευ τόπου, καὶ μεταβάλλεται φυσικῇ, ἀδύνατον δὲ μεταβολὴν εἶναι ἄνευ χρόνου καὶ τῆς κατὰ φύσιν κινήσεως, οὔτε σώματος οἷόν τε σύστασιν εἶναι ἄνευ ἁρμονίας.", "st": "16.3"}, {"sp": "N", "t": "ἕνεκα τοίνυν τοῦ σώματός ἐστιν ὁ τόπος· παραδεχόμενος γὰρ τὰς τοῦ σώματος μεταβολὰς οὐκ ἐᾷ ἀπόλλυσθαι τὸ μεταβαλλόμενον. μεταβαλλόμενον δὲ ἀπὸ ἑτέρου εἰς ἕτερον μεταπίπτει, καὶ τῆς μὲν ἕξεως στερίσκεται, τοῦ δὲ εἶναι σῶμα οὐχὶ συστατόν· μεταβληθὲν δὲ εἰς ἕτερον, τὴν τοῦ ἑτέρου ἕξιν ἔχει. τὸ γὰρ σῶμα, ᾗ σῶμα, μένει σῶμα, ἡ δὲ ποιὰ διάθεσις οὐ μένει. τὸ σῶμα τοίνυν κατὰ διάθεσιν μεταβάλλεται.", "st": "16.4"}, {"sp": "N", "t": "ἀσώματος τοίνυν ὁ τόπος καὶ ὁ χρόνος καὶ ἡ φυσικὴ κίνησις.", "st": "16.5"}, {"sp": "N", "t": "τυγχάνει δὲ ἕκαστον τούτων τῆς ἰδίας ἰδιότητος· ἰδιότης δὲ τοῦ τόπου παραδοχή, χρόνου δὲ διάστημα καὶ ἀριθμός, φύσεως δὲ κίνησις, ἁρμονίας δὲ φιλία, σώματος δὲ μεταβολή. ἰδιότης δὲ ψυχῆς ἡ κατ᾽ οὐσίαν νόησις.", "st": "16.6"}, {"sp": "SEC", "t": "XVII", "st": "17.1"}, {"sp": "N", "t": "ψυχὴ τοίνυν ἐστίν, ὦ Ἄμμων, οὐσία αὐτοτελὴς ἐν ἀρχῇ· ἑλομένη βίον τὸν καθ᾽ εἱμαρμένην, καὶ ἐπεσπάσατο ἑαυτῇ λόγον ὅμοιον τῇ ὕλῃ", "st": "17.1"}, {"sp": "N", "t": "ἔχοντα θυμὸν καὶ ἐπιθυμίαν. καὶ ὁ μὲν θυμὸς ὑπάρχει ὕλη. οὗτος, ἐὰν ἕξιν ποιήσῃ πρὸς τὸ τῆς ψυχῆς νόημα, γίνεται ἀνδρεία, καὶ οὐ παράγεται ὑπὸ δειλίας· ἡ δὲ ἐπιθυμία παρέχεται. αὕτη, ἐὰν ἕξιν ποιήσηται πρὸς τὸν τῆς ψυχῆς λογισμόν, γίνεται σωφροσύνη, καὶ οὐ κινεῖται ὑπὸ ἡδονῆς.", "st": "17.2"}, {"sp": "N", "t": "ἀναπληροῖ γὰρ ὁ λογισμὸς τὸ ἐνδέον τῆς ἐπιθυμίας. ὅταν δὲ ἀμφότερα ὁμονοήσῃ καὶ ἴσην ἕξιν ποιήσῃ, καὶ ἔχηται ἀμφότερα τοῦ τῆς ψυχῆς λογισμοῦ, γίνεται δικαιοσύνη· ἡ γὰρ ἴση ἕξις αὐτῶν ἀφαιρεῖ μὲν τὴν ὑπερβολὴν τοῦ θυμοῦ, ἐπανισοῖ δὲ τὸ ἐνδέον τῆς ἐπιθυμίας.", "st": "17.3"}, {"sp": "N", "t": "ἀρχὴ δὲ τούτων ἡ διανοητικὴ οὐσία, καθ᾽ αὑτὴν ἑαυτὴ οὖσα ἐν τῷ αὑτῆς περινοητικῷ λόγῳ, κράτος ἔχουσα τὸν ἑαυτῆς λόγον.", "st": "17.4"}, {"sp": "N", "t": "ἄρχει δὲ καὶ ἡγεμονεύει ἡ οὐσία ὥσπερ ἄρχων, ὁ δὲ λόγος αὐτῆς ὥσπερ σύμβουλος.", "st": "17.5"}, {"sp": "N", "t": "ὁ περινοητικὸς λόγος τοίνυν τῆς οὐσίας ἐστὶ γνῶσις τῶν λογισμῶν τῶν παρεχόντων εἴκασμα λογισμοῦ τῷ ἀλόγῳ, ἀμυδρὸν μὲν ὡς πρὸς λογισμόν, λογισμὸν δὲ ὡς πρὸς τὸ ἄλογον, καθάπερ ἠχὼ πρὸς φωνὴν καὶ τὸ τῆς σελήνης λαμπρὸν πρὸς ἥλιον.", "st": "17.6"}, {"sp": "N", "t": "ἥρμοσται δὲ θυμὸς καὶ ἐπιθυμία πρός τινα λογισμόν, καὶ ἀνθέλκει ἄλληλα, καὶ ἐπίσταται ἐν ἑαυτοῖς κυκλικὴν διάνοιαν.", "st": "17.7"}, {"sp": "SEC", "t": "XVIII", "st": "18.1"}, {"sp": "N", "t": "ἔστι τοίνυν οὐσία καὶ λόγος καὶ νόημα καὶ διάνοια. φέρεται δὲ ἐπὶ τὴν οὐσίαν. φέρεται δ᾽ ἐπὶ τὴν διάνοιαν καὶ δόξα καὶ αἴσθησις. ἴεται δ᾽ ὁ λόγος ἐπὶ τὴν οὐσίαν. τὸ δὲ νόημα δι᾽ αὐτοῦ ἴεται. ἐπιπλέκεται δὲ τὸ νόημα τῇ διανοίᾳ· ἐλθόντα δὲ δι᾽ ἀλλήλων μία ἰδέα ἐγένοντο. αὕτη δέ ἐστιν ἡ τῆς ψυχῆς. φέρεται δ᾽ ἐπὶ τὴν αὐτῆς διάνοιαν δόξα καὶ αἴσθησις. ταῦτα δὲ ἐπὶ τοῦ αὐτοῦ οὐ μένει.", "st": "18.1"}, {"sp": "N", "t": "ἔνθεν καὶ ὑπερβάλλει καὶ ἐλλείπει, καὶ ἑαυτῷ διαφέρεται. χεῖρον μὲν γίνεται ὅταν ἀποσπασθῇ τῆς διανοίας· ὅταν δὲ ἀκολουθῇ καὶ πείθηται, κοινωνεῖ τῷ νοηματικῷ λόγῳ διὰ τῶν μαθημάτων.", "st": "18.2"}, {"sp": "N", "t": "τὸ δὲ αἱρεῖσθαι ἔχομεν· τὸ γὰρ αἱρεῖσθαι τὸ κρεῖττον ἐφ᾽ ἡμῖν ἐστίν, ὁμοίως δὲ καὶ τὸ χεῖρον ἀκουσίως· ἐχομένη γὰρ αἵρεσις τῶν κακῶν πλησιάζει τῇ σωματικῇ φύσει, διὰ τοῦτο τῷ ἑλομένῳ εἱμαρμένη δυναστεύει.", "st": "18.3"}, {"sp": "N", "t": "ἐπεὶ τοίνυν ἡ ἐν ἡμῖν σωματικὴ οὐσία αὐτεξούσιός ἐστιν ὁ περινοηματικὸς λόγος, αὕτη δ᾽ ἀεὶ κατὰ ταὐτὰ καὶ ὡσαύτως ἔχει, διὰ τοῦτο εἱμαρμένη ταύτης οὐχ ἅπτεται.", "st": "18.4"}, {"sp": "N", "t": "παραθεῖσα δὲ τὸν πρῶτον ἀπὸ τοῦ πρώτου θεοῦ διανοητικὸν λόγον προίησι καὶ ὅλον τὸν λόγον ὃν συνέταξε φύσις τοῖς γιγνομένοις· τούτοις ψυχὴ κοινωνήσασα κοινωνεῖ καὶ τῆς τούτων εἱμαρμένης, ἀμέτοχος οὖσα τῆς τῶν γινομένων φύσεως.", "st": "18.5"}, {"sp": "SEC", "t": "XIX", "st": "19.1"}, {"sp": "N", "t": "ψυχὴ τοίνυν ἐστὶν ἀίδιος νοητικὴ οὖσα νόημα ἔχουσα τὸν ἑαυτῆς λόγον. συννοοῦσα δὲ διάνοιαν τῆς ἁρμονίας ἐπισπᾶται. ἀπαλλαγεῖσα δὲ τοῦ φυσικοῦ σώματος, αὐτὴ καθ᾽ αὑτὴν μένει αὐτὴ ἑαυτῆς οὖσα ἐν τῷ νοητῷ κόσμῳ. ἄρχει δὲ τοῦ ἑαυτῆς λόγου φέρουσα ὁμοίαν κίνησιν ἐν τῷ ἑαυτῆς νοήματι ὀνόματι ζωὴν τῷ εἰς ζωὴν ἐρχομένῳ.", "st": "19.1"}, {"sp": "N", "t": "τοῦτο γὰρ ἴδιον ψυχῆς, τὸ παρέχειν ἑτέροις ὅμοιον τῇ ἰδιότητι αὐτῆς.", "st": "19.2"}, {"sp": "N", "t": "δύο τοίνυν εἰσὶ ζωαὶ καὶ δύο κινήσεις, μία μὲν ἡ κατ᾽ οὐσίαν, ἑτέρα δὲ ἡ κατὰ φύσιν σώματος. καὶ ἡ μὲν γενικωτέρα καὶ ἡ κατ᾽ οὐσίαν αὐτεξούσιος, ἡ δὲ ἀναγκαστική· πᾶν γὰρ τὸ κινούμενον τῇ τοῦ κινοῦντος ἀνάγκῃ ὑποτέτακται.", "st": "19.3"}, {"sp": "N", "t": "ἡ δὲ κινοῦσα κίνησις τῷ τῆς νοητικῆς οὐσίας ἔρωτι ᾠκείωται. εἴη γὰρ ἂν ψυχὴ ἀσώματος ἀμέτοχος οὐσία τοῦ φυσικοῦ σώματος. εἰ γὰρ ἔχει σῶμα, οὔτε λόγον ἔχει οὔτε νόησιν. πᾶν γὰρ σῶμα ἀνόητον· μεταλαβὸν δὲ οὐσίας, τὸ εἶναι ζῷον ἔμπνουν ἔσχε.", "st": "19.4"}, {"sp": "N", "t": "καὶ τὸ μὲν πνεῦμα τοῦ σώματος, ὁ δὲ λόγος τῆς οὐσίας τοῦ καλοῦ θεωρητικός ἐστι, τὸ δὲ αἰσθητικὸν πνεῦμα τῶν φαινομένων κριτικόν ἐστι. διῄρηται δὲ εἰς τὰς ὀργανικὰς αἰσθήσεις, καὶ ἔστι τι μέρος αὐτοῦ πνευματικὴ ὁρατικὸν καὶ ἀκουστικὸν καὶ ὀσφρητικὸν καὶ γευστικὸν καὶ ἁπτικόν. τοῦτο τὸ πνεῦμα ἀνάγον γενόμενον διανοίας κρίνει τὸ αἰσθητικόν· εἰ δὲ μή, φαντάζεται μόνον.", "st": "19.5"}, {"sp": "N", "t": "τοῦ γὰρ σώματός ἐστι καὶ δεκτικὸν πάντων, ὁ δὲ λόγος τῆς οὐσίας ἐστὶ τὸ φρονοῦν. συνυπάρχει δὲ τῷ λόγῳ ἡ τῶν τιμίων γνῶσις, τῷ δὲ πνεύματι ἡ δόξα.", "st": "19.6"}, {"sp": "N", "t": "τὸ μὲν γὰρ ἀπὸ τοῦ περιέχοντος κόσμου τὴν ἐνέργειαν ἔχει, ἡ δὲ ἀφ᾽ ἑαυτῆς.", "st": "19.7"}, {"sp": "SEC", "t": "XX", "st": "20.1"}, {"sp": "N", "t": "ἔστι τοίνυν ἡ ψυχὴ ἀσώματος οὐσία· εἰ γὰρ ἔχει σῶμα, οὐκέτι ἔσται ἑαυτῆς σωστική. πᾶν γὰρ σῶμα δεῖται τοῦ εἶναι, δεῖται καὶ ζωῆς τῆς ἐν τάξει κειμένης.", "st": "20.1"}, {"sp": "N", "t": "παντὶ γὰρ τῷ γένεσιν ἔχοντι καὶ μεταβολὴν δεῖ ἐπακολουθεῖν, τὸ γὰρ γινόμενον γίνεται ἐν μεγέθει, γινόμενον αὔξην ἔχει· παντὶ γὰρ τῷ αὐξανομένῳ ἐπακολουθεῖ μείωσις, μειώσει φθορά.", "st": "20.2"}, {"sp": "N", "t": "μετειληφὸς δὲ εἴδους ζωῆς, ζῇ, καὶ κοινωνεῖ τοῦ εἶναι τῇ ψυχῇ. ἡ δὲ αἰτία ἑτέρῳ τοῦ εἶναι αὐτὴ πρώτως ὂν ἔστι. τὸ δὲ εἶναι νῦν λέγω τὸ ἐν λόγῳ γενέσθαι καὶ μετέχειν ζωῆς νοερᾶς. παρέχει δὲ ἡ ψυχὴ ζωὴν νοεράν.", "st": "20.3"}, {"sp": "N", "t": "καλεῖται δὲ ζῷον μὲν διὰ τὴν ζωήν, λογικὸν δὲ διὰ τὸ νοερόν, θνητὸν δὲ διὰ τὸ σῶμα. ψυχὴ ἄρα ἀσώματος, ἀμετάπτωτον ἔχουσα τὴν δύναμιν. πῶς γὰρ οἷόν τέ ἐστι λέγειν ζῷον νοερόν, μὴ οὔσης οὐσίας τῆς καὶ παρεχούσης ζωήν; ἀλλὰ οὐδὲ λογικὸν οἷόν τέ ἐστιν εἰπεῖν, μὴ οὔσης τῆς διανοητικῆς οὐσίας τῆς καὶ παρεχούσης νοερὰν ζωήν.", "st": "20.4"}, {"sp": "N", "t": "ἐν πᾶσι δὲ οὐκ ἀφικνεῖται τὸ νοερόν, διὰ τὴν τοῦ σώματος σύστασιν πρὸς τὴν ἁρμονίαν. ἐὰν γὰρ ὑπερέχῃ ἐν τῇ συστάσει τὸ θερμόν, κοῦφος καὶ ἔνθερμος γίνεται· ἐὰν δὲ τὸ ψυχρόν, βαρὺς καὶ νωχελὴς γίνεται. φύσις γὰρ ἁρμόζει τὴν τοῦ σώματος σύστασιν πρὸς τὴν ἁρμονίαν.", "st": "20.5"}, {"sp": "N", "t": "εἴδη δὲ τῆς ἁρμονίας τρία, τὸ κατὰ τὸ θερμόν, καὶ τὸ κατὰ ψυχρόν, καὶ τὸ κατὰ τὸ μέσον· ἁρμόζει δὲ κατὰ τὸν ἐπικρατήσαντα ἀστέρα τῆς συγκρατήσεως τῶν ἀστέρων. παραλαβοῦσα δὲ ψυχὴ καθὼς εἴργασται τούτῳ παρέχει ζωὴν τῷ τῆς φύσεως ἔργῳ.", "st": "20.6"}, {"sp": "N", "t": "ἡ φύσις τοίνυν ὁμοιοῖ τὴν ἁρμονίαν τοῦ σώματος τῇ τῶν ἀστέρων συγκράσει, καὶ ἑνοῖ τὰ πολυμιγῆ πρὸς τὴν τῶν ἄστρων ἁρμονίαν ὥστε ἔχειν πρὸς ἄλληλα συμπάθειαν. τέλος γὰρ τῆς τῶν ἀστέρων ἁρμονίας τὸ γεννᾶν συμπάθειαν καθ᾽ εἱμαρμένην αὐτῶν.", "st": "20.7"}, {"sp": "SEC", "t": "XXI", "st": "21.1"}, {"sp": "N", "t": "ἔστι τοίνυν τὸ προὸν ἐπὶ πάντων τῶν ὄντων, καὶ τῶν ὄντως ὄντων προόν. ὂν γάρ ἐστι δι᾽ οὗ ἡ οὐσιότης ἡ καθόλου λεγομένη κοινὴ νοητῶν τῶν ὄντως ὄντων καὶ τῶν ὄντων τῶν καθ᾽ ἑαυτὰ νοουμένων. τὰ δὲ ἐναντία τούτοις κατὰ τὸ ἕτερον πάλιν αὐτὰ καθ᾽ ἑαυτὰ ἔστι. φύσις οὐσία αἰσθητή, ἔχουσα ἐν ἑαυτῇ αἰσθητὰ πάντα. μεταξὺ δὲ τούτων νοηματικοὶ καὶ αἰσθητοὶ θεοί, τὰ μὲν μετέχοντα τῶν νοητῶν, τὰ δὲ δοξαστά, τὰ κοινωνοῦντα τῶν νοηματικῶν", "st": "21.1"}, {"sp": "N", "t": "θεῶν· οὗτοι δὲ εἰκόνες εἰσὶ νοημάτων. οἷον ἥλιος εἰκών ἐστι τοῦ ἐπουρανίου δημιουργοῦ θεοῦ· καθάπερ γὰρ ἐκεῖνος τὸ ὅλον ἐδημιούργησε, καὶ ὁ ἥλιος δημιουργεῖ τὰ ζῷα καὶ γεννᾷ φυτὰ καὶ τῶν πνευμάτων πρυτανεύει.", "st": "21.2"}, {"sp": "SEC", "t": "XXII", "st": "22.1"}, {"sp": "N", "t": "παρὰ τί τὰ βρέφη ὅμοια τοῖς γονεῦσι γίνεται ἢ συγγενείαις ἀποδίδοται ἐκθήσω λόγον. ὅταν νοστίμου αἵματος ἐξαφεδρουμένου ἡ γένεσις ἀποθησαυρίζῃ γόνον, συμβαίνει πως ἐκπνέειν ἐκ τοῦ σώματος ὅλου μελῶν οὐσίαν τινὰ κατὰ θείαν ἐνέργειαν, ὡς τοῦ αὐτοῦ ἀνθρώπου γινομένου. τὸ δ᾽ αὐτὸ καὶ ἐπὶ τῆς γυναικὸς εἰκὸς γίγνεσθαι. ὅταν καθυπερτερήσῃ τὸ ῥυὲν ἀπὸ τοῦ ἀνδρὸς καὶ ἄτηκτον γένηται, τῷ πατρὶ ὁμοιούμενον τὸ βρέφος ἀποδειχθήσεται, ὡς τὸ ἀνάπαλιν τὸν αὐτὸν τρόπον τῇ μητρί. ἐάν τινος μέρους καθυπερτέρησις γένηται, πρὸς ἐκεῖνο τὸ μέρος ἀφομοιοῦται. ἔσθ᾽ ὅτε δὲ καὶ εἰς μακρὰς γενεὰς παραβάλλειν τὸ βρέφος τῇ μορφῇ τοῦ γεννήσαντος, ἐκείνου δεκανοῦ λόγον ἔχοντος πρὸς τὴν ὥραν ἐν ᾗ ἡ γυνὴ ἐπαιδοποίει.", "st": "22.1"}, {"sp": "SEC", "t": "XXIII", "st": "23.1"}, {"sp": "N", "t": "ταῦτα εἰποῦσα Ἶσις ἐγχεῖ ποτὸν Ὥρῳ γλυκύν τι πρῶτον ἀμβροσίας, ὃ αἱ ψυχαὶ λαμβάνειν ἔθος ἔχουσιν θεῶν, καὶ οὕτως τοῦ ἱερωτάτου λόγου ἄρχεται Ἶσις.", "st": "23.1"}, {"sp": "N", "t": "Ἐπικειμένου, τέκνον Ὧρε, τῇ τῶν ὑποκειμένων φύσει πάσῃ τοῦ πολυστέφους οὐρανοῦ, καὶ κατ᾽ οὐδένα τόπον στερουμένου τινὸς ὧν νῦν ὁ σύμπας ἔχει κόσμος, ἀνάγκη πᾶσα ὑπὸ τῶν ὑπερκειμένων συγκεκοσμῆσθαι καὶ πεπληρῶσθαι φύσιν πᾶσαν τὴν ὑποκειμένην· οὐ γὰρ δήπου δυνατὰ κοσμῆσαι τὰ κάτω τὸν ὕπερθεν διάκοσμον. ἀνάγκη τοίνυν τοῖς κρείττοσι μυστηρίοις εἴκειν τὰ ἐλάσσονα· κρείσσων δὲ τῶν ὑποκειμένων ἡ τῶν μετεώρων ἐστὶ διάταξις, καὶ τῷ παντὶ ἀσφαλής τε, καὶ θνητῶν οὐχ ὑποπίπτουσα διανοίᾳ.", "st": "23.2"}, {"sp": "N", "t": "ἔνθεν ἐστέναζον τὰ κάτω φόβον ἔχοντα τὴν περικαλλῆ καὶ εἰς ἀεὶ διαμονὴν τῶν ἐπικειμένων. ἦν γὰρ ἄξιον θεωρίας ὁμοῦ καὶ ἀγωνίας ὁρᾶν οὐρανοῦ κάλλος θεῷ καταφωτιζομένου τῷ ἔτι ἀγνώστῳ, πλουσίαν τε νυκτὸς σεμνότητα, ἐλάττονι μὲν ἡλίου ὀξεῖ δὲ πυρφορουμένης φωτί, τῶν τε ἄλλων κατὰ μέρος κινουμένων ἐν οὐρανῷ μυστηρίων τακταῖς χρόνων κινήσεσι καὶ περιόδοις, διά τινων κρυπτῶν ἀπορροιῶν τὰ κάτω συγκοσμούντων καὶ συναυξόντων. καὶ οὕτως φόβοι μὲν ἐπάλληλοι, ζητήσεις δὲ ἄληκτοι.", "st": "23.3"}, {"sp": "N", "t": "καὶ ἕως ὁ τῶν συμπάντων οὐκ ἐβούλετο τεχνίτης, ἀγνωσία κατεῖχε τὰ ξύμπαντα· ὅτε δὲ ἔκρινεν αὑτὸν ὅστις ἐστὶ δηλῶσαι, ἔρωτας ἐνεθουσίασε θεοῖς, καὶ αὐγὴν ἧς εἶχον ἐν στέρνοις πλείονα ταῖς τούτων ἐχαρίσατο διανοίαις, ἵνα πρῶτον μὲν ζητεῖν θελήσωσιν, εἶτα ἐπιθυμήσωσιν εὑρεῖν, εἶτα καὶ κατορθῶσαι δυνηθῶσι.", "st": "23.4"}, {"sp": "N", "t": "τοῦτο δ᾽ ἄν, ὦ τέκνον ἀξιοθαύμαστον Ὧρε, οὐκ ἂν ἐπὶ θνητῇ σπορᾷ ἐγεγόνει, οὐδὲ γὰρ ἦν οὐδέπω, ψυχῆς δὲ τὴν συμπάθειαν ἐχούσης τοῖς οὐρανοῦ μυστηρίοις. τοῦτο δὲ ἦν ὁ πάντα γνοὺς Ἑρμῆς· ὃς καὶ εἶδε τὰ σύμπαντα, καὶ ἰδὼν κατενόησε, καὶ κατανοήσας ἴσχυσε δηλῶσαί τε καὶ δεῖξαι. καὶ γὰρ ἃ ἐνόησεν ἐχάραξε, καὶ χαράξας ἔκρυψε, τὰ πλεῖστα σιγήσας ἀσφαλῶς ἢ λαλήσας, ἵνα ζητῇ ταῦτα πᾶς αἰὼν ὁ μεταγενέστερος κόσμου.", "st": "23.5"}, {"sp": "N", "t": "καὶ οὗτος τοὺς συγγενεῖς θεοὺς δορυφορεῖν ἀνέβαινεν εἰς ἄστρα· ἀλλ᾽ ἦν αὐτῷ διάδοχος ὁ Τάτ, υἱὸς ὁμοῦ καὶ παραλήπτωρ τῶν μαθημάτων τούτων, οὐκ εἰς μακρὰν δὲ καὶ Ἀσκληπιὸς ὁ Ἰμούθης, ὁ Πανὸς καὶ Ἡφαίστου βουλαῖς, ἄλλοι τε ὅσοι τῆς οὐρανίου θεωρίας πιστῇ ἀκριβείᾳ ἔμελλον βουλομένης τῆς πάντων βασιλίδος ἱστορῆσαι προνοίας.", "st": "23.6"}, {"sp": "N", "t": "Ἑρμῆς μὲν οὖν ἀπελογεῖτο τῷ περιέχοντι ὡς οὐδὲ τῷ παιδὶ παρέδωκεν ὁλοτελῆ θεωρίαν, διὰ τὸ ἔτι τῆς ἡλικίας νεοειδές· «Ἐγὼ δὲ τῆς ἀνατολῆς γενόμενος τοῖς πάντα βλέπουσιν ὀφθαλμοῖς τὰ τῆς ἀνατολῆς θεωρῆσαί τι ἀειδές· καὶ ἐπισκοποῦντι βραδέως μέν, ἀλλ᾽ οὖν ἦλθεν ἡ ἀκριβὴς διάγνωσις πλησίον τῶν Ὀσίριδος κρυφίων ἀποθέσθαι τὰ ἱερὰ τῶν κοσμικῶν στοιχείων σύμβολα, ἐπικατευξάμενον δὲ καὶ τοὺς λόγους τούσδε εἰπόντας εἰς οὐρανὸν ἀπελθεῖν.»", "st": "23.7"}, {"sp": "N", "t": "ἀλλ᾽ οὐ καθῆκον ἀτελῆ τὴν ἀπαγγελίαν, ὦ τέκνον, ταύτην μὲν καταλεῖψαι, εἰπεῖν δ᾽ ὅσα τὰς βίβλους κατατιθέμενος ἐξεῖπεν Ἑρμῆς. ἐξεῖπε γὰρ οὕτως· «Ὦ ἱεραὶ βίβλοι, τῶν ἀφθάρτων αἳ τετεύχαταί μου χειρῶν, ἃς τῷ τῆς ἀφθαρσίας φαρμάκῳ χορείας ἐπικρατῶ, ἀσαπεῖς πάντας αἰῶνας καὶ ἄφθαρτοι διαμείνατε χρόνους, ἀθεώρητοι καὶ ἀνεύρετοι γιγνόμεναι παντὶ τῷ τὰ γῆς ταύτης περιοδεύειν μέλλοντι πεδία, ἄχρις οὗ γέρων οὐρανὸς συστήματα ὑμῶν ἄξια τεκνώσηται ἃς ψυχὰς ὁ δημιουργὸς προσηγόρευσε.» τοσαῦτα εἰπὼν τὰς βίβλους καὶ τοῖς ἑαυτοῦ κατευξάμενος ἔργοις, ἰδίοις τεμενίζεται ζώναις.", "st": "23.8"}, {"sp": "N", "t": "ἱκανὸς δὲ ὁ μέσος ἤργει χρόνος, ἐκέκρυπτο καὶ ἡ φύσις, ὦ τέκνον, ἐτύγχανε στεῖρα, ἕως αὐτοὶ οἱ ἤδη περιπολεῖν τὸν οὐρανὸν κελευσθέντες, τῷ πάντων θεῷ βασιλεῖ προσελθόντες, τὴν τῶν ὄντων ἡσυχίαν ἀπήγγειλαν, καὶ ὅτι δέον ἐστὶ συγκοσμηθῆναι τὰ σύμπαντα καὶ τοῦτο οὐχ ἑτέρου τινός ἐστιν ἔργον ἢ αὐτοῦ· καὶ «Δεόμεθά σου» ἔλεγον «τὰ νῦν ὄντα καὶ ὧν ὕστερον ἔχει χρείαν διασκέψασθαι.»", "st": "23.9"}, {"sp": "N", "t": "ταῦτα εἰπόντων ἐμειδίασεν ὁ θεός, καὶ εἶπε Φύσιν εἶναι. καὶ θῆλυ πάγκαλον χρῆμα ἐκ τῆς φωνῆς αὐτοῦ προῆλθεν, ὃ καὶ θεωρήσαντες οἱ θεοὶ κατεπλάγησαν· καὶ ταύτην Φύσεως ὀνόματι ἐτίμησεν ὁ θεὸς ὁ προπάτωρ. καὶ ταύτην προσέταξεν εἶναι γεννητικήν.", "st": "23.10"}, {"sp": "N", "t": "καὶ ταῦτα ἔτι εἰς τὸ περιέχον ἀτενίσας φώνησεν· «Ἔστω πεπληρωμένος ὁ οὐρανὸς ἅπασιν ἀήρ τε καὶ αἰθήρ.» εἶπεν ὁ θεὸς καὶ ἦν.", "st": "23.11"}, {"sp": "N", "t": "ἡ δὲ Φύσις ἑαυτῇ λαλήσασα ἔγνω ὡς μὴ δέον αὐτήν ἐστι παρακοῦσαι τῆς τοῦ πατρὸς ἐντολῆς· καὶ", "st": "23.12"}, {"sp": "N", "t": "καλὴν Πόνῳ συνελθοῦσαν θυγατέρα ἐποίησεν, ἣν Εὕρεσιν ἐκάλεσε. τῇ δὲ ὁ θεὸς ἐχαρίσατο εἶναι, καὶ χαρισάμενος διέκρινε τὰ ἤδη γεγονότα, καὶ ἐπλήρωσεν αὐτὰ μυστηρίων, καὶ τῇ Εὑρέσει τούτων τὸ κατὰ τούτων ἐχαρίσατο ἡγεμονικόν.", "st": "23.13"}, {"sp": "N", "t": "αὐτὸς δ᾽ οὐκέτι βουλόμενος ἀργὸν τὸν ὑπουράνιον κόσμον εἶναι, ἀλλὰ πνευμάτων πληρῶσαι δοκιμάσας τοῦτον, ὡς μὴ τὰ κατὰ μέρος ἀκίνητα καὶ ἀργὰ μένῃ, οὕτως εἰς ταῦτα ἤρξατο τεχνιτείαις, οὐσίαις πρὸς τὴν τοῦ ἰδίου ἔργου τέλεσιν χρησάμενος ἐπιτηδείαις. πνεῦμα γὰρ ὅσον ἀρκετὸν ἀπὸ τοῦ ἰδίου λαβών, καὶ νοερῷ τοῦτο πυρὶ μίξας, ἀγνώστοις τισὶν ἑτέραις ὕλαις ἐκέρασε· καὶ ταῦτα ἑκάτερον ἑκατέρῳ μετά τινων ἐπιφωνήσεων κρυπτῶν ἑνώσας, τὸ πᾶν οὕτως εὖ μάλα διεκίνησε κρᾶμα, ἕως ἐπεγέλασέ τις ὕλη τῷ μίγματι λεπτοτέρα τε καὶ καθαρωτέρα μᾶλλον καὶ διαφανεστέρα ἢ ἐξ ὧν ἐγίνετο· διειδὴς δὲ ἦν αὕτη, ἣν δὴ καὶ μόνος ὁ τεχνίτης ἑώρα.", "st": "23.14"}, {"sp": "N", "t": "ἐπειδὴ δὲ οὔτε ὡς ἐκ πυρὸς καιομένη διετήκετο, οὔτε μὴν ὡς ἐκ πνεύματος τελεσιουργηθεῖσα ἔψυχε, ἀλλά τινα ἰδιογενῆ καὶ οἰκείαν εἶχε τὴν τοῦ κράματος σύστασιν ἰδιότυπόν τε καὶ ἰδιοσύγκριτον, ἣν δὴ καὶ ἀπὸ τοῦ εὐφημοτέρου ὀνόματος καὶ τῆς καθ᾽ ὁμοιότητα ἐνεργείας ψύχωσιν ὁ θεὸς ἐκάλεσε τὴν σύστασιν. ἐξ οὗ δὴ ἐπιπάγου μυριάδας ψυχῶν ἱκανὰς ἐγενεσιούργησε, τὸ παρ᾽ αὐτοῦ τοῦ κράματος ἐπάνθουν πρὸς ὃ θέλει πλάσσων εὐτάκτως τε καὶ συμμέτρως μετ᾽ ἐμπειρίας καὶ λόγου τοῦ καθήκοντος, ὡς μηδέ τι", "st": "23.15"}, {"sp": "N", "t": "διαφέρειν ἑαυτὰς ἑαυτῶν ἦν ἀναγκαῖον, ἐπειδήπερ τὸ ἐκ τῆς κινήσεως τοῦ θεοῦ ἐξατμιζόμενον ἄνθος οὐκ ἦν ἑαυτῷ ὅμοιον, ἀλλὰ μεῖζον καὶ ὁλοκληρότερον ἦν τοῦ δευτέρου τὸ πρῶτον καὶ τῷ παντὶ καθαρώτερον, τὸ δεύτερον δὲ ἱκανῶς μὲν ἦν τοῦ πρώτου τὸ δεύτερον, πολλῷ δὲ τοῦ τρίτου τὸ μεῖζον, καὶ οὕτως ἄχρι βαθμῶν ἑξήκοντα ὁ πᾶς ἀπήρτιστο ἀριθμός· πλὴν ὅτι γε πάσας ἀιδίους εἶναι νομοθετήσας ἔταξεν, ὡς ἂν ἐκ μιᾶς οὐσίας, ἧς μόνος αὐτὸς ᾔδη τελειῶ. ταῖς δὲ καὶ τμήματα καὶ ταμιεῖα ἐν μεταρσίῳ διέταξε τῆς ἄνω φύσεως οὐρανοῦ, ὅπως τόν τε κύλινδρον περιστροβῶσι τάξει τινὶ καὶ οἰκονομίᾳ καθηκούσῃ, καὶ τὸν πατέρα τέρπωσιν.", "st": "23.16"}, {"sp": "N", "t": "οὕτως δὴ καὶ ἐν τῇ περικαλλεῖ τοῦ αἰθέρος στάσει, καὶ τὰς τῶν ἤδη οὐσῶν μεταπεμψάμενος φυλάς, «Ὦ», φησί, «πνεύματος ἐμοῦ καὶ μερίμνης ἐμῆς ψυχαὶ καλὰ τέκνα, ἃ ταῖς ἐμαυτοῦ μαιωσάμενος χερσὶν ἤδη τῷ ἐμῷ καθιερῶ κόσμῳ, λόγων ἐμῶν ὡς νόμων τούτων ἐπακούσατε, καὶ τόπου μηδενὸς ἄλλου θίγητε πλὴν τοῦ διαταγέντος ὑμῖν ὑπὸ τῆς ἐμῆς γνώμης. εὐσταθησάσαις μὲν οὖν ὑμῖν οὐρανός τε καὶ μένει πάλιν ὁ μισθὸς καὶ ὁ διαταγεὶς ἀστερισμός, θρόνοι τε ἀρετῆς πεπληρωμένοι· εἰ δέ τι νεώτερον παρὰ τἀμὰ πράξητε βουλεύματα, ἱερὸν ὑμῖν ὀμνύω πνεῦμα καὶ κρᾶμα τοῦτ᾽ ἀφ᾽ οὗπερ ὑμᾶς ἐγέννησα, ψυχοποιούς τε ταύτας μου τὰς χεῖρας, ὡς οὐκ εἰς μακρὰν δεσμοὺς καὶ κολάσεις ὑμῖν τεχνιτεύσω.»", "st": "23.17"}, {"sp": "N", "t": "τοσαῦτα εἰπὼν ὁ θεὸς ὁ κἀμοῦ κύριος τὰ λοιπὰ τῶν στοιχείων συγγενῆ μίξας, ὕδωρ καὶ γῆν, καί τινας ὁμοίως κρυπτοὺς ἐπειπὼν λόγους, δυνατοὺς μέν, οὐ τοῖς πρώτοις δ᾽ ὁμοίους, εὖ τε κιρνήσας καὶ ζωοποιὸν ἐνθουσιάσας, τῷ κράματι ἐπιπλέοντα ὁμοίως ἐπίπαγον εὐβαφῆ τε καὶ εὐπαγῆ γενόμενον ἔλαβε, καὶ ἐκ τούτου τὰ ἀνθρωποειδῆ τῶν ζῴων διέπλασε·", "st": "23.18"}, {"sp": "N", "t": "τὸ δὲ τοῦ μίγματος λείψανον ταῖς ἤδη προκοψάσαις ψυχαῖς ἔδωκε, ψυχαῖς δὲ ταύταις ταῖς εἰς χωρία θεῶν καὶ τοὺς ἐγγὺς ἄστρων τόπους καὶ ἱεροῖς δαίμοσι μετακεκλημέναις, «Πλάσσετε» λέγων «ὦ τέκνα, τῆς ἐμῆς φύσεως γεννήματα, δέχεσθε τῆς ἐμῆς τεχνιτείας τὰ λείψανα, καὶ ἑκάστη τῇ ἑαυτῆς φύσει πλασσέτω τι παραπλήσιον· παραθήσομαι δ᾽ ἐγὼ καὶ ταῦθ᾽ ὑμῖν παραδείγματα.» καὶ λαβὼν εὖ καὶ καλῶς", "st": "23.19"}, {"sp": "N", "t": "τὸν ζῳδιακὸν συμφώνως ταῖς ψυχικαῖς κινήσεσι διέταξε κόσμον, πρὸς τοῖς ἀνθρωποειδέσι τῶν ζῳδιακῶν τὰ ἑξῆς ἀπαρτίσας οἷον ζῳδίοις, καὶ τὰς πανούργους ἐχαρισάμην δυνάμεις καὶ πάντεχνον πνεῦμα γεννητικὸν τῶν εἰς ἀεὶ μελλόντων ἔσεσθαι καθολικῶς πάντων.", "st": "23.20"}, {"sp": "N", "t": "καὶ ἀπέστη, ὑποσχόμενος τοῖς ὁρατοῖς ἔργοις αὐτῶν τὰ ὁρατὰ πνεῦμα ἐπιζεῦξαι, οὐσίαν τε ὁμοιογονίας ἑκάστῳ, ὅπως αὑτῷ αὐτοῖς ἕτερα γεννᾷ ὅμοια, αὐτά τε οὐκέτι ἀνάγκην ἔχωσιν ἄλλο τι ποιεῖν ἃ ἔφθησαν ἐργάσασθαι.", "st": "23.21"}, {"sp": "N", "t": "— Τί οὖν, ὦ τεκοῦσα, ἐποίησαν αἱ ψυχαί; — καὶ εἶπεν Ἶσις· Τὸ κεκερασμένον, ὦ τέκνον Ὧρε, τῆς ὕλης λαβοῦσαι κατενόουν πρῶτον καὶ τὸ τοῦ πατρὸς προσεκύνουν κρᾶμα, καὶ ὁπόθεν ἦν συμπεπλεγμένον ἐπεζήτουν· τὸ δὲ ἦν αὐταῖς οὐκ εὔπορον ἐπιγνῶναι. ἔνθεν δὴ καὶ ὅτι ἐπεζήτησαν ἐφοβοῦντο μὴ τῷ τοῦ πατρὸς ὑποπέσωσι χόλῳ· καὶ ἐπὶ τὸ πράττειν τὰ προσταχθέντα ἐτράπησαν.", "st": "23.22"}, {"sp": "N", "t": "ἔνθεν ἐκ μὲν τῆς ἀνωτέρω ὕλης, τῆς ὑπερβολῇ κοῦφον ἐχούσης τὸν ἐπίπαγον, τὸ τῶν ὀρνέων γένος εὐμόρφουν, ἐν τούτῳ δ᾽ ἡμιπαγοῦς ἤδη τοῦ κράματος γενομένου καὶ ἤδη τὴν στερεὰν πῆξιν λαβόντος τὸ τῶν τετραπόδων γένος ἔπλασσον, τὸ δὴ ἧττον κοῦφον καὶ ἑτέρας ὑγρασίας οὐσίας δεόμενον εἰς διάνηξιν τὸ τῶν ἰχθύων. ψυχροῦ δὲ τοῦ λοιποῦ, καὶ ἤδη κατωφεροῦς ὑπάρχοντος, τὴν τῶν ἑρπετῶν αἱ ψυχαὶ φύσιν ἐκαινούργουν.", "st": "23.23"}, {"sp": "N", "t": "αὗται δέ, ὦ τέκνον, ὥς τι πράξασαι, ἤδη καὶ περίεργον ὡπλίζοντο τόλμαν, καὶ παρὰ τὰ διατεταγμένα ἐποίουν· καὶ ἤδη τῶν ἰδίων τμημάτων καὶ ταμιείων προήρχοντο· καὶ ἐφ᾽ ἑνὸς οὐκέτι ἤθελον τόπου μένειν, ἀεὶ δὲ ἐκινοῦντο, καὶ τὸ ἔτι ἐπὶ μιᾶς μονῆς εἶναι θάνατον ἡγοῦντο.", "st": "23.24"}, {"sp": "N", "t": "τοῦτο μὲν οὖν, φησίν, ὦ τέκνον, Ἑρμῆς ὡς κἀμοὶ λέγων, καὶ τὸν τῶν ὅλων κύριον καὶ θεὸν οὐκ ἐλάνθανον ὃ πράσσουσαι· κόλασιν δὲ αὐταῖς ἐπεζήτει καὶ δεσμὸν ὃν τλημόνως ὑπομενοῦσι. καὶ δὴ καὶ ἔδοξε τῷ πάντων ἡγεμόνι καὶ δεσπότῃ τὸ τῶν ἀνθρώπων σύστημά τι τεχνήσασθαι, ὅπως ἐν τούτῳ τὸ τῶν ψυχῶν διαπαντὸς γένος κολάζηται.", "st": "23.25"}, {"sp": "N", "t": "Τότε δὴ μεταπεμψάμενος ἐμέ, φησὶν Ἑρμῆς, εἶπεν «Ὦ ψυχῆς ἐμῆς ψυχὴ καὶ νοῦς ἱερὸς ἐμοῦ νοῦ,»", "st": "23.26"}, {"sp": "N", "t": "«ἄχρι ποῦ στυγνὴ φύσις ἡ τῶν ὑποκειμένων ὁρᾶται; ἄχρι πότε τὰ ἤδη γεγονότα ἀργὰ μένει καὶ ἀνεγκωμίαστα; ἀλλ᾽ ἄγε δή μοι τοὺς ἐν οὐρανῷ θεοὺς πάντας ἤδη» εἶπεν ὁ θεός, ὦ τέκνον, ὥς φησιν Ἑρμῆς. οἱ δὲ ἦλθον πρὸς ἐπίταγμα· «Ἀπίδετε» εἶπεν «εἰς τὴν γῆν καὶ πάντα τὰ χαμαί.» οἱ δὲ ἐν τάχει καὶ εἶδον καὶ ἐνόησαν ἃ ἐβούλετο δυνάστης, καὶ εἰπόντι ὑπὲρ τῆς τῶν ἀνθρώπων γενέσεως συνέθεντο.", "st": "23.27"}, {"sp": "N", "t": "εἴ τι παρ᾽ ἕνα ἕκαστον τί δυνατός ἐστι παρασχεῖν τοῖς μέλλουσι γίγνεσθαι, ἔλεγεν Ἥλιος «Ἐπὶ πλέον λάμψω.» ὑπισχνεῖτο Σελήνη τὸν μετὰ τὸν Ἡλίου δρόμον φωτίσαι· ἔλεγε δὲ καὶ προπεπαιδοποιηκέναι φόβον καὶ σιγὴν καὶ ὕπνον καὶ τὴν μέλλουσαν αὐτοῖς ἔσεσθαι ἀνωφελῆ μνήμην. Κρόνος ἀπήγγειλεν ἤδη πατὴρ γεγονέναι καὶ δίκης καὶ ἀνάγκης. Ζεὺς ἔλεγεν «Ὡς μὴ παντάπασι πολέμοις ἀπόληται τὸ φῦλον τὸ ἐσόμενον, ἤδη αὐτοῖς καὶ τύχην καὶ ἐλπίδα καὶ εἰρήνην γεγέννηκα.» Ἄρης ἀγωνίας ἔλεγεν ἤδη καὶ ὀργῆς καὶ ἔριδος πατὴρ εἶναι. Ἀφροδίτη οὐκ ἐμέλλησεν, ἀλλὰ εἶπεν «Ἐγὼ δὲ πόθον αὐτοῖς, ὦ δέσποτα, καὶ ἡδονὴν ἐπιζεύξω καὶ γέλωτα, ὡς μὴ χαλεπωτάτην αἱ συγγενεῖς ψυχαὶ τὴν καταδίκην ὑπομένουσαι ἐπὶ πλέον κολάζωνται.» ἐτέρπετο, ὦ τέκνον, ἐπὶ πλέον Ἀφροδίτης ταῦτα λεγούσης.", "st": "23.28"}, {"sp": "N", "t": "«Ἐγὼ δέ», εἶπεν Ἑρμῆς, «καὶ ποιήσω τὴν ἀνθρώπων φύσιν, ἔφη, καὶ σοφίαν αὐτοῖς καὶ σωφροσύνην καὶ πειθὼ καὶ ἀλήθειαν παραθήσω· καὶ οὐ παύσομαι τῇ εὑρέσει συνών, ἀλλὰ καὶ τῶν ὑπὸ ζῳδίων τῶν ἐμῶν γινομένων ἀνθρώπων εἰσαεὶ τὸν θνητῶν βίον ὠφελήσω, ζῴδια γὰρ τὰ ἐμοὶ ἀνέθηκεν ὁ πατὴρ καὶ δημιουργὸς ἔμφρονά γε καὶ νοερά, καὶ τότε πλέον, ὅταν ἡ ἐπικειμένη αὐτοῖς τῶν ἀστέρων κίνησις σύμφωνον ἔχῃ τὴν ἑνὸς ἑκάστου φυσικὴν ἐνέργειαν.» ἔχαιρεν ὁ θεὸς ὁ δεσπότης κόσμου ταῦτα ἀκούσας, καὶ προσέταξε γίγνεσθαι φῦλον τὸ ἀνθρώπων.", "st": "23.29"}, {"sp": "N", "t": "ἐγὼ δέ, φησὶν Ἑρμῆς, ἐπεζήτουν ὕλην, τίνι δέον ἐστὶ χρήσασθαι. καὶ παρεκάλουν τὸν μόναρχον· ὁ δὲ ταῖς ψυχαῖς προσέταξε τοῦ κράματος τὸ λείψανον δοῦναι. καὶ λαβὼν εὗρον αὐτὸ παντελῶς ξηρόν. ἔνθεν πολλῷ πλείονι τοῦ δέοντος ἐχρησάμην κατάμιξιν ὕδατι, ὡς τὴν τῆς ὕλης σύστασιν νεαροποιήσασθαι, ὡς ἔκλυτον παντάπασιν καὶ ἀσθενὲς καὶ ἀδύνατον τὸ πλασσόμενον εἶναι, ὡς μὴ πρὸς τῷ συνετὸν εἶναι ἔτι καὶ δυνάμεως ᾖ πεπληρωμένον. ἔπλασα· καὶ καλὸν ὑπῆρχε, καὶ ἐτερπόμην βλέπων μου τὸ ἔργον. καὶ κάτωθεν ἐπεκαλεσάμην τὸν μόναρχον θεωρῆσαι· ὁ δὲ καὶ εἶδε καὶ ἐχάρη, καὶ τὰς ψυχὰς ἐκέλευσεν ἐνσωματισθῆναι.", "st": "23.30"}, {"sp": "N", "t": "αἱ δὲ τότε πρῶτον στυγνάσασαι κατακρίτους ἑαυτὰς μαθοῦσαι· ἐθαύμασα οὖν καὶ τοὺς τῶν ψυχῶν λόγους.", "st": "23.31"}, {"sp": "N", "t": "πρόσεχε, τέκνον Ὧρε, κρυπτῆς γὰρ ἐπακούεις θεωρίας, ἧς ὁ μὲν προπάτωρ Καμῆφις ἔτυχεν ἐπακούσας παρὰ Ἑρμοῦ τοῦ πάντων ἔργων ὑπομνηματογράφου, παρὰ τοῦ πάντων προγενεστέρου Καμήφεως, ὁπότε με καὶ τῷ τελείῳ μέλανι ἐτίμησε, νῦν δὲ αὐτὸς σὺ παρ᾽ ἐμοῦ.", "st": "23.32"}, {"sp": "N", "t": "ὅτε γάρ, ὦ θαυμαστὲ παῖ μεγαλόδοξε, ἔμελλον ἐγκατακλείεσθαι τοῖς σώμασιν, αἱ μὲν γὰρ αὐτῶν αὐτὸ μόνον ὠδύροντο καὶ ἐστέναζον, καὶ ὅνπερ τρόπον τῶν γεγονότων θηρίων τὰ ἐλεύθερα δούλοις πονηρῶν μελήσει τῆς συνήθους καὶ φίλης ἀποσπώμενα ἐρημίας μάχεσθαι καὶ στασιάζειν καὶ οὐχ ὁμονοεῖν πρὸς τοὺς κρατήσαντας αὐτῶν καὶ στασιάζειν, ἀλλὰ καί, ἐὰν τύχῃ περιγενόμενα, θανάτῳ παραδώσουσι τοὺς αὐτοῖς ἐπιβάλλοντας. αἱ δὲ παλαιῶν ἔτριζον δίκην ἀσπίδων.", "st": "23.33"}, {"sp": "N", "t": "ὀξὺ δὲ κωκύσασα ἑτέρα, καὶ πρὸ τῶν λόγων ἱκανὰ κλαύσασα, καὶ πολλάκις ἄνω τε καὶ κάτω τοὺς ὡς ἔτυχεν ἔχουσα μεταφέρουσα ὀφθαλμούς, «Οὐρανέ, τῆς ἡμετέρας» εἶπεν «ἀρχὴ γενέσεως, αἰθήρ τε καὶ ἀήρ, καὶ τοῦ μονάρχου θεοῦ χεῖρές τε καὶ ἱερὸν πνεῦμα, περιλαμπῆ τε ὀφθαλμοὶ θεῶν ἄστρα καὶ φῶς ἡλίου καὶ σελήνης ἀκοπίαστον, τὰ τῆς ἡμετέρας ἀρχῆς σύντροφα· ὧν ἁπάντων ἀποσπώμενα ἄθλια πάσχομεν. πλέον οὐδ᾽ ὅτι ἀπὸ μεγάλων τε καὶ λαμπρῶν καὶ τοῦ ἱεροῦ περιχύματος καὶ πλησίου πόλου καὶ ἐπὶ τῆς μακαρίας μετὰ θεῶν πολιτείας εἰς ἄτιμα καὶ ταπεινὰ οὕτως ἐγκατειρχθησόμεθα σκηνώματα.»", "st": "23.34"}, {"sp": "N", "t": "«τί ταῖς δυστήναις ἡμῖν ἀπρεπὲς οὕτως πέπρακται; τί τῶν κολάσεων τούτων ἄξιον; οἷαι τὰς δειλαίας ἡμᾶς ἁμαρτίας περιμένουσιν· οἷα διὰ τὰ πονηρὰ τῶν ἐλπίδων πράξομεν, ἵνα τῷ ὑδαρεῖ καὶ ταχὺ διαλύτῳ σώματι πορίζωμεν τὰ ἐπιτήδεια.»", "st": "23.35"}, {"sp": "N", "t": "«ὀφθαλμοὶ τὰς οὐκέτι τοῦ θεοῦ ψυχὰς χωρήσουσιν ὀλίγον, καὶ παντελῶς μικρὸν τῷ ἐν τούτοις ὑγρῷ καὶ κύκλων τὸν ἑαυτῶν πρόγονον οὐρανὸν ὁρῶσαι στενάξομεν ἀεί. ἔστι δ᾽ ὅτε καὶ οὐ βλέψομεν· ἔνθ᾽ Ὀρφεύς «τῷ λαμπρῷ βλέπομεν, τοῖς δ᾽ ὄμμασιν οὐδὲν ὁρῶμεν·» ἄθλιαι γὰρ κατεκρίθημεν, καὶ τὸ βλέπειν ἡμῖν οὐκ ἄντικρυς ἐχαρίσθη, ὅτι χωρὶς τοῦ φωτὸς ἡμῖν τὸ ὁρᾶν οὐκ ἐδόθη. τόποι τοίνυν καὶ οὐκέτ᾽ εἰσὶν ὀφθαλμοί. ὡς δὲ καὶ τῶν συγγενῶν φυσώντων ἐν ἀέρι πνευμάτων ἀκοῦσαι τλημόνως οἴσομεν ὅτι μὴ συμπνέομεν αὐτοῖς· οἶκος ἡμᾶς ἀντὶ τοῦ μεταρσίου κόσμου τούτου ὁ βραχὺς περιμένει καρδίας ὄγκος.»", "st": "23.36"}, {"sp": "N", "t": "«ἀεὶ δὲ ἀπολύσας ἡμᾶς ἀφ᾽ ὧν εἰς οἷα κατέβημεν ἀπολεῖ τὸ λυπεῖσθαι. δέσποτα καὶ πάτερ καὶ ποιητά, εἰ ταχέως οὕτως σῶν ἔργων ἠμέλησας, διάταξον ἡμῖν τινας ὅρους. ἔτι κἂν βραχέων ἡμᾶς ἀξίωσον λόγων, ἕως ἔτι δι᾽ ὅλου τοῦ περιφανοῦς ἔχομεν βλέπειν κόσμου.»", "st": "23.37"}, {"sp": "N", "t": "ἐπέτυχον, τέκνον Ὧρε, αἱ ψυχαὶ ταῦτα εἰποῦσαι· παρῆν γὰρ καὶ μόναρχος, καὶ τάδε ἐπὶ τοῦ τῆς ἀληθείας καθίσας θρόνου, ταῖς δεηθείσαις ἐφώνησεν·", "st": "23.38"}, {"sp": "N", "t": "Λόγοι τοῦ θεοῦ.", "st": "23.38"}, {"sp": "N", "t": "Ἔρως ὑμῶν, ψυχαί, δεσπόσει καὶ Ἀνάγκη· οἵδε γὰρ μετ᾽ ἐμὲ πάντων δεσπόται καὶ ταξίαρχοι. ψυχαὶ δέ, ὅσαι τὴν ἀγήρατόν μου σκηπτουχίαν θεραπεύετε, ἴστε ὡς ἕως μὲν ἀναμάρτητοι ἦτε, τὰ τοῦ οὐρανοῦ ᾠκεῖτε χωρία· εἰ δ᾽ ἄρα τις ὑμῶν τινος ἐγγίσει μέμψις, θνητοῖς καὶ αὐταὶ προσμεμοιρασμένον χῶρον σπλάγχνοις καταδικασθεῖσαι ἐνοικήσετε.", "st": "23.38"}, {"sp": "N", "t": "κἂν μὲν ᾖ ὑμῶν μέτρια τὰ αἰτιάματα, τὸν ἐπίκηρον τῶν σαρκῶν σύνδεσμον καταλιποῦσαι πάλιν ἀστένακτοι τὸν ἑαυτῶν οὐρανὸν ἀσπάσεσθε· εἰ δ᾽ ἄρα τινῶν μειζόνων ἁμαρτημάτων ἔσεσθε ποιητικαί, οὐ μετὰ τέλους καθήκοντος τῶν πλασμάτων προελθοῦσαι οὐρανὸν μὲν οὐκέτι οἰκήσετε, οὐδ᾽ αὖ σώματα ἀνθρώπων, ζῷα δ᾽ ἄλογα μεταπλανώμεναι λοιπὸν διατελέσετε.", "st": "23.39"}, {"sp": "N", "t": "τάδε εἰπών, ὦ τέκνον Ὧρε, πάσαις αὐταῖς ἐχαρίσατο πνεύματα, καὶ πάλιν ἐφώνησεν· «Ἄλλους δὲ εἰκῆ καὶ ὡς ἔτυχεν ἐνομοθέτησε τὰς διαβολὰς ὑμῶν, ἄλλως ἐπὶ τὸ χεῖρον εἴ τι διαπράξετε ἄσχημον, οὕτως ἐπὶ τὸ βέλτιον εἴ τι βουλεύεσθε τῆς ἑαυτῶν γενέσεως ἄξιον· ἐγὼ γὰρ καὶ οὔτις ἕτερος ἐπόπτης αὐτὸς καὶ ἐπίσκοπος ἔσομαι. ἐπίγνωτε δὲ οὖν ὡς διὰ τὰ πρόσθεν πραχθέντα ὑμῖν κόλασιν ταύτην ὑπομένετε τὴν ἐνσωμάτωσιν.»", "st": "23.40"}, {"sp": "N", "t": "«ἡ τοίνυν διαφορὰ τῆς παλιγγενεσίας ὑμῖν ἔσται ἡ τῶν σωμάτων, ὡς ἔφην, διαφορά, εὐεργεσία δὲ καὶ πρόσθεν εὐδαιμονία ἡ διάλυσις· τυφλωθήσεται δ᾽ ὑμῶν ἡ φρόνησις, ἐάν τι ἀνάξιον ἐμοῦ δόξητε πράσσειν, ὥστε φρονεῖν τὰ ἐναντία, καὶ τὴν μὲν κόλασιν ὡς εὐεργεσίαν ὑπομένειν, τὴν δὲ εἰς τὰ βελτίονα μεταβολὴν ἀτιμίαν τε καὶ ὕβριν. αἱ δικαιότεραι δ᾽ ὑμῶν καὶ τὴν εἰς τὸ θεῖον μεταβολὴν ἐκδεχόμεναι»", "st": "23.41"}, {"sp": "N", "t": "εἰς μὲν ἀνθρώπους, βασιλεῖς δίκαιοι, φιλόσοφοι γνήσιοι, κτίσται καὶ νομοθέται, μάντεις οἱ ἀληθεῖς, ῥιζοτόμοι γνήσιοι, ἄριστοι προφῆται θεῶν, μουσικοὶ ἔμπειροι, ἀστρονόμοι νοεροί, οἰωνοσκόποι σαφεῖς, ἀκριβεῖς θύται, καὶ ὁπόσοι ἔς τι καλῶν κἀγαθῶν ἄξιοι. εἰς δὲ πτηνά, ἀετοί, διότι οὐδὲν τῶν ὁμογενῶν οὔτε ἐκβοήσουσιν οὔτε θοινήσονται, ἀλλ᾽ οὐδὲ πλησίον τούτων ζῷον ἕτερον ἀσθενέστερόν τι αὑτῶν ἀδικεῖν ἀφεθήσεται· ἐνδικωτάτη γὰρ ἡ τῶν ἀετῶν φύσις μετελεύσεται. εἰς δὲ τετράποδα, λέοντες· ἰσχυρὸν γὰρ τὸ ζῷον, καὶ φύσεως ἔτυχεν ἀκοιμήτου τρόπῳ τινί, καὶ φθαρτῷ σώματι τὴν ἀθάνατον γυμναζόμενον φύσιν· οὔτε γὰρ κάμνουσιν οὔτε κοιμῶνται. εἰς δὲ ἑρπετά, δράκοντες, δυνατὸν ὅτι τὸ ζῷον, καὶ μακρόβιον, ἄκακόν τε, καὶ φιλάνθρωπον οὕτως ὥστε ἐνίους καὶ τιθασεύεσθαι, καὶ ἰὸν οὐκ ἔχει, νεάζει δὲ καὶ γηράσαν, καθάπερ φύσις ἡ θεῶν. ἐν δὲ νήχουσι, δελφῖνες· συμπαθήσουσι γὰρ καὶ τοῖς εἰς πέλαγος ἐμπίπτουσιν οὗτοι, καὶ τὸ μὲν ἔμπνουν διακομιοῦσιν εἰς γῆν, τῶν δὲ τελευτησάντων οὐδ᾽ ὅλως ποτὲ ἅπτονται, καίτοι φιλοβρωτάτου πάντων ὄντος τοῦ τῶν ἐνύδρων γένους.", "st": "23.42"}, {"sp": "N", "t": "τοσαῦτα ὁ θεὸς εἰπὼν ἀόρατος νοῦς γίγνεται.", "st": "23.42"}, {"sp": "N", "t": "τούτων οὕτως γενομένων, τέκνον Ὧρε, ἰσχυρότατόν τι ἀπὸ γῆς ἀνίσταται πνεῦμα, ἀκατάληπτον μὲν περιοχῇ σώματος, δυνάμει δὲ φρονήσεως ὑπερέχον, ὃ καίπερ εἰδὸς ὑπὲρ ὧν ἐπυνθάνετο, τὸ σῶμα μὲν κατὰ τύπον ἀνδρὸς περικείμενον, καὶ καλὸν καὶ σεμνοπρεπὲς ὄν, ὑπερβολῇ δὲ ἄγριον καὶ πλῆρες φόβου· ὃ δὴ παραυτίκα τὰς ψυχὰς εἰσιούσας εἰς τὰ πλάσματα θεωρῆσαν, «Τίνες» ἔλεγεν «οὗτοι καλοῦνται, ὦ Ἑρμῆ, θεῶν ὑπομνηματογράφε;»", "st": "23.43"}, {"sp": "N", "t": "εἰπόντος δὲ «Ἄνθρωποι», ἔφης ἔφη «Ὦ Ἑρμῆ, τολμηρὸν ἔργον ποιῆσαι τὸν ἄνθρωπον, περίεργον ὀφθαλμοῖς, καὶ λάλου γλώσσης ἀκουστικὸν μᾶλλον εἶναι καὶ τῶν αὐτῷ μὴ προσηκόντων, λίχνον ὀσφρήσει, καὶ μέχρι πάντων τῷ τῆς ἁφῆς ἁπτικῷ μέλλοντα καταχρᾶσθαι. τοῦτον ἀμέριμνον καταλεῖψαι κέκρικας, ὦ γενεσιουργέ, τὸν ὁρᾶν μέλλοντα τολμηρῶς τῆς φύσεως τὰ καλὰ μυστήρια; ἄλυπον ἐᾶσαι θέλεις τοῦτον, καὶ μέχρι τῶν πέραν γῆς τὰς ἑαυτοῦ μελλήσοντα πέμπειν ἐπινοίας;»", "st": "23.44"}, {"sp": "N", "t": "«ῥίζας φυτῶν ἀνασκάψουσιν ἄνθρωποι, καὶ ποιότητα ἐξετάσουσι χυλῶν, λίθων φύσεις ἐπισκοπήσουσι· καὶ διὰ μέσου ἀνατεμοῦσι τῶν ζῴων τὰ ἄλογα, οὐ μόνον, ἀλλὰ καὶ ἑαυτούς, ὡς ἐγένοντο ἐξετάζειν θέλοντες, τολμηρὰς ἐκτείνουσι χεῖρας καὶ μέχρι θαλάσσης καὶ τὰς αὐτοφυεῖς ὕλας τέμνοντες μέχρι καὶ τῶν πέραν διαπορθμεύουσιν ἀλλήλους ἐπὶ ζήτησιν καὶ τίς ἐνδοτέρω τῶν ἱερῶν ἀδύτων φύσις ὑπάρχει. τὰ μέχρις ἄνω διώξουσι, παρατηρῆσαι βουλόμενοι τίς οὖν καθέστηκε κίνησις. ἔτι μέτρια ταῦτα. λείπει γὰρ οὐδὲν ἔτι πλὴν γῆς τόπος ἔσχατος. ἀλλὰ καὶ τούτων τὴν ἐσχάτην τῷ θέλειν ἐρευνήσουσι νύκτα.»", "st": "23.45"}, {"sp": "N", "t": "«μηδὲν οὖν ἐμπόδιον ἔχωσιν οὗτοι, ἀλλὰ τῷ τῆς ἀληθείας ἀγαθῷ μυηθῶσι καὶ τοῖς χαλεποῖς μὴ βιασθέντες τοῦ φόβου κέντροις ἀμερίμνῳ βίῳ τρυφήσωσιν; εἶτα οὐ καὶ μέχρις οὐρανοῦ περίεργον ὁπλισθήσεται τόλμαν; οὗτοι οὐκ ἀμερίμνους ἐκτενοῦσιν ἐπεὶ καὶ τὰ στοιχεῖα τὰς ψυχὰς αὐτῶν; δίδαξον ἐντεῦθεν ἐρᾶν τοῦ τί βουλεύεσθαι, ἵνα ἔχωσι καὶ τῆς ἀποτυχίας τὸ χαλεπὸν φοβηθῆναι, ἵνα τῷ τῆς λύπης δακνηρῷ δαμασθῶσι, τῶν ἐλπιζομένων ἀποτυχόντες. χρεωκοπείσθω τῶν ψυχῶν αὐτῶν τὸ περίεργον ἐπιθυμίαις καὶ φόβοις καὶ λύπαις καὶ ἐλπίσι πλάνοις. ἐπάλληλοι τὰς ψυχὰς αὐτῶν ἔρωτες νεμέσθωσαν, ἐλπίδες ποικίλαι, ἐπιθυμίαι, ποτὲ μὲν ἐπιτυγχάνουσαι, ποτὲ δὲ ἀτευκτοῦσαι, ἵνα αὐτοῖς καὶ τῆς ἐπιτυχίας ἡδὺ δέλεαρ ᾖ εἰς ἄθλησιν τελειοτέρων κακῶν. βαρείτω πυρετὸς αὐτούς, ἵνα ἐκκακήσαντες κολάσωσι τὴν ἐπιθυμίαν.»", "st": "23.46"}, {"sp": "N", "t": "λυπῇ, τέκνον Ὧρε, τάδε ἑρμηνευούσης σοι τῆς τεκούσης; οὐ θαυμάζεις, οὐ καταπλήσσῃ πῶς ὁ τάλας ἄνθρωπος ἐβαρήθη; ἔτι δεινότερον ἐπάκουσον.", "st": "23.47"}, {"sp": "N", "t": "ἐτέρπετο Μώμου ταῦτα λέγοντος Ἑρμῆς· ἐλέγετο γὰρ οἰκείως αὐτῷ τὰ εἰρημένα. καὶ ταῦτα ἔπραττεν ὅσα περ εἰρήκει λέγων «Μῶμε, ἀλλ᾽ οὐκέτ᾽ ἀργὴ γενήσεται πνεύματος θείου φύσις ἡ τοῦ περιέχοντος. εἶπε γὰρ εἶναί με ταμίαν καὶ προνοητὴν ὁ τῶν συμπάντων δεσπότης. ἐποπτετῆρα τοίνυν τὰ γῆς ἔσται τῶν ὅλων ὀξυδερκὴς θεὸς Ἀδράστεια. καί τι κρυπτὸν ὄργανον ἐγὼ τεχνάσομαι, ἀπλανοῦς καὶ ἀπαραβάτου θεωρίας ἐχόμενον, ᾧ τὰ ἐπὶ γῆς ἀναγκαίως δουλαγωγηθήσεται πάντα τὰ ἀπὸ γενέσεως ἄχρι φθορᾶς ἐσχάτης ἔχον τὴν ἀποτελουμένων πῆξιν· πεισθήσεται δὲ τῷ ὀργάνῳ τούτῳ καὶ τὰ ἐπὶ γῆς ἄλλα πάντα.» εἶπεν Ἑρμῆς ἐγὼ δὲ ταῦτα τῷ Μώμῳ, καὶ ἤδη τὸ ὄργανον ἐκινεῖτο.", "st": "23.48"}, {"sp": "N", "t": "ταῦτα δὲ ὡς ἐγένετο, καὶ ἐνεσωματίσθησαν αἱ ψυχαί, καὶ ἐπαίνου ὑπὲρ τῶν γενομένων αὐτὸς ἔτυχεν,", "st": "23.49"}, {"sp": "N", "t": "πάλιν ὁ μόναρχος σύγκλητον τῶν θεῶν ἐποίησε συνέδριον. καὶ οἱ θεοὶ παρῆσαν, καὶ πάλιν αὐτὸς ταῦτα οὕτως ἐφώνησε, «Θεοί» λέγων, «ὅσοι τῆς κορυφαίας, ὅσοι καὶ ἀφθάρτου φύσεως τετεύχατε, οἳ τὸν μέγαν αἰῶνα διέπειν ἐς ἀεὶ κεκλήρωσθε, οἷς αὐτὰ ἑαυτοῖς ἀντιπαραδιδόντα οὐδέποτε κοπιάσει τὰ σύμπαντα, μέχρι πότε τῆς ἀνεπιγνώστου ταύτης δεσπόσομεν ἡγεμονίας; μέχρι πότε ἀθεώρητα γενήσεται ταῦτα ἡλίῳ καὶ σελήνῃ; ἕκαστος ἡμῶν ἐφ᾽ ἑαυτῷ γεννάτω. ἀπαλείψωμεν τῷ δύνασθαι τὴν ἔτι ἀργὴν σύστασιν ταύτην. ἄπιστος τοῖς μεταγενεστέροις μῦθος δὲ δοξάτω χάος εἶναι. ἔργων ἅπτεσθε μεγάλων, ἐγὼ δ᾽ αὐτὸς ἄρξομαι πρῶτος.» εἶπε, καὶ εὐθέως κοσμικῶς τῆς ἔτι μελαίνης ἑνώσεως διάστασις ἐγένετο· καὶ", "st": "23.50"}, {"sp": "N", "t": "ἐφάνη μὲν οὐρανὸς ἄνω συγκεκοσμημένος τοῖς ἑαυτοῦ μυστηρίοις πᾶσι· κραδαινομένη ἔτι γῆ ἡλίου λάμψαντος ἐπάγη, καὶ ἐφάνη πᾶσι τοῖς περὶ αὐτὴν συγκεκοσμημένοις καλοῖς. καλὰ γὰρ τῷ θεῷ καὶ τὰ θνητοῖς εἶναι νομιζόμενα φαῦλα, ὅτι δὴ τοῖς τοῦ θεοῦ νόμοις δουλεύειν ἐποιήθη. ἔχαιρε δὲ ὁ θεὸς ὁρῶν ἤδη ἑαυτοῦ τὰ ἔργα κινούμενα.", "st": "23.51"}, {"sp": "N", "t": "πληρώσας δὲ τὰς ἰσοστασίας χεῖρας τῷ περιέχοντι τῶν ἐκ τῆς φύσεως ὑπαρχόντων, καὶ τὰς δράκας καρτερῶς σφίγξας, «Λάβε,» εἶπεν, «ὦ ἱερὰ γῆ, λάβε, πάντιμε καὶ εἶναι γεννήτειρα μέλλουσα πάντων, καὶ μηδενὶ ἐντεῦθεν λείπεσθαι δόκει.» εἶπεν ὁ θεός, καὶ τὰς χεῖρας, οἵας δεῖ θεὸν ἔχειν, ἁπλώσας πάντα ἀφῆκεν ἐν τῇ τῶν ὄντων συστάσει.", "st": "23.52"}, {"sp": "N", "t": "καὶ ἄγνωστα μὲν ἦν κατ᾽ ἀρχὰς παντάπασι. νεωστὶ γὰρ αἱ ψυχαὶ καθειρχθεῖσαι καὶ τὴν ἀτιμίαν μὴ φέρουσαι τοῖς ἐν οὐρανῷ θεοῖς ἐφιλονείκουν, τῆς ἑαυτῶν εὐγενείας περικρατοῦσαι καὶ ἀντιλαμβανόμεναι, ὡς καὶ αὐταὶ τοῦ αὐτοῦ ἔτυχον δημιουργοῦ, ἐστασίαζον· καὶ τοῖς λειπομένοις ἀνθρώποις ὀργάνοις χρώμενοι, ἐποίουν αὐτοὺς ἑαυτοῖς ἐπιτίθεσθαι καὶ ἀντιτάσσεσθαι, καὶ πολεμεῖν ἀλλήλοις. καὶ οὕτως ἡ μὲν ἰσχὺς κατὰ τῆς ἀσθενείας μέγα ἠδύνατο, ὥστε οἱ ἰσχυροὶ τοὺς ἀδυνάτους καὶ ἔκαιον καὶ ἐφόνευον, καὶ κατὰ τῶν ἱερῶν τοῦτο μὲν ζῶντας, τοῦτο δὲ καὶ νεκροὺς ἔρριπτον κατὰ τῶν ἀδύτων.", "st": "23.53"}, {"sp": "N", "t": "ἕως ἀγανακτήσαντα τὰ στοιχεῖα τῷ μονάρχῳ θεῷ ἐντυχεῖν ἐδοκίμαζον ὑπὲρ τῆς τῶν ἀνθρώπων ἀγρίου πολιτείας· πολλοῦ δὲ ἤδη γενομένου τοῦ κακοῦ τὰ στοιχεῖα τῷ ποιήσαντι αὐτὰ τῷ θεῷ προσελθόντα τοιούτοις λόγοις ὑπὲρ μέμψεως ἐχρήσαντο.", "st": "23.54"}, {"sp": "N", "t": "καὶ δὴ καὶ εἶχε τὴν τοῦ λέγειν ἐξουσίαν τὸ πῦρ πρῶτον, «Δέσποτα» δὲ ἔλεγε «καὶ τοῦ καινοῦ τούτου κόσμου τεχνῖτα, καὶ κρυπτὸν ἐν θεοῖς καὶ σεβαστὸν ὄνομα μέχρι νῦν ἅπασιν ἀνθρώποις, μέχρι πότε, ὦ δαῖμον, ἄθεον καταλεῖψαι τὸν θνητῶν βίον προαίρεσιν ἔχεις;»", "st": "23.55"}, {"sp": "N", "t": "«ἀνάτειλον ἤδη σεαυτὸν χρηματίζοντι τῷ κόσμῳ, καὶ τοῦ βίου τὸ ἄγριον μύησον εἰρήνῃ. χάρισο νόμους τῷ βίῳ. χάρισαι νυκτὶ χρησμούς. πλήρωσον καλῶν ἐλπίδων πάντα. φοβείσθωσαν ἄνθρωποι τὴν ἀπὸ θεῶν ἐκδικίαν, καὶ οὐδεὶς ἁμαρτήσει. ἐπαξίους ἁμαρτημάτων μισθοὺς ἂν ἀπολάβωσι, φυλάξονται οἱ λοιποὶ τὸ ἀδικεῖν. φοβηθήσονται ὅρκους, καὶ οὐδὲ εἷς ἔτι ἀνόσιον φρονήσει. μαθέτωσαν εὐεργετηθέντες εὐχαριστῆσαι, ἵνα χαῖρον παρὰ λοιβαῖς παρὰ θυσίαις ὑπηρετοῦν ἐγὼ τὸ πῦρ ἵν᾽ εὐώδεις ἀτμοὺς ἀπ᾽ ἐσχάρας προπέμψω σοι. μαίνομαι γάρ, ὦ δέσποτα, μέχρι νῦν, καὶ ὑπὸ τῆς τῶν γενομένων ἀνθρώπων ἀθέου τόλμης σάρκας ἀναγκάζομαι τήκειν. οὐκ ἐῶσί τε μένειν εἰς ὃ πέφυκα, παραχαράσσοντες οὐ καθηκόντως τὸ ἄφθαρτον.»", "st": "23.56"}, {"sp": "N", "t": "ὁ δὲ ἀήρ «Καὶ αὐτὸς θολοῦμαι, δέσποτα,» ἔλεγε, «καὶ ἀπὸ τῶν νεκρῶν σωμάτων ἀναθυμιάσεως, νοσώδης τέ εἰμι, καὶ ὑγιεινὸς οὐκέτι· ἐφορῶ τε ἄνωθεν οἷα μὴ θέμις ὁρᾶν.»", "st": "23.57"}, {"sp": "N", "t": "ὕδωρ ἑξῆς, ὦ παῖ μεγαλόψυχε, τὴν τοῦ λέγειν εἶχεν ἐξουσίαν, καὶ ἔλεγεν οὕτως· «Πάτερ καὶ θαυμαστὲ ποιητὰ πάντων, αὐτογόνε δαῖμον καὶ τῆς διὰ σὲ πάντα γεννώσης ποιητὰ φύσεως, ἤδη ποτέ, ὦ δαῖμον, ἀεὶ ῥεῖθρα ποταμῶν καθαρὰ πρόσταξον εἶναι· ἢ γὰρ ἀπολούουσι ποταμοὶ καὶ θάλασσαι τοὺς φονεύσαντας ἢ δέχονται τοὺς φονευθέντας.»", "st": "23.58"}, {"sp": "N", "t": "γῆ παρῆν περίλυπος ἑξῆς, καὶ τάξομαι τῆς ἀπὸ τῶν λόγων, ὦ παῖ μεγαλόδοξε, οὕτως λέγειν ἤρξατο· «Βασιλεῦ καὶ τῶν οὐρανίων πρύτανι καὶ δέσποτα ἁψίδων, στοιχείων ἡμῶν ἡγεμὼν πάτερ τῶν σοι παρεστώτων, ἐξ ὧν αὐξήσεως καὶ μειώσεως ἀρχὴν ἔχει τὰ πάντα, εἰς ἃ καὶ πάλιν καταλήγοντα ἀναγκαίως ὀφειλόμενον τέλος ἔχει· ἀλόγιστος, ὦ πολυτίμητε, καὶ ἄθεος ἀπ᾽ ἀνθρώπων ἐπ᾽ ἐμὲ χορὸς ἔπεστι. χωρῶ δ᾽ ἐγὼ καὶ φύσιν πάντων· αὐτὴ γάρ, ὡς σὺ προσέταξας, καὶ φέρω πάντα καὶ τὰ φονευθέντα δέχομαι. ἀτιμοῦμαι δὲ ἤδη·»", "st": "23.59"}, {"sp": "N", "t": "«ὁ ἐπὶ πάντων ὁ ἐπιχθόνιός σου κόσμος πεπληρωμένος θεὸν οὐκ ἔχει. πάντα γάρ, ὃ φοβηθῶσιν οὐκ ἔχοντες, παρανομοῦσι· καὶ κατ᾽ ἐμῶν, ὦ κύριε, τενόντων πάσῃ πονηρᾷ τέχνῃ καταπίπτουσι, καταβρέχομαι δὲ πᾶσα διαφθειρομένων σωμάτων χυλοῖς.»", "st": "23.60"}, {"sp": "N", "t": "«ἐντεῦθεν, κύριε, καὶ τοὺς οὐκ ἀξίους ἀναγκάζομαι χωρεῖν, χωρῆσαι θέλω μεθ᾽ ὧν φέρω πάντων καὶ θεόν. χάρισαι τῇ γῇ, κἂν οὐ σεαυτόν, οὐ γὰρ σὲ χωρεῖν ὑπομένω, σαυτοῦ τινα ἱερὰν ἀπόρροιαν. στοιχείων τιμιωτέραν τῶν ἄλλων τὴν γῆν μετεποίησαν. μόνῃ γὰρ αὐχεῖν τῶν ἀπὸ σοῦ πρέπει τὰ πάντα παρεχούσῃ.»", "st": "23.61"}, {"sp": "N", "t": "τοσαῦτα μὲν τὰ στοιχεῖα εἶπεν· ὁ δὲ θεός, ἱερᾶς ἐν τῷ λέγειν φωνῆς τὰ σύμπαντα πληρώσας, «Πορεύεσθε,» εἶπεν, «ἱερὰ καὶ μεγάλου πατρὸς ἄξια τέκνα, καὶ κατὰ μηδένα τρόπον νεωτερίζειν ἐπιχειρεῖτε, μηδὲ ἀργὸν τῆς ἐξ ὑμῶν ὑπηρεσίας τὸν σύμπαντά μου κόσμον καταλείπετε. ἑτέρα γὰρ ἐν ὑμῖν τις ἤδη τῆς ἐμῆς ἀπόρροια φύσεως, ὃς δὴ καὶ ὅσιος ἔσται τῶν πραττομένων ἐπόπτης, καὶ ζώντων μὲν κριτὴς ἀμεθόδευτος, φρικτὸς δ᾽ οὐ μόνον ἀλλὰ καὶ τιμωρὸς τῶν ὑπὸ γῆν τύραννος· καὶ ἑκάστῳ δὲ τῶν ἀνθρώπων ἀκολουθήσει διὰ γένους μισθὸς ἐπάξιος.»", "st": "23.62"}, {"sp": "N", "t": "καὶ οὕτως ἐπαύσατο τῆς ἐντυχίας τὰ στοιχεῖα τοῦ δεσπότου κελεύσαντος καὶ ἐχεμυθίαν εἶχεν· καὶ ἕκαστον αὐτῶν τῆς ἰδίας ἐξουσίας ἐκράτει καὶ ἐδέσποζε.", "st": "23.63"}, {"sp": "N", "t": "— καὶ ἐκ τούτου εἶπεν Ὧρος· Ὦ τεκοῦσα, πῶς οὖν τὴν τοῦ θεοῦ ἀπόρροιαν ἔχειν εὐτύχησεν ἡ γῆ; — καὶ εἶπεν Ἶσις· Παραιτοῦμαι γένεσιν ἱστορεῖν· οὐ γὰρ θεμιτὸν σῆς σπορᾶς καταλέγειν ἀρχήν, ὦ μεγαλοσθενὲς Ὧρε, ὡς μήποτε ὕστερον εἰς ἀνθρώπους ἀθανάτων ἔλθῃ γένεσις θεῶν· πλὴν ὅτι γε ὁ μόναρχος θεός, ὁ τῶν συμπάντων κοσμοποιητὴς καὶ τεχνίτης, τῇ ⟨γῇ⟩ τὸν μέγιστόν σου πρὸς ὀλίγον ἐχαρίσατο πατέρα Ὄσιριν καὶ τὴν μεγίστην θεὰν Ἶσιν, ἵνα τῶν πάντων δεομένῳ κόσμῳ βοηθοὶ γένωνται.", "st": "23.64"}, {"sp": "N", "t": "οὗτοι βίου τὸν βίον ἐπλήρωσαν. οὗτοι τὸ τῆς ἀλληλοφονίας ἔπαυσαν ἄγριον. τεμένη προγόνοις θεοῖς αὐτοὶ καὶ θυσίας καθιέρωσαν· νόμους οὗτοι καὶ τροφὰς θνητοῖς καὶ σκέπην ἐχαρίσαντο.", "st": "23.65"}, {"sp": "N", "t": "«οὗτοι τὰ κρυπτά», φησὶν Ἑρμῆς, «τῶν ἐμῶν ἐπιγνώσονται γραμμάτων πάντα καὶ διακρινοῦσι, καὶ τινὰ μὲν αὐτοὶ κατασχῶσιν, ἃ δὲ καὶ πρὸς εὐεργεσίας θνητῶν φθάνει, στήλαις καὶ ὀβελίσκοις χαράξουσιν.»", "st": "23.66"}, {"sp": "N", "t": "οὗτοι πρῶτοι δείξαντες δικαστήρια εὐνομίας τὰ σύμπαντα καὶ δικαιοσύνης ἐπλήρωσαν.", "st": "23.67"}, {"sp": "N", "t": "οὗτοι δεξιᾶς καὶ πίστεως ἀρχηγέται γενόμενοι καὶ τὸν μέγιστον θεὸν Ὅρκον εἰσηγάγοντο εἰς τὸν βίον. οὗτοι τοὺς παυσαμένους τοῦ ζῆν ὡς δέον ἐστὶν ἐδίδαξαν περιστέλλειν·", "st": "23.67"}, {"sp": "N", "t": "οὗτοι τὸ τοῦ θανάτου ζητήσαντες αἴτιον ἔγνωσαν ὡς τοῦ ἔξωθεν πνεύματος φιλυποστρόφου τυγχάνοντος εἰς τὰ τῶν ἀνθρώπων πλάσματα, ἐὰν ὑστερήσῃ ποτέ, ἀνάκτησιν οὐκ ἔχουσαν ἐργάζεται λειποθυμίας.", "st": "23.67"}, {"sp": "N", "t": "οὗτοι τὸ περιέχον ὅτι δαιμόνων ἐπληρώθη παρὰ Ἑρμοῦ μαθόντες κρυπταῖς στήλαις ἐχάραξαν.", "st": "23.67"}, {"sp": "N", "t": "οὗτοι μόνοι, τὰς κρυπτὰς νομοθεσίας τοῦ θεοῦ παρὰ Ἑρμοῦ μαθόντες, τεχνῶν καὶ ἐπιστημῶν καὶ ἐπιτηδευμάτων ἁπάντων εἰσηγηταὶ τοῖς ἀνθρώποις ἐγένοντο καὶ νομοθέται.", "st": "23.68"}, {"sp": "N", "t": "οὗτοι, παρ᾽ Ἑρμοῦ μαθόντες ὡς τὰ κάτω συμπαθεῖν τοῖς ἄνω ὑπὸ τοῦ δημιουργοῦ διετάγη, τὰς προσκαθέτους τοῖς ἐν οὐρανῷ μυστηρίοις ἱεροποιίας ἀνέστησαν ἐν γῇ.", "st": "23.68"}, {"sp": "N", "t": "οὗτοι τὸ φθόριμον τῶν σωμάτων ἐπιγνόντες τὸ ἐν ἅπασι τέλειον τῶν προφητῶν ἐτεχνάσαντο, ὡς μήποτε ὁ μέλλων θεοῖς προσάγειν χεῖρας προφήτης ἀγνοῇ τι τῶν ὄντων, ἵνα φιλοσοφίᾳ μὲν καὶ μαγείᾳ ψυχὴν τρέφῃ, σώζῃ δ᾽ ὅταν τι πάσχῃ ἰατρικῇ σῶμα.", "st": "23.68"}, {"sp": "N", "t": "ταῦτα πάντα ποιήσαντες, ὦ τέκνον, Ὄσιρίς τε κἀγώ, τὸν κόσμον πληρέστατον ἰδόντες ἀπῃτούμεθα λοιπὸν ὑπὸ τῶν τὸν οὐρανὸν κατοικούντων. ἀλλ᾽ οὐκ ἦν ἀνελθεῖν πρὶν ἐπικαλέσασθαι τὸν μόναρχον, ἵνα δὴ καὶ τῆς θεωρίας ταύτης πλῆρες τὸ περιέχον γένηται, αὐτοί τε εὐπαράδεκτοι εὐτυχήσωμεν τὴν ἀνάβασιν. χαίρει γὰρ ὕμνοις ὁ θεός.", "st": "23.69"}, {"sp": "N", "t": "— Ὦ τεκοῦσα, εἶπεν Ὧρος, κἀμοὶ χάρισαι τὴν τοῦ ὕμνου ἐπίγνωσιν ὡς μὴ ἀμαθὴς ὑπάρχω. — Καὶ εἶπεν Ἶσις, Πρόσεχε, παῖ.", "st": "23.70"}, {"sp": "SEC", "t": "XXIV", "st": "24.1"}, {"sp": "N", "t": "Σὺ δέ, ὦ παῖ μεγαλόψυχε, εἴ τι θέλεις ἕτερον ἐπερώτα. — καὶ εἶπεν Ὧρος· Ὦ πολυτίμητε μῆτερ, εἰδῆσαι θέλω πῶς γίγνονται βασιλικαὶ ψυχαί. — καὶ εἶπεν Ἶσις· Ἡ γιγνομένη, τέκνον Ὧρε, περὶ τὰς βασιλικὰς ψυχὰς διαφορὰ τοιαύτη τίς ἐστιν. ἐπεὶ γὰρ τόποι τέσσαρές εἰσιν ἐν τῷ παντί, οἵτινες ἀπαραβάτῳ νόμῳ καὶ προστασίᾳ ὑποπίπτουσιν, ὅ τε οὐρανὸς καὶ αἰθὴρ καὶ ὁ ἀὴρ καὶ ἡ ἱερωτάτη γῆ. καὶ ἄνω μέν, ὦ τέκνον, ἐν οὐρανῷ θεοὶ κατοικοῦσιν, ὧν ἄρχει μετὰ καὶ τῶν ἄλλων πάντων ὁ τῶν ὅλων δημιουργός· ἐν δὲ τῷ αἰθέρι ἀστέρες, ὧν ἄρχει ὁ μέγας φωστὴρ ἥλιος· ἐν δὲ τῷ ἀέρι ψυχαὶ δὲ μόναι, ὧν ἄρχει σελήνη· ἐπὶ δὲ τῆς γῆς ἄνθρωποι καὶ τὰ λοιπὰ ζῷα, ὧν ἄρχει ὁ κατὰ καιρὸν βασιλεύς· γεννῶσι γάρ, ὦ τέκνον, βασιλεῖς οἱ θεοὶ ἐπαξίους τῆς ἐπιγείου ἡγεμονίας.", "st": "24.1"}, {"sp": "N", "t": "καί εἰσιν οἱ ἄρχοντες τοῦ βασιλέως ἀπόρροιαι· ὧν ὁ μᾶλλον ἐκείνῳ πλησίον, οὗτος καὶ τῶν ἄλλων βασιλικώτερος. ὁ μὲν γὰρ ἥλιος, καθὸ ἔγγιόν ἐστι τοῦ θεοῦ, τῆς σελήνης ἐστὶ μείζων καὶ δυναμικώτερος· ᾧ δευτερεύει ἡ σελήνη καὶ κατὰ τάξιν καὶ κατὰ δύναμιν.", "st": "24.2"}, {"sp": "N", "t": "καὶ ὁ μὲν βασιλεὺς τῶν μὲν ἄλλων θεῶν ἐστὶν ἔσχατος, πρῶτος δὲ ἀνθρώπων. καὶ μέχρις ὅτου ἐπὶ γῆς ἐστι, τῆς μὲν ἀληθοῦς θειότητος ἀπήλλακται, ἔχει δὲ ἐξαίρετόν τι παρ᾽ ἀνθρώπους, ὃ ὅμοιόν ἐστι τῷ θεῷ· ἡ γὰρ εἰς αὐτὸν καταπεμπομένη ψυχὴ ἐξ ἐκείνου ἐστὶ τοῦ χωρίου ὃ ὑπεράνω κεῖται ἐκείνων ἀφ᾽ ὧν εἰς τοὺς ἄλλους καταπέμπονται ἀνθρώπους.", "st": "24.3"}, {"sp": "N", "t": "καταπέμπονται δὲ ἐκεῖθεν εἰς τὸ βασιλεύειν διὰ δύο ταῦτα αἱ ψυχαί, ὦ τέκνον· αἱ γὰρ καλῶς καὶ ἀμέμπτως δραμοῦσαι τὸν ἴδιον αἰῶνα, καὶ μέλλουσαι ἀποθεοῦσθαι, ἵνα κἀν τῷ βασιλεύειν τὴν τῶν θεῶν προγυμνασθῶσιν ἐξουσίαν· αἱ θεῖαί τινες ἤδη οὖσαι, καὶ ἐν μικρῷ τινι παραθεμιστεύσασαι τὸν ἔνθεον γνώμονα, ἵνα μὴ κόλασιν μὲν ἐν τῷ σεσωματίσθαι ὑπομένωσι δι᾽ ἀδοξίαν καὶ φύσιν, μηθὲν ὅμοιον ταῖς ἄλλαις πάσχωσιν ἐνσωματισθεῖσαι, ἀλλ᾽ ὅπερ εἶχον λελυμέναι, τοῦτο καὶ δεθεῖσαι ἔχωσιν.", "st": "24.4"}, {"sp": "N", "t": "αἱ μέντοι περὶ τὰ ἤθη τῶν βασιλευόντων γιγνόμεναι διαφοραὶ οὐκ ἐν τῇ τῆς ψυχῆς φύσει κρίνονται, πᾶσαι γὰρ θεῖαι, ἀλλ᾽ ἐν τῇ τῶν δορυφορησάντων αὐτῆς τὴν κατάβασιν ἀγγέλων καὶ δαιμόνων. αἱ γὰρ τοιαῦται καὶ ἐπὶ τοιαῦτα κατερχόμεναι δίχα προπομπῆς καὶ δορυφορίας οὐ κατέρχονται· οἶδε γὰρ ἡ ἄνω δίκη τὴν ἀξίαν ἑκάστῳ νέμειν, κἂν ἐκ τῆς εὐημερούσης χώρας ἀπωθῶνται.", "st": "24.5"}, {"sp": "N", "t": "ὅταν οὖν οἱ κατάγοντες αὐτὴν ἄγγελοι καὶ δαίμονες, τέκνον Ὧρε, πολεμικοὶ ὦσι, τούτων περικρατεῖν τῆς γνώμης ἡ ψυχὴ ἔχει ἢ ἐπιλαθομένη τῶν ἑαυτῆς ἔργων, μόνων δὲ μεμνημένη τούτων μέχρι τῶν τῆς ἱερᾶς συνοδίας προσγεγονότων· ὅταν δὲ εἰρηνικοί, τότε καὶ αὐτὴ τὸν ἴδιον δρόμον εἰρηνοποιεῖται· ὅταν δὲ δικαστικοί, τότε καὶ αὐτὴ δικάζει· ὅταν δὲ μουσικοί, τότε καὶ αὐτὴ ᾄδει· ὅταν δὲ φιλαλήθεις, τότε καὶ αὐτὴ φιλοσοφεῖ. ὡς γὰρ ἐξ ἀνάγκης αἱ ψυχαὶ αὗται τῆς τῶν καταγόντων περικρατοῦσι γνώμης· πίπτουσι γὰρ εἰς τὴν ἀνθρωπότητα τῆς μὲν ἰδίας φύσεως ἐπιλαθόμεναι καὶ παρόσον μακρὰν αὐτῆς ἀπέστησαν, μεμνημέναι δὲ τῆς τῶν κατακλεισάντων αὐτὰς διαθέσεως.", "st": "24.6"}, {"sp": "N", "t": "— Καλῶς, εἶπεν Ὧρος, ἅπαντά μοι, ὦ τεκοῦσα· πῶς δὲ εὐγενεῖς γίγνονται ψυχαί, οὐδέπω μοι διηγήσω.", "st": "24.7"}, {"sp": "N", "t": "Πῶς γίγνονται εὐγενεῖς ψυχαί.", "st": "24.7"}, {"sp": "N", "t": "— Ὃν τρόπον ἐπὶ γῆς, ὦ τέκνον Ὧρε, εἰσί τινες πολιτεῖαι διαφέρουσαι ἀλλήλων, οὕτως καὶ ἐπὶ τῶν ψυχῶν ἐστι. καὶ αὗται γὰρ τόπους ἔχουσιν ὅθεν ὡρμῶσι, καὶ ἡ ἀπὸ τοῦ ἐνδοξοτέρου τόπου ὡρμηκυῖα εὐγενεστέρα ἐστὶ τῆς μὴ οὕτως ἐχούσης. ὅνπερ γὰρ τρόπον ἐν ἀνθρώποις ὁ ἐλεύθερος εὐγενέστερος εἶναι δοκεῖ δούλου, τὸ γὰρ ἐν ταῖς ψυχαῖς ὑπερέχον καὶ βασιλικὸν δουλοποιεῖ τὸ ὑπερεχόμενον ἐξ ἀνάγκης, οὕτω δή, ὦ τέκνον, καί * * *", "st": "24.7"}, {"sp": "N", "t": "— ἀρρενικαὶ καὶ θηλυκαὶ γίγνονται ψυχαί;", "st": "24.8"}, {"sp": "N", "t": "Πῶς ἀρρενικαὶ καὶ θηλυκαὶ γίγνονται ψυχαί.", "st": "24.8"}, {"sp": "N", "t": "— Αἱ ψυχαί, ὦ τέκνον Ὧρε, ὁμοφυεῖς εἰσιν ἑαυταῖς, καθάπερ ἐξ ἑνὸς οὖσαι χωρίου, ἐν ᾧ αὐτὰς διετύπωσεν ὁ δημιουργός, καὶ οὔτε εἰσὶν ἄρρενες οὔτε θήλειαι. ἡ γὰρ τοιαύτη διάθεσις ἐπὶ σωμάτων γίγνεται, καὶ οὐκ ἐπὶ ἀσωμάτων.", "st": "24.8"}, {"sp": "N", "t": "ἡ δὲ διαφορὰ τοῦ τὰς μὲν βριμωδεστέρας εἶναι, τὰς δὲ εὐαφεῖς, ὁ ἀήρ ἐστι, τέκνον Ὧρε, ἐν ᾧ πάντα γίγνεται· ἀὴρ δὲ ψυχῆς ἐστιν αὐτὸ τὸ σῶμα ὃ περιβέβληται, ὅπερ στοιχείων ἐστὶ φύραμα, γῆς καὶ ὕδατος καὶ ἀέρος καὶ πυρός. ἐπεὶ οὖν τὸ μὲν τῶν θηλειῶν σύγκριμα πλεονάζει μὲν τῷ ὑγρῷ καὶ ψυχρῷ, λείπεται δὲ τῷ ξηρῷ καὶ θερμῷ, παρὰ τοῦτο ἡ εἰς τοιοῦτον πλάσμα συγκλειομένη ψυχὴ δίυγρος γίγνεται καὶ τρυφερά, ὥσπερ ἐπὶ τῶν ἀρρένων τὸ ἐναντίον ἐστιν εὑρεῖν· ἐν γὰρ τούτοις πλεονάζει μὲν τὸ ξηρὸν καὶ τὸ θερμόν, λείπεται δὲ τὸ ψυχρὸν καὶ ὑγρόν, διὰ τοῦτο αἱ ἐν τοιούτοις σώμασι ψυχαὶ τραχεῖαι καὶ ἐργατικώτεραί εἰσι.", "st": "24.9"}, {"sp": "N", "t": "— Πῶς γίγνονται αἱ ψυχαὶ συνεταί, ὦ τεκοῦσα; — καὶ ἀπεκρίθη Ἶσις·", "st": "24.10"}, {"sp": "N", "t": "Πῶς γίγνονται αἱ ψυχαί", "st": "24.10"}, {"sp": "N", "t": "Τὸ ὁρατικόν, ὦ τέκνον, περιβέβληται χιτῶσιν. ὅταν οὗτοι οἱ χιτῶνες πυκνοὶ ὦσι καὶ παχεῖς, ἀμβλυωπεῖ ὁ ὀφθαλμός· ἐὰν δὲ ἀραιοὶ καὶ λεπτοί, τότε ὀξυωπέστατα βλέπει. οὕτως καὶ ἐπὶ τῆς ψυχῆς· ἔχει γὰρ καὶ αὕτη ἴδια περιβόλαια, ἀσώματα, καθὸ καὶ αὐτὴ ἀσώματός ἐστι. τὰ δὲ περιβόλαια ταῦτα ἀέρος εἰσὶ τοῦ ἐν ἡμῖν. ὅταν οὗτοι ὦσι λεπτοὶ καὶ ἀραιοὶ καὶ διαυγεῖς, τότε συνετὴ ἡ ψυχή ἐστιν· ὅταν δὲ τοὐναντίον πυκνοὶ καὶ παχεῖς καὶ τεθολωμένοι, τότε ὡς ἐν χειμῶνι, ἐπὶ μακρὸν οὐ βλέπει, ἀλλὰ ταῦτα ὅσα παρὰ ποσὶ κεῖται.", "st": "24.10"}, {"sp": "N", "t": "— καὶ εἶπεν Ὧρος· Διὰ τίνα οὖν αἰτίαν, ὦ τεκοῦσα, οἱ ἔξω τῆς ἱερωτάτης ἡμῶν χώρας ἄνθρωποι ταῖς διανοίαις οὐχ οὕτως εἰσὶ συνετοὶ ὡς οἱ ἡμέτεροι; — καὶ εἶπεν Ἶσις· Ἡ γῆ μέσον τοῦ παντὸς ὑπτία κεῖται, ὥσπερ ἄνθρωπος, οὐρανὸν βλέπουσα. μεμέρισται δὲ καθ᾽ ὅσα μέρη ὁ ἄνθρωπος μερίζεται· βλέπει δ᾽ ἐν οὐρανῷ καθάπερ πατρὶ ἰδίῳ, ὅπως ταῖς ἐκείνου μεταβολαῖς καὶ αὐτὴ τὰ ἴδια συμμεταβάλλῃ· καὶ πρὸς μὲν τῷ νότῳ τοῦ παντὸς κειμένην ἔχει τὴν κεφαλήν, πρὸς δὲ τῷ ἀπηλιώτῃ δεξιὸν ὦμον, ὑπὸ τὴν ἄρκτον τοὺς πόδας, τὸν δὲ εὐώνυμον ὑπὸ τὴν κεφαλὴν τῆς ἄρκτου, τοὺς δὲ μηροὺς ἐν τοῖς μετὰ τὴν ἄρκτον, τὰ δὲ μέσα ἐν τοῖς μέσοις.", "st": "24.11"}, {"sp": "N", "t": "καὶ τούτου σημεῖόν ἐστι τὸ τοὺς μὲν νοτιαίους τῶν ἀνθρώπων καὶ ἐπὶ τῇ κορυφῇ οἰκοῦντας εὐκορύφους καὶ καλλίτριχας, τοὺς δὲ ἀπηλιωτικοὺς πρὸς μάχην προχείρους εἶναι καὶ τοξικούς, αἰτία γὰρ τούτοις ἡ δεξιὰ χείρ ἐστι, τοὺς δ᾽ ἐν τῷ λιβὶ ἀσφαλεῖς εἶναι καὶ ὡς ἐπὶ τὸ πλεῖστον ἀριστερομάχους, καὶ ὅσοις ἄλλοι τῷ δεξιῷ μέρει ἐνεργοῦσιν, αὐτοὺς τῷ εὐωνύμῳ προστιθεμένους, τοὺς δὲ ὑπὸ τὴν ἄρκτον πρός τινα τοὺς πόδας, καὶ ἄλλως εὐκνήμους. τοὺς δὲ μετὰ τούτους καὶ μικρῷ πόρρω, τὸ νῦν Ἰταλικὸν κλίμα καὶ τὸ Ἑλλαδικόν, πάντες δὲ οὗτοι καλλίμηροί εἰσι καὶ εὐπωγωνότεροι, ὥστε τῇ τοῦ κάλλους τῶν μερῶν τούτων ὑπερβολῇ καὶ τοὺς ἐνταῦθα ἀνθρώπους καταβαίνειν πρὸς τὴν τῶν ἀρρένων ὁμιλίαν.", "st": "24.12"}, {"sp": "N", "t": "πάντα δὲ ταῦτα τὰ μέρη, πρὸς τὰ ἄλλα ἀργὰ ὄντα, ἀργοτέρους ἤνεγκε καὶ τοὺς ἀπ᾽ αὐτῶν ἀνθρώπους. ἐπειδὴ δὲ ἐν τῷ μέσῳ τῆς γῆς κεῖται ἡ τῶν προγόνων ἡμῶν ἱερωτάτη χώρα, τὸ δὲ μέσον τοῦ ἀνθρωπίνου σώματος μόνης τῆς καρδίας ἐστὶ σηκός, τῆς δὲ ψυχῆς ὁρμητήριόν ἐστι καρδία, παρὰ ταύτην τὴν αἰτίαν, ὦ τέκνον, ἐνταῦθα ἄνθρωποι τὰ μὲν ἄλλα ἔχουσιν οὐχ ἧττον ὅσα καὶ πάντες, ἐξαίρετον δὲ τῶν πάντων νοερώτεροί εἰσι καὶ σώφρονες, ὡς ἂν ἐπὶ καρδίας γενόμενοι καὶ τραφέντες.", "st": "24.13"}, {"sp": "N", "t": "ἄλλως τε, ὁ μὲν νότος, ὦ παῖ, δεκτικὸς ὢν τῶν ἐκ τοῦ περιέχοντος συνισταμένων νεφῶν (αὐτίκα γοῦν καὶ διὰ τὴν οὕτως αὐτῶν γενομένων ἐκεῖ κατακομιδὴν ἐκεῖθεν ῥεῖν λέγουσιν καὶ τὸν ἡμέτερον ποταμόν, λυομένης ἐκεῖ τῆς πάχνης), ὅπου δ᾽ ἂν ἐμπέσῃ νεφέλη, τὸν ὑποκείμενον ἤχλυσεν ἀέρα, καὶ τρόπον τινὰ καπνοῦ κατέπλησε· καπνὸς δὲ ἢ ἀχλὺς οὐ μόνον ὀμμάτων ἐστὶν ἐμπόδιον, ἀλλὰ καὶ νοῦ. ὁ δὲ ἀπηλιώτης, ὦ μεγαλόδοξε Ὧρε, τῇ σύνεγγυς τοῦ ἡλίου ἀνατολῇ θορυβούμενος καὶ ἐκθερμαινόμενος, ὁμοίως δὲ καὶ ὁ ἀντικείμενος τούτῳ λὶψ μετέχων τῶν αὐτῶν κατὰ δυσμάς, οὐδεμίαν εἰλικρινῆ ἐπίστασιν ποιοῦσι τῶν παρ᾽ αὐτοῖς γεννωμένων ἀνθρώπων· ὁ δὲ βορέας τῇ συμφύτῳ ψυχρίᾳ ἀποπήσσει μετὰ τῶν σωμάτων καὶ τὸν νοῦν τῶν ὑπ᾽ αὐτὸν ἀνθρώπων.", "st": "24.14"}, {"sp": "N", "t": "τὸ δὲ μέσον τούτων, εἰλικρινὲς ὂν καὶ ἀτάραχον, καὶ ἑαυτὸ προέχει, καὶ τοῖς ἐν αὐτῷ πᾶσι· τῇ γὰρ συνεχεῖ ἀμεριμνίᾳ γεννᾷ καὶ κοσμεῖ καὶ παιδεύει· καὶ μόνον τοῖς τοσούτοις ἐρίζει καὶ νικᾷ, καὶ ἐπιστάμενον τὴν ἰδίαν νίκην, ὥσπερ σατράπης ἀγαθὸς τοῖς νενικημένοις καὶ ἐπιδίδωσι.", "st": "24.15"}, {"sp": "N", "t": "— Καὶ τοῦτό μοι, κυρία μῆτερ, ἔκθου· παρὰ ποίαν αἰτίαν ἔτι ζώντων ἀνθρώπων ἐν ταῖς μακραῖς νόσοις καὶ ὁ λόγος καὶ αὐτὸς ὁ λογισμὸς καὶ αὐτὴ ἡ ψυχὴ ἔσθ᾽ ὅτε βλάπτεται.", "st": "24.16"}, {"sp": "N", "t": "— καὶ ἀπεκρίθη Ἶσις· Τῶν ζώντων, ὦ τέκνον, τὰ μὲν ᾠκείωται πρὸς τὸ πῦρ, τὰ δὲ πρὸς τὸ ὕδωρ, τὰ δὲ πρὸς ἀέρα, τὰ δὲ πρὸς γῆν, τὰ δὲ πρὸς τούτων δύο ἢ τρία, τὰ δὲ καὶ πρὸς τὰ ὅλα· πάλιν αὖ τὰ μὲν ἀπηλλοτρίωται τοῦ πυρός, τὰ δὲ τοῦ ὕδατος, τὰ δὲ τῆς γῆς, τὰ δὲ τοῦ ἀέρος, τὰ δὲ δύο τούτων, τὰ δὲ τριῶν, τὰ δὲ τῶν ὅλων.", "st": "24.17"}, {"sp": "N", "t": "οἷον ἀκρὶς μέν, ὦ τέκνον, καὶ πᾶσα μυῖα φεύγει τὸ πῦρ, ἀετὸς καὶ κίρκος καὶ ὅσα ὑψιπετέστερά ἐστι τῶν ὀρνέων φεύγει τὸ ὕδωρ, ἰχθύες ἀέρα καὶ γῆν, ὄφις τὸν ἀέρα τὸν εἰλικρινῆ ἀποστρέφεται· φιλοῦσι δὲ τὴν μὲν γῆν οἱ ὄφεις καὶ ὅσα ἕρπει, τὸ δὲ ὕδωρ τὰ κινητὰ πάντα, τὸν δὲ ἀέρα τὰ πτηνά, ἐν ᾧ καὶ πολιτεύεται, τὸ δὲ πῦρ ὅσα ὑπερπετῆ ἐστι καὶ ἐγγὺς τὴν δίαιταν. οὐ μὴν ἀλλὰ καί τινα τῶν ζῴων φιλεῖ τὸ πῦρ, οἷον αἱ σαλαμάνδραι· ἐν γὰρ τῷ πυρὶ καὶ φωλεύουσιν.", "st": "24.18"}, {"sp": "N", "t": "ἕκαστον γὰρ τῶν στοιχείων περιβολή ἐστι τῶν σωμάτων. πᾶσα οὖν ψυχή, ἐν τῷ σώματι οὖσα, βαρεῖται καὶ θλίβεται τοῖς τέτταρσι τούτοις. καὶ γὰρ εἰκός ἐστι καὶ ταύτην τισὶ μὲν τούτων τέρπεσθαι, τισὶ δὲ ἄχθεσθαι. διὰ τοῦτο οὖν οὐκ ἔχει ἐνταῦθα τὴν ἀκροτάτην εὐδαιμονίαν, ἀλλ᾽ ὡς ἂν φύσει θεία οὖσα κἀν τούτοις οὖσα μάχεται· καὶ νοεῖ, ἀλλ᾽ οὐχ ὅσα ἂν ἐνόησεν ἀσύνδετος οὖσα σώματι. ἐὰν μέντοι καὶ τοῦτο σάλον λάβῃ καὶ ταραχὴν ἤτοι ἀπὸ νόσου ἢ φόβου, τότε καὶ αὐτὴ ὥσπερ ἐν βυθῷ ἄνθρωπος ἐπικυμαίνεται, καὶ οὐδὲν ἀνθισταμένη φέρεται.", "st": "24.19"}, {"sp": "SEC", "t": "XXV", "st": "25.1"}, {"sp": "N", "t": "Θαυμαστῶς, εἶπεν Ὧρος, ἕκαστά μοι διηγήσω, ὦ μέγα δυναμένη τεκοῦσα Ἶσι, ὑπὲρ τῆς θαυμαστῆς ψυχοποιίας τοῦ θεοῦ, καὶ θαυμάζων διατελῶ· οὔπω δέ μοι ἀπήγγειλας ποῦ τῶν σωμάτων ἀπολυθεῖσαι χωροῦσιν αἱ ψυχαί. βούλομαι οὖν καὶ τῆς θεωρίας ταύτης μύστης γενόμενος εὐχαριστῆσαι σοὶ μόνῃ, ἀθάνατε μῆτερ.", "st": "25.1"}, {"sp": "N", "t": "— καὶ εἶπεν Ἶσις· Πρόσεχε, παῖ· ἀναγκαιοτάτη γὰρ ζήτησις αὕτη· τὸ συνεστὸς καὶ μὴ ἀφανιζόμενον χῶρον ἔχει.", "st": "25.2"}, {"sp": "N", "t": "ἀλλ᾽ ὧδε γὰρ ἐρεῖ λόγος ἐμός.", "st": "25.3"}, {"sp": "N", "t": "Ποῦ τῶν σωμάτων ἀπολυθεῖσαι διατρίβουσιν αἱ ψυχαί.", "st": "25.3"}, {"sp": "N", "t": "οὐ γάρ, ὦ θαυμαστὲ καὶ μεγάλου πατρὸς Ὀσίρεως μέγα τέκνον, ἀκρίτως καὶ ὁρμηδὸν τῶν σωμάτων προελθοῦσαι εἰς ἀέρα ἀναχύνονταί τε καὶ διασκεδάννυνται μετὰ τοῦ ἄλλου ἀπείρου πνεύματος· εἶτα οὐκέτι δύνασθαι πάλιν τὰς αὐτὰς οὔσας εἰς σώματα παλινδρομῆσαι, ἀλλὰ οὐδὲ εἰς ἐκεῖνον ἔτι τὸν χῶρον εἶναι, ὅθεν ἦλθον τὸ πρότερον, ἀναστρέφειν, καθάπερ οὐδὲ τὸ λαμβανόμενον ἐκ τῶν κάτω ἀγγείων ὕδωρ εἰς τοὺς αὐτοὺς τόπους ὅθεν ἐλήφθη ἐπέχειν ἐστὶ δυνατόν, ἀλλ᾽ οὐδ᾽ αὐτὸ παραυτίκα λαμβανόμενον καὶ χεόμενον τὴν ἰδίαν λαμβάνει χώραν, πλὴν ἀναμίγνυται τῷ παντὶ τοῦ ὕδατος χύματι.", "st": "25.3"}, {"sp": "N", "t": "ἀλλ᾽ οὐκ ἔχει οὕτως, ὦ μεγαλόφρων Ὧρε· μύστης δὲ ὥσπερ τῆς ἀθανάτου φύσεως καὐτὴ τυγχάνουσα, καὶ ὡδευκυῖα διὰ τοῦ πεδίου τῆς ἀληθείας, διεξελεύσομαί σοι τῶν ὄντων τὸ καθ᾽ ἕκαστον, ἐκεῖνό σοι φήσασα πρῶτον, ὡς δὴ τὸ ὕδωρ σῶμά ἐστιν ἄλογον, ἐκ πολλῶν συγκεκριμένον παρατεθλιμμένων εἰς χύσιν, ἡ δὲ ψυχὴ πρᾶγμα ἰδιοφυές, τέκνον, καὶ βασιλικόν, καὶ ἔργον τῶν τοῦ θεοῦ χειρῶν τε καὶ νοῦ, αὐτῷ θ᾽ ἑαυτῷ εἰς νοῦν ὁδηγούμενον. τὸ τοίνυν ἐξ ἑνὸς καὶ οὐκ ἐκ πολλῶν ἀδύνατον ἑτέρῳ ἀναμιγῆναι· ὅθεν δεῖ καὶ τὴν πρὸς τὸ σῶμα αὐτῆς σύνοδον, ἁρμονίαν θεοῦ, ὑπὸ ἀνάγκης γενομένην εἶναι.", "st": "25.4"}, {"sp": "N", "t": "ὅτι δὲ οὔτε εἰς ἕνα καὶ τὸν αὐτὸν τόπον χυδαίως, οὔτε εἰκῇ καὶ ὡς ἔτυχεν, ἀλλὰ ἑκάστη ἐπὶ τὴν ἰδίαν ἀναπέμπεται χώραν, φανερὸν καὶ ἐξ ὧν ἔτι ἐν τῷ σώματι οὖσα καὶ τῷ πλάσματι πάσχει γὰρ παρὰ τὴν ἰδίαν φύσιν πεπαχυμμένη.", "st": "25.5"}, {"sp": "N", "t": "ἀλλὰ καὶ πρόσχες, ὦ περιπόθητε Ὧρε, τῷ λεγομένῳ ὁμοιώματι. φέρε γὰρ εἰς ἓν καὶ τὸ αὐτὸ συσχετήριον ἐγκεκλεῖσθαι ἀνθρώπους τε, καὶ ἀετοὺς καὶ περιστερὰς καὶ κύκνους καὶ ἱέρακας καὶ χελιδόνας καὶ στρουθοὺς καὶ μυίας, καὶ ὄφεις, καὶ λέοντας καὶ παρδάλεις καὶ λύκους καὶ κύνας καὶ λαγωοὺς καὶ βόας καὶ ποίμνια, καί τινα τῶν τῆς κοινότητος ἐχομένων ζῴων, οἱονεὶ φώκας καὶ ἐνύδρεις καὶ χελώνας καὶ τοὺς ἡμετέρους κροκοδείλους· ἔπειτα τούτους, ὦ τέκνον, ὑπὸ μίαν ῥοπὴν ἀπολυθῆναι τοῦ συσχετηρίου.", "st": "25.6"}, {"sp": "N", "t": "πάντως τραπήσονται οἱ μὲν ἄνθρωποι εἴς τε ἀγορὰς καὶ στέγας, ὁ δὲ ἀετὸς εἰς τὸν αἰθέρα, ὅπου καὶ φύσιν ἔχει διαιτᾶσθαι, αἱ δὲ περιστεραὶ εἰς τὸν πλησίον ἀέρα, οἱ δὲ ἱέρακες ὑπεράνω τούτων; αἱ δὲ χελιδόνες οὐχὶ ὅπου ἂν οἰκῶσιν ἄνθρωποι, οἱ δὲ στρουθοὶ περὶ τὰ καρποφόρα τῶν δένδρων, οἱ δὲ κύκνοι ὅπου ἔξεστιν αὐτοῖς ᾄδειν, αἱ δὲ μυῖαι περὶ αὐτὴν τὴν γῆν, τοσοῦτον αὐτῆς ἀπέχουσαι ὅσον ἀναβῆναι δύνανται ἀνθρώπων τῇ ὀσμῇ; ἀνθρωπόλιχνον γὰρ ἰδίως, ὦ τέκνον, ἐστὶν ἡ μυῖα, καὶ χαμαιπετές· οἱ δὲ λέοντες καὶ παρδαλεῖς οὐκ ἐπὶ τὰ ὄρη, οἱ δὲ λύκοι ἐπὶ τὰς ἐρημίας, οἱ δὲ κύνες κατ᾽ ἴχνος ἀνθρώπων, λαγωοὶ δὲ δρυμούς, καὶ βόες αὐλιστήρια πεδία, καὶ εἰς τὰς νομὰς τὰ ποίμνια; οἱ δὲ ὄφεις εἰς τὰ μύχια τῆς γῆς; φῶκαι δὲ καὶ χελῶναι μετὰ τῶν ὁμοίων εἰς βάθη καὶ νάματα. ὡς μὴ πεδιάδος γῆς στέροιντο μηδὲ τοῦ συγγενοῦς ἀπολειφθεῖεν ὕδατος, ἑκάστου εἰς τὴν οἰκείαν χώραν ὑπὸ τοῦ ἔνδον κριτηρίου ἀνατρεπομένου;", "st": "25.7"}, {"sp": "N", "t": "οὕτως ἑκάστη ψυχή, καὶ ἀνθρωπευομένη καὶ ἄλλως ἐπιγεΐζουσα, οἶδεν ὅπου πορευτέον αὐτῇ ἐστι· πλὴν εἰ μή τις τῶν Τυφωνίων, ὦ τέκνον, παρελθὼν λέγοι ὅτι δυνατὸν ταῦρον μὲν ἐν βυθῷ ἐν ἀέρι χελώνην διαζῆν. εἰ δὴ τοῦτο πάσχουσι σαρκὶ καὶ αἵματι βεβαπτισμέναι, ὡς μηδὲν παρὰ τάξιν πράσσειν κἂν κολάζωνται, κόλασις γὰρ αὐταῖς ἡ ἐνσωμάτωσις, πόσῳ πλέον βαπτισμοῦ καὶ κολάσεως καὶ ἐλευθερίας ἰδίας μετασχοῦσαι;", "st": "25.8"}, {"sp": "N", "t": "ἔχει δὲ ἡ διάταξις ἡ ἱερωτάτη οὕτως. ἤδη ποτὲ ἄνω, μεγαλοφυέστατε παῖ, βλέπε ψυχῶν διατάξεις. τὸ ἀπ᾽ οὐρανοῦ κορυφῆς μέχρι σελήνης θεοῖς καὶ ἄστροις καὶ τῇ ἄλλῃ προνοίᾳ σχολάζει· τὸ δὲ ἀπὸ σελήνης, ὦ τέκνον, ἐφ᾽ ἡμᾶς ψυχῶν ἐστιν οἰκητήριον.", "st": "25.9"}, {"sp": "N", "t": "ἔχει μέντοι ἐν ἑαυτῷ ὁδὸν ὁ τοσοῦτος ἀήρ, ὃν ἄνεμον καλεῖν ἔθος ἐστὶν ἡμῖν, ἴδιον μέγεθος ἐν ᾧ κινεῖται πρὸς ἀνάψυξιν τῶν ἐπιγείων· ὃ δὴ καὶ ὕστερον ἐρῶ. κατ᾽ οὐδένα μέντοι τρόπον πρὸς ἑαυτὸν κινούμενος ἐμπόδιον γίγνεται ψυχαῖς· κινουμένου γὰρ τούτου ἔξεστι ψυχαῖς ἀναΐσσειν καὶ καταΐσσειν, ὡς ἂν τύχῃ, ἀδιακωλύτως. ῥέουσι γὰρ δι᾽ αὐτοῦ ἀμιγῶς καὶ ἀκολλητί, ὡς δι᾽ ἐλαίου ὕδωρ.", "st": "25.10"}, {"sp": "N", "t": "τὸ δὲ διάστημα τοῦτο, ὦ τέκνον Ὧρε, μοιρῶν μέν ἐστι γενικῶν τεσσάρων, ἰδικῶν δὲ χωρῶν ἑξήκοντα· ὧν ἡ μὲν ἀπὸ γῆς ἄνω χωρῶν ἐστι τεσσάρων, ὡς τὴν γῆν κατά τινας λόφους καὶ ἀκρωρείας ἀνατεῖναι καὶ φθάνειν ἄχρι τοσούτου· ὑπὲρ γὰρ ταύτης αὐτὴν ἀναβῆναι τὸ ὕψος οὐκ ἔχει φύσιν. ἡ δ᾽ ἀπὸ ταύτης δευτέρα ἐστι χωρῶν ὀκτώ· ἐν αἷς γίγνονται ἀνέμων κινήσεις. πρόσεχε, παῖ· ἀρρήτων γὰρ ἐπακούεις μυστηρίων γῆς τε καὶ οὐρανοῦ καὶ παντὸς τοῦ μέσου ἱεροῦ πνεύματος. ὅπου ἡ τοῦ ἀνέμου κίνησις, καὶ ἡ τῶν ὀρνέων πτῆσις· ὑπὲρ γὰρ ταύτης οὔτε ἀὴρ κινεῖται οὔτε ζῷον βαστάζει. ἔχει μέντοι παρὰ τῆς φύσεως ταύτην τὴν ἐξουσίαν ὁ ἀὴρ οὗτος, ὥστε καὶ ἐν ταῖς ἰδίαις ὀκτὼ χώραις καὶ ἐν ταῖς τῆς γῆς τέτταρσι περιπολεῖ μεθ᾽ ὧν ἔχει ζῴων, τῆς γῆς εἰς τὰς ἑαυτοῦ ἐπαναβῆναι δυναμένης.", "st": "25.11"}, {"sp": "N", "t": "ἡ δὲ τρίτη χωρῶν ἐστιν ἑκκαίδεκα, ἀέρος λεπτοῦ καὶ καθαροῦ πλήρης. ἡ δὲ τετάρτη ἐστὶ δύο καὶ τριάκοντα, ἐν αἷς ἐστι λεπτότατος καὶ εἰλικρινέστατος ἀὴρ καὶ διαυγής, διορίζων ἐφ᾽ ἑαυτοῦ τοὺς ἄνω οὐρανούς, ἐκπύρους ὄντας τὴν φύσιν.", "st": "25.12"}, {"sp": "N", "t": "καὶ ἔστιν ἡ διάταξις αὕτη κατ᾽ εὐθυτενῆ γραμμὴν ἄνωθεν κάτω ἀκολλητὶ τὴν φύσιν, ὡς εἶναι μοίρας γενικὰς μὲν τέσσαρας, διαστηματικὰς δὲ δώδεκα, χώρας δὲ ἑξήκοντα. ἐν δὲ ταῖς χώραις ταύταις, ἑξήκοντα οὔσαις τὸν ἀριθμόν, οἰκοῦσιν αἱ ψυχαί, ἑκάστη πρὸς ἣν ἔχει φύσιν, μίας μὲν καὶ τῆς αὐτῆς συστάσεως οὖσαι, οὐκέτι δὲ τιμῆς· ὅσῳ γὰρ ἑκάστη τῶν χωρῶν ἀπὸ γῆς ὑπερβέβηκε τῆς ἑτέρας, τοσούτῳ καὶ ἐν αὐταῖς ψυχαὶ ἑτέρα τὴν ἑτέραν καθ᾽ ὑπεροχὴν λείπειν, ὦ τέκνον. χώρα καὶ ψυχή.", "st": "25.13"}, {"sp": "N", "t": "τίνες μὲν οὖν εἰς ἑκάστην τούτων ἀναλύουσι ψυχαί, ἐντεῦθέν σοι πάλιν, ὦ μεγαλόδοξε Ὧρε, καταλέγειν ἄρξομαι, ἄνωθεν ἐπὶ τὰ πρόσγεια τὴν τάξιν ποιουμένη.", "st": "25.14"}, {"sp": "SEC", "t": "XXVI", "st": "26.1"}, {"sp": "N", "t": "Τὸ μεταξὺ γῆς καὶ οὐρανοῦ κεχωρίσται, τέκνον Ὧρε, πρὸς μέτρον καὶ ἁρμονίαν. αἱ δὲ χῶραι αὗται ὑπὸ τῶν προγόνων καλοῦνται ὑφ᾽ ὧν μὲν ζῶναι, ὑφ᾽ ὧν δὲ στερεώματα, ὑπὸ δὲ ἑτέρων πτυχαί. ἐν δὲ ταύταις φοιτῶσιν αἵ τε ἀπολελυμέναι τῶν σωμάτων ψυχαὶ αἵ τε μηδέπω ἐνσωματισθεῖσαι. ἑκάστη δὲ τούτων, ὦ τέκνον, κατὰ τὴν ἀξίαν καὶ χώραν ἔχει, ὥστε τὰς μὲν θείας καὶ βασιλικὰς ἐν τῇ ὑπεράνω πάντων κατοικεῖν, τὰς δὲ ἐλαχίστας κατὰ τιμήν, καὶ τὰς ἄλλας ὅσαι εἰσὶ χαμαιπετεῖς, ἐν τῇ ὑποκάτω πάντων, τὰς δὲ μέσας τῇ μέσῃ.", "st": "26.1"}, {"sp": "N", "t": "αἱ μὲν οὖν εἰς τὸ ἄρχειν καταπεμπόμεναι, ὦ τέκνον Ὧρε, ἐκ τῶν ὑπεράνω ζωνῶν καταπέμπονται· αἳ καὶ λυθεῖσαι εἰς τὰς αὐτὰς ἢ καὶ ἔτι ὑπεράνω ἀνέρχονται, πλὴν εἰ μή τινες ἔτι εἶεν τὴν ἀξίαν τῆς ἑαυτῶν φύσεως καὶ τὴν τοῦ θείου νόμου παραγγελίαν πεπραχυῖαι· ταύτας γὰρ ἡ ἄνω πρόνοια πρὸς μέτρον τῶν ἁμαρτημάτων εἰς τὰς ὑποκάτω χώρας ἐξορίζει, ὥσπερ καὶ τὰς ὑποδεεστέρας δυνάμει τε καὶ ἀξίᾳ ἐκ γὰρ κατωτέρων ἐπὶ μείζονας καὶ ὑψηλοτέρας ἀνάγει.", "st": "26.2"}, {"sp": "N", "t": "εἰσὶ γὰρ ἄνωθεν οἱ δορυφόροι ὄντες τῆς καθόλου προνοίας, ὧν ὁ μὲν ψυχοταμίας, ὁ δὲ ψυχοπομπός· καὶ ὁ μὲν ψυχοταμίας ψυχῶν, ὁ δὲ ψυχοπομπὸς ἀποστολεύς τε καὶ διατάκτης τῶν ἐνσωματουμένων ψυχῶν· καὶ ὁ μὲν τηρεῖ, ὁ δὲ προίησι κατὰ γνώμην τοῦ θεοῦ.", "st": "26.3"}, {"sp": "N", "t": "τῷ οὖν λόγῳ τούτῳ, ὦ παῖ, καὶ τῇ ἄνω τῶν πραγμάτων ἐξαλλαγῇ καὶ ἐπὶ γῆς ἐστιν ἡ φύσις, πλάστρια γὰρ οὖσα, καὶ σκηνοποιὸς ἀγγείων εἰς ⟨ἃ⟩ βάλλονται αἱ ψυχαί. παρεστᾶσι δὲ δύο ἐνέργειαι καὶ αὐτῇ, μνήμη καὶ ἐμπειρία. καὶ ἡ μὲν μνήμη ἔργον ἔχει τοῦτο, ὅπως ἡ φύσις τηρῇ καὶ περικρατῇ τοῦ τε ἑκάστου τύπου ἐξ ἀρχῆς καταβεβλημένου, καὶ τοῦ παραδείγματος τοῦ ἄνω γίγνηται· ἡ δὲ ἐμπειρία, ὅπως πρὸς ἀνάλογον ἑκάστης τῶν καταβαινουσῶν ψυχῶν εἰς τὸ σωματισθῆναι καὶ τὸ πλάσμα ἐνεργῆ καὶ γένηται, καὶ ταῖς μὲν ὀξέσι τῶν ψυχῶν ὀξέα γένηται καὶ τὰ σώματα, ταῖς δὲ βραδέσι βραδέα, ταῖς δὲ ἐνεργέσιν ἐνεργῆ, καὶ ταῖς νωθραῖς νωθρά, καὶ ταῖς δυναταῖς δυνατά, καὶ ταῖς δολίαις δόλια, καὶ ἁπαξαπλῶς ἑκάσταις κατὰ τὸ εἰκός.", "st": "26.4"}, {"sp": "N", "t": "οὐ γὰρ ἀσκόπως πτηνὰ μὲν ἐπτίλωσε, λογικὰ δὲ περισσαῖς καὶ ἀκριβεστέραις αἰσθήσεσιν ἐκόσμησε, τετραπόδων δὲ τὰ μὲν κέρασι, τὰ δὲ ὀδοῦσι, τὰ δὲ ὄνυξι καὶ ὁπλαῖς ἐκαρτέρωσε. τὰ δὲ ἑρπετὰ εὐχαίτοις σώμασι καὶ εὐυποχωρήτοις ἐμαλάκυνε, καὶ ὅπως μὴ τῇ τοῦ σώματος ὑγρότητι τέλεον ἀσθενῆ διαμένῃ, ὧν μὲν τὰ στόματα καὶ τοῖς ὀδοῦσιν ἐχαράκωσεν, ὧν δὲ τοὺς ὄγκους αὐξήσασα δύναμιν περιέθηκεν. οὕτως τὰ μὲν τῇ τοῦ θανάτου εὐλαβείᾳ ἰσχυρότερα τῶν ἄλλων. τὰ δὲ νηκτά, δειλὰ ὄντα, ἐνοικεῖν ἔδωκε στοιχείῳ ἐν ᾧ τὸ φῶς οὐδετέραν ὧν ἔχει δυνάμεων ἐνεργεῖν ἰσχύει· ⟨ἐν⟩ γὰρ ὕδατι τὸ πῦρ οὔτε φαίνει οὔτε καίει· ἕκαστον δὲ αὐτῶν ἢ φολίσιν ἢ ἀκάνθαις ἐν ὕδατι νηχόμενον φεύγει ὅπῃ ἂν θέλῃ, τὴν ἰδίαν περιβεβλημένον δειλίαν, καὶ σκεπαστήριον ἔχον εἰς τὸ μὴ ὁρᾶσθαι τὸ ὕδωρ.", "st": "26.5"}, {"sp": "N", "t": "εἰς γὰρ ἕκαστον τῶν σωμάτων τούτων καθ᾽ ὁμοιότητα ἐγκλείονται αἱ ψυχαί, ὥστε εἰς μὲν ἀνθρώπους χωρεῖν τὰς κριτικάς· εἰς δὲ πτηνὰ τὰς ἀπανθρώπους· εἰς δὲ τετράποδα ἀκρίτους, νόμος γὰρ ἐκείνοις ἐστὶν ἡ ἰσχύς· εἰς δὲ ἑρπετὰ τὰς δολίας, οὐδὲν γὰρ αὐτῶν ἐξ ἐναντίου ἐπεξέρχεται τοῖς ἀνθρώποις, λοχήσαντα δὲ καταβάλλει· εἰς δὲ τὰ νηκτὰ τὰς δειλάς, καὶ ὅσα τῶν λοιπῶν στοιχείων ἀπολαύειν ἀνάξια τυγχάνει.", "st": "26.6"}, {"sp": "N", "t": "γίγνεται μὲν οὖν καὶ ἐν ἑκάστῳ εὑρεῖν ζῷον τῇ ἰδίᾳ φύσει μὴ καταχρώμενον. — Πῶς πάλιν, ὦ τεκοῦσα; εἶπεν Ὧρος. — καὶ ἀπεκρίθη Ἶσις· Ὥστε ἄνθρωπον μέν, ὦ τέκνον, τὸ κριτικὸν ὑπερβῆναι, τετράπουν δὲ τὴν ἀνάγκην παραλλάξαι, ἑρπετὸν δὲ τὸ δόλιον ἀπολέσαι, καὶ νηκτὸν τῆς δειλίας καταφρονῆσαι, καὶ πτηνὸν τῆς ἀπανθρωπίας ἐκπεσεῖν.", "st": "26.7"}, {"sp": "N", "t": "καὶ τὰ μὲν περὶ τῆς διαθέσεως τῶν ἄνω καὶ τῆς καταβάσεως αὐτῶν καὶ τῆς σωματουργίας τοσαῦτα.", "st": "26.7"}, {"sp": "N", "t": "συμβαίνει δέ, ὦ τέκνον, ἐν ἑκάστῳ εἴδει εὑρίσκεσθαι καὶ γένει τῶν προκειμένων βασιλικάς τινας ψυχάς. καταβαίνειν δὲ καὶ ἄλλας ἀλλοίους, τὰς μὲν διαπύρου τὰς δὲ ψυχρὰς τὰς δὲ ὑπερηφάνους τὰς δὲ πραείας τὰς δὲ βαναύσους τὰς δὲ ἐμπείρους τὰς δὲ ἀπείρους τὰς δὲ ἀργὰς τὰς δὲ ἐνεργεῖς τὰς δὲ ἄλλο τι ἄλλως οὔσας. συμβαίνει δὲ τοῦτο παρὰ τὴν τῶν τόπων θέσιν ὅθεν εἰς τὸ ἐνσωματισθῆναι καὶ θάλλονται αἱ ψυχαί. αἱ μὲν γὰρ ἀπὸ βασιλικοῦ διαζώματος καταπηδῶσι τῆς ὁμοιοπάθους βασιλευούσης ψυχῆς.", "st": "26.8"}, {"sp": "N", "t": "πολλαὶ γάρ εἰσι βασιλεῖαι· αἱ μὲν γάρ εἰσι ψυχῶν αἱ δὲ σωμάτων, αἱ δὲ τέχνης αἱ δὲ ἐπιστήμης, αἱ δὲ αὑτῶν. — Πῶς πάλιν, εἶπεν Ὧρος, καὶ ἑαυτῶν; — Οἷον, ὦ τέκνον Ὧρε, ἀπογεγονότων ἤδη ψυχῶν μὲν Ὄσιρις ὁ πατήρ σου, σωμάτων δὲ ὁ ἑκάστου ἔθνους ἡγεμών· βουλῆς δὲ ὁ πατὴρ πάντων· καὶ καθηγητὴς ὁ τρισμέγιστος Ἑρμῆς, ἰατρικῆς δὲ ὁ Ἀσκληπιὸς ὁ Ἡφαίστου· ἰσχύος δὲ καὶ ῥώμης πάλιν Ὄσιρις, μεθ᾽ ὅν, ὦ τέκνον, αὐτὸς σύ· φιλοσοφίας δὲ Ἁρνεβεσχῆνις· ποιητικῆς δὲ πάλιν ὁ Ἀσκληπιὸς Ἰμούθης. καθόλου γάρ, ὦ τέκνον, εὑρήσεις, ἐὰν ἐξετάσῃς, πολλοὺς καὶ πολλῶν ἄρχοντας καὶ πολλοὺς πολλῶν βασιλεύοντας.", "st": "26.9"}, {"sp": "N", "t": "ἀλλ᾽ ὁ μὲν πάντων κρατῶν, τέκνον, ἐκ τῆς ὑπεράνω χώρας ἐστίν, ὁ δὲ τῶν κατὰ μέρος ἐκείνην ἔσχε τὴν ἀφ᾽ οὗ τόπου ἐστὶν βασιλικωτέραν.", "st": "26.10"}, {"sp": "N", "t": "* * * διαζώματος τετευχότες πυρὸς ἐργάται γίγνονται καὶ τροφῆς, οἱ δὲ ἀπὸ ὑγροῦ ἐν ὑγροῖς διαζώμασιν, οἱ δὲ ἀπὸ ἐπιστημονικοῦ καὶ τεχνικοῦ περὶ ἐπιστήμας καταγίγνονται καὶ τέχνας, οἱ δὲ ἀπὸ ἀργοῦ ἀργῶς καὶ ἐπιρρεμβῶς διαζῶσι. πάντων γὰρ τῶν ἐπὶ γῆς, ὦ τέκνον, διὰ λόγου καὶ ἔργου πραττομένων ἄνω εἰσὶν αἱ πηγαί, μέτρῳ καὶ σταθμῷ ἐπιχύνουσαι ἡμῖν τὰς οὐσίας, καὶ οὐκ ἔστιν ὃ μὴ ἄνωθεν καταβέβηκε.", "st": "26.11"}, {"sp": "N", "t": "καὶ πάλιν ἀνέρχεται ἵνα κατέβη. — Πῶς πάλιν λέγεις τοῦτο, ὦ τεκοῦσα; παράδειξον. — Καὶ ἀπεκρίθη Ἶσις πάλιν· Τῆς παλινδρομίας ἐναργὲς τοῦτο σημεῖον τοῖς ζῴοις ἐνέθηκεν ἡ ἱερωτάτη φύσις· τοῦτο γὰρ ὃ σπῶμεν ἄνωθεν ἐξ ἀέρος πνεῦμα, τοῦτο πάλιν ἄνω πέμπομεν, ὅθεν ἐλάβομεν. καὶ εἰσίν, ὦ τέκνον, τούτου τοῦ ἐνεργήματος τεχνίτιδες ἐν ἡμῖν φῦσαι· αἳ ἐπειδὰν μύσωσι τὰ δεκτικὰ ἑαυτῶν τοῦ πνεύματος στόματα, τότε ἡμεῖς οὐκέτι ὧδέ ἐσμεν, ἀλλ᾽ ἀναβεβήκαμεν.", "st": "26.12"}, {"sp": "N", "t": "προσεπιγίγνεται δέ, ὦ παῖ μεγαλόδοξε, καὶ ἕτερά τινα ἡμῖν ἐκ τῆς τοῦ φυράματος συσταθμίας. — Τί δέ ἐστιν, Ὧρος εἶπε, τὸ φύραμα τοῦτο, ὦ τεκοῦσα; — Σύνοδός ἐστι καὶ κρᾶσις τῶν τεσσάρων στοιχείων, ἐξ ἧς κράσεως καὶ συνόδου ἀναθυμιᾶταί τις ἀτμός, ὃς περιειλεῖται μὲν τῇ ψυχῇ, διατρέχει δὲ ἐν σώματι, ἀμφοτέροις μεταδιδούς, τουτέστι τῷ σώματι καὶ τῇ ψυχῇ, τῆς ἰδίας ποιότητος· καὶ οὕτως αἱ διαφοραὶ τῶν ψυχικῶν καὶ σωματικῶν ἐναλλοιώσεων γίνονται.", "st": "26.13"}, {"sp": "N", "t": "εἰ μὲν γὰρ κατὰ τὴν σωματικὴν διάπηξιν πλεονάσειε τὸ πῦρ, τὸ τηνικαῦτα ἡ ψυχὴ θερμὴ τὴν φύσιν ὑπάρχουσα καὶ ἕτερον θερμὸν προσλαβοῦσα ἐκπυρωδεστέρα γενομένη ποιεῖ τὸ ζῷον ἐνεργότερον καὶ θυμικόν, τὸ δὲ σῶμα ὀξὺ καὶ εὐκίνητον.", "st": "26.14"}, {"sp": "N", "t": "εἰ δὲ πλεονάσειεν ὁ ἀήρ, τὸ τηνικαῦτα καὶ κοῦφον καὶ πηδητικὸν καὶ ἀνέδραστον γίνεται τὸ ζῷον καὶ ψυχῇ καὶ σώματι.", "st": "26.15"}, {"sp": "N", "t": "εἰ δὲ τὸ ὕδωρ πλεονάσειε, τὸ τηνικαῦτα καὶ τὸ ζῷον τῇ μὲν ψυχῇ γίγνεται εὔχρουν καὶ εὐφυὲς καὶ εὐπερίχυτον, ἱκανῶς τε τοῖς ἄλλοις ἐπιπεσεῖν καὶ κολληθῆναι δυνάμενον, διὰ τὸ πρὸς τὰ ἄλλα ἑνωτικὸν καὶ κοινωνικὸν τοῦ ὕδατος· ἐφιζάνει γὰρ πᾶσι, καὶ πολὺ μὲν ὂν εἰς ἑαυτὸν ἀναλύει καὶ περιλαμβάνει, ὀλίγον δ᾽ ὑπάρχον καὶ καταδῦσαν ἐκεῖνο γίγνεται ᾧ ἐμίγη. τὰ μέντοι σώματα ὑπὸ τῆς πλαδαρότητος καὶ χαυνότητος εἰς περίσφιγξιν οὐ συνάγεται, ἀλλὰ μικρᾷ τινι νόσου ἀφορμῇ λύεται καὶ τοῦ ἰδίου συνδέσμου κατ᾽ ὀλίγον ἐκπίπτει.", "st": "26.16"}, {"sp": "N", "t": "εἰ δὲ τὸ γεῶδες πλεονάσειε, τὸ τηνικαῦτα ἀμβλεῖα μὲν τοῦ ζῴου ἡ ψυχὴ γίνεται, οὐκ ἔχουσα τὴν σωματικὴν ἀραιότητα εὔλυτον, οὐδὲ τοῦ δι᾽ οὗ πηδήσεται, πεπαχυμένων τῶν αἰσθητικῶν μερῶν, ἀλλ᾽ ἔνδον μένει παρ᾽ ἑαυτῇ, ὑπὸ βάρους καὶ πυκνότητος πεδηθεῖσα· τὸ δὲ σῶμα στερεὸν μέν, ἀλλὰ ἀργὸν καὶ βαρύ, καὶ μετὰ βίας ὑπὸ τῆς προαιρέσεως μετακινούμενον.", "st": "26.17"}, {"sp": "N", "t": "εἰ δὲ σύμμετρος γένοιτο ἡ πάντων στάσις, τότε τὸ ζῷον θερμὸν εἰς πρᾶξιν, κοῦφον δὲ εἰς κίνησιν, εὔκρατον δὲ εἰς ἁφήν, γενναῖον δὲ εἰς τῆξιν κατασκευάζεται.", "st": "26.18"}, {"sp": "N", "t": "ὅσα οὖν τῷδε τῷ λόγῳ κεκοινώνηκε πλείονος μὲν πυρὸς καὶ πνεύματος, ταῦτα ἀπωρνέωται, καὶ ἄνω παρ᾽ ἐκείνοις πολιτεύεται τοῖς στοιχείοις ἐξ ὧν καὶ ἐγένετο.", "st": "26.19"}, {"sp": "N", "t": "ὅσα δὲ πλείονος μὲν πυρός, ὀλίγου δὲ πνεύματος, ὕδατος δὲ καὶ γῆς ἴσης, ταῦτα ἀπηνθρώπισται· καὶ τῷ ζῴῳ τὸ περισσὸν τοῦ θερμοῦ εἰς σύνεσιν ἐτράπη. ὁ γὰρ ἐν ἡμῖν νοῦς θερμόν τι χρῆμά ἐστιν, ὃ καίειν μὲν οὐκ οἶδε, διαδύνει δὲ κατὰ πάντων καὶ ἐπίσταται.", "st": "26.20"}, {"sp": "N", "t": "ὅσα δὲ πλείονος μὲν ὕδατος, πλείονος δὲ γῆς, μετρίου δὲ πνεύματος καὶ ὀλίγου δὲ πυρός, ταῦτα τεθηρίωται· τῇ δὲ τοῦ θερμοῦ παρουσίᾳ ἀλκιμώτερα γέγονε τῶν ἄλλων.", "st": "26.21"}, {"sp": "N", "t": "ὅσα δὲ γῆς καὶ ὕδατος ἴσων κεκοινώνηκε, ταῦτα ἀφηρπέτωται· καὶ τῇ τοῦ πυρὸς στερήσει ἄτολμα γέγονε καὶ ἀπαρρησίαστα, τῇ δὲ τοῦ ὕδατος κοινωνίᾳ ψυχρὰ ἐγένετο, τῇ δὲ τῆς γῆς βαρέα καὶ νωθρά, τῇ δὲ τοῦ πνεύματος εὐκίνητα εἰ προαιρέσει τὸ κινεῖσθαι.", "st": "26.22"}, {"sp": "N", "t": "ὅσα δὲ πλείονος μὲν ὑγροῦ, ὀλίγου δὲ ξηροῦ, ταῦτα ἀπιχθύωται· καὶ τῇ μὲν τοῦ θερμοῦ καὶ ἀέρος στερήσει δειλά ἐστι καὶ καταδυτικά, τῇ δὲ τοῦ ὑγροῦ περιουσίᾳ καὶ τῇ τοῦ γεώδους παρουσίᾳ ἐν λελυμένῃ γῇ καὶ ὕδατι διὰ τὸ συγγενὲς κατοικεῖ.", "st": "26.23"}, {"sp": "N", "t": "καὶ πρὸς μὲν τὴν τοῦ ἑκάστου στοιχείου μοῖραν καὶ τῆς μοίρας τὴν περιοχὴν καὶ τὰ σώματα ἡλικιάζεται καὶ πρὸς τὴν ὀλιγομετρίαν τὰ λοιπὰ ζῷα μεμετροποίηται πρὸς ἐνέργειαν τὴν ἑκάστῳ τῶν στοιχείων οὐσιομετρίας·", "st": "26.24"}, {"sp": "N", "t": "καὶ ἔτι, ὦ παῖ περιπόθητε, λέγω, ὅτι ἐκ ταύτης τῆς οὕτω συστάσεως ἡ κατὰ τὴν πρώτην σύνοδον γενομένη κρᾶσις καὶ ὁ ἐκ ταύτης ἀναθυμιώμενος ἀτμὸς ἐφ᾽ ὅσον τὴν ἰδίαν τηρεῖ ποιότητα, ὥστε τὸ μὲν θερμὸν ἕτερον μὴ λαβεῖν θερμόν, καὶ τὸ ἀερῶδες πνεῦμα ἕτερον, μηδὲ τὸ ὑγρὸν ἑτέραν ὑγρασίαν, μηδὲ τὸ γεῶδες ἑτέραν πυκνότητα, τὸ τηνικαῦτα τὸ ζῷον ὑγιαίνει· ἐπὰν γὰρ μὴ οὕτως μένῃ, ὦ τέκνον, ἐφ᾽ οἷς ἔσχεν ἐξ ἀρχῆς μέτροις, ἀλλ᾽ ἤτοι πλεονάσῃ τούτων, οὐκ ἐνεργείᾳ λέγω τὴν περιοχήν, οὐδὲ τῇ κατ᾽ αὔξησιν γινομένῃ μεταβολῇ τοῦ γένους καὶ τῶν σωμάτων, ἀλλὰ τῇ ὡς προέφημεν συστατικῇ τῶν στοιχείων κράσει, ὥστε τὸ μὲν θερμὸν ἐπὶ πλέον αὐξηθῆναι ἢ ἐπὶ πλέον ἐλαττωθῆναι, τὰ δὲ ἄλλα ὁμοίως, τηνικαῦτα οὕτως νοσεῖ τὸ ζῷον.", "st": "26.25"}, {"sp": "N", "t": "ἐπὰν γὰρ οὕτως διατεθῇ τό τε θερμὸν καὶ τὸ ἀερῶδες, ἃ δὴ σύσκηνά ἐστι τῆς ψυχῆς, τότε ἐν ἀλληγορίαις καὶ ἐκστάσεσι γίγνεται τὸ ζῷον. πεπύκνωται γὰρ τὰ στοιχεῖα δι᾽ ὧν διαφθείρεται τὰ σώματα.", "st": "26.26"}, {"sp": "N", "t": "αὐτὸ μὲν γὰρ τὸ γεῶδές ἐστιν ἡ τοῦ σώματος πῆξις, τὸ δὲ ὑγρὸν ἡ ἐν τούτῳ ἐστὶν εἰς συμπαγίαν περίχυσις, τὸ γὰρ ἀερῶδές ἐστι τὸ ἐν ἡμῖν κινητικόν, καὶ τούτων πάντων διεγερτικὸν τὸ πῦρ.", "st": "26.27"}, {"sp": "N", "t": "ὥσπερ οὖν ὁ ἐκ τῆς πρώτης συνόδου καὶ κράσεως τῶν στοιχείων γιγνόμενος ἀτμὸς καὶ ὡσανεὶ ἔξαψις καὶ ἀναθυμίασις, ὁποῖος ἐὰν ᾖ, παραμιγεὶς τῇ ψυχῇ, ἄγει ἑαυτὴν εἰς ἑαυτόν, ὡς ἂν ἔχῃ φύσεως, εἴτε σπουδαίως εἴτε μή.", "st": "26.28"}, {"sp": "N", "t": "τῇ γὰρ ἐξ ἀρχῆς πρὸς αὐτὸν οἰκειότητι καὶ συντροφίᾳ ἐπιμένουσα ἡ ψυχὴ τὴν τάξιν διατηρεῖ· ὅταν δὲ ἐπιπροσγένηται ἤτοι τῷ ὅλῳ συγκράματι ἢ καὶ μέρεσιν ἢ μέρει αὐτοῦ ἔξωθέν τις πλείων μοῖρα τοῦ προκαταβεβλημένου, τότε καὶ ὁ ἐντεῦθεν μεταλλοιούμενος ἀτμὸς μεταλλοιοῖ ἤτοι τὴν τῆς ψυχῆς διάθεσιν ἢ τὴν τοῦ σώματος.", "st": "26.29"}, {"sp": "N", "t": "τὸ γὰρ πῦρ καὶ τὸ πνεῦμα, ἀνωφερῆ ὄντα, ἐπὶ τὴν ψυχήν, ὁμοιόχωρον αὐτοῖς ὑπάρχουσαν, ἀνατρέχει, τὸ δὲ ὑγρὸν καὶ τὸ γεῶδες, κατωφερῆ ὄντα, τῷ σώματι, ὁμοέδρῳ ὄντι, ἐφιζάνει.", "st": "26.30"}, {"sp": "SEC", "t": "XXVII", "st": "27.1"}, {"sp": "N", "t": "ἔλεγχος γὰρ ἐπιγνωσθείς, ὦ μέγιστε βασιλεῦ, εἰς ἐπιθυμίαν φέρει τὸν ἐλεγχθέντα ὧν πρότερον οὐκ ᾔδει.", "st": "27.1"}, {"sp": "SEC", "t": "XXVIII", "st": "28.1"}, {"sp": "N", "t": "Θαλῆς, ἐρωτηθεὶς τί πρεσβύτατον τῶν ὄντων, ἀπεκρίνατο· Θεός, ἀγέννητον γάρ.", "st": "28.1"}, {"sp": "N", "t": "Σωκράτης, ἐρωτηθεὶς τί θεός, εἶπε· Τὸ ἀθάνατον καὶ ἀίδιον.", "st": "28.1"}, {"sp": "N", "t": "Ἑρμῆς, ἐρωτηθεὶς τί θεός, εἶπεν· Ὁ τῶν ὅλων δημιουργός, σοφώτατος νοῦς καὶ ἀίδιος.", "st": "28.1"}, {"sp": "SEC", "t": "XXIX", "st": "29.1"}, {"sp": "N", "t": "ἑπτὰ πολυπλανέες κατ᾽ Ὀλύμπιον ἀστέρες οὐδὸν εἱλεῦνται, μετὰ τοῖσιν ἀεὶ περινίσεται αἰών· νυκτιφανὴς Μήνη, στυγνὸς Κρόνος, Ἥλιος ἡδύς, παστοφόρος Παφίη, θρασὺς Ἄρης, εὔπτερος Ἑρμῆς, καὶ Ζεὺς ἀρχιγένεθλος, ἀφ᾽ οὗ φύσις ἐβλάστησεν. οἱ δ᾽ αὐτοὶ μερόπων ἔλαχον γένος, ἔστι δ᾽ ἐν ἡμῖν Μήνη, Ζεύς, Ἄρης, Παφίη, Κρόνος, Ἥλιος, Ἑρμῆς. τοὔνεκ᾽ ἀπ᾽ αἰθερίου μεμερίσμεθα πνεύματος ἕλκειν δάκρυ, γέλωτα, χόλον, γένεσιν, λόγον, ὕπνον, ὄρεξιν. δάκρυ μέν ἐστι Κρόνος, Ζεὺς δὴ γένεσις, λόγος Ἑρμῆς, θυμὸς Ἄρης, Μήνη δ᾽ ἄρ᾽ ὕπνος, Κυθέρεια δ᾽ ὄρεξις, Ἠέλιος δὲ γέλως· τούτῳ γὰρ ἅπασα δικαίως καὶ θνητὴ διάνοια γελᾷ καὶ κόσμος ἀπείρων.", "st": "29.1"}], []);})();
